"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[44],{1499:(e,t,i)=>{i.d(t,{H3:()=>r,SP:()=>l,s_:()=>o,y4:()=>s});let n="physics4all-progress";function a(){return{completedChapters:{}}}function s(){try{let e=localStorage.getItem(n);if(!e)return a();return JSON.parse(e)}catch(e){return a()}}function o(e,t){let i=s();i.completedChapters[e]||(i.completedChapters[e]=[]),i.completedChapters[e].includes(t)||i.completedChapters[e].push(t),localStorage.setItem(n,JSON.stringify(i))}function r(e,t){var i,n;return null!=(n=null==(i=s().completedChapters[e])?void 0:i.includes(t))&&n}function l(e,t){var i,n;let a=null!=(n=null==(i=s().completedChapters[e])?void 0:i.length)?n:0;return 0===t?0:Math.round(a/t*100)}},9826:(e,t,i)=>{i.d(t,{aq:()=>l,Z7:()=>c,Jv:()=>h,lb:()=>d,ZY:()=>r,Pq:()=>o,tW:()=>n,yo:()=>s});let n=[{number:1,title:"Foundations",description:"Seeing like a physicist — numbers, proportion, and every physics phenomenon qualitatively (classes 1–7, compressed for adults)",color:"phase-1",audienceLevel:"Complete Beginner"},{number:2,title:"The First Full Tour",description:"All of physics once, at one-formula depth, plus the algebra to power it (classes 8–10, the Russian/Chinese model)",color:"phase-2",audienceLevel:"Beginner"},{number:3,title:"Quantitative Physics",description:"The theory pass with vectors and trigonometry (classes 11–12; H2/A-level/NCERT/AP level)",color:"phase-3",audienceLevel:"Intermediate"},{number:4,title:"University General Physics",description:"Calculus-based mechanics, electromagnetism, waves and special relativity (BSc years 1–2, the MIT 8.01→8.033 spine)",color:"phase-4",audienceLevel:"Intermediate"},{number:5,title:"The Theoretical Core",description:"Lagrangian mechanics, electrodynamics, quantum mechanics, statistical mechanics — plus math methods and computation",color:"phase-5",audienceLevel:"Advanced"},{number:6,title:"Advanced & Frontier",description:"Solid state, nuclear & particle, astrophysics & cosmology, general relativity, and the QFT gateway",color:"phase-6",audienceLevel:"Advanced"}],a=[{icon:"\xbd",colorHex:"#6366f1",difficulty:"beginner",estimatedHours:25,shortName:"Numbers"},{icon:"⚛",colorHex:"#8b5cf6",difficulty:"beginner",estimatedHours:20,shortName:"Phenomena"},{icon:"\uD83D\uDD2C",colorHex:"#a855f7",difficulty:"beginner",estimatedHours:12,shortName:"Method"},{icon:"x\xb2",colorHex:"#3b82f6",difficulty:"beginner",estimatedHours:35,shortName:"Algebra"},{icon:"F",colorHex:"#2563eb",difficulty:"beginner",estimatedHours:25,shortName:"Motion"},{icon:"\uD83C\uDF21",colorHex:"#0ea5e9",difficulty:"beginner",estimatedHours:15,shortName:"Heat"},{icon:"\uD83D\uDCA1",colorHex:"#06b6d4",difficulty:"beginner",estimatedHours:18,shortName:"Light"},{icon:"⚡",colorHex:"#0891b2",difficulty:"beginner",estimatedHours:22,shortName:"Electricity"},{icon:"☢",colorHex:"#0e7490",difficulty:"beginner",estimatedHours:12,shortName:"Atoms"},{icon:"sin",colorHex:"#f59e0b",difficulty:"intermediate",estimatedHours:40,shortName:"Precalc"},{icon:"→",colorHex:"#d97706",difficulty:"intermediate",estimatedHours:35,shortName:"Mechanics"},{icon:"PV",colorHex:"#b45309",difficulty:"intermediate",estimatedHours:18,shortName:"Thermal"},{icon:"λ",colorHex:"#eab308",difficulty:"intermediate",estimatedHours:20,shortName:"Waves"},{icon:"E",colorHex:"#ca8a04",difficulty:"intermediate",estimatedHours:30,shortName:"Fields"},{icon:"hν",colorHex:"#a16207",difficulty:"intermediate",estimatedHours:20,shortName:"Modern"},{icon:"∫",colorHex:"#ef4444",difficulty:"intermediate",estimatedHours:50,shortName:"Calculus"},{icon:"ma",colorHex:"#dc2626",difficulty:"intermediate",estimatedHours:40,shortName:"Mechanics I"},{icon:"∇",colorHex:"#b91c1c",difficulty:"intermediate",estimatedHours:40,shortName:"Vector Calc"},{icon:"∮",colorHex:"#f97316",difficulty:"intermediate",estimatedHours:35,shortName:"E&M I"},{icon:"ω",colorHex:"#ea580c",difficulty:"intermediate",estimatedHours:30,shortName:"Waves II"},{icon:"c",colorHex:"#c2410c",difficulty:"intermediate",estimatedHours:18,shortName:"Relativity"},{icon:"Ax",colorHex:"#9a3412",difficulty:"intermediate",estimatedHours:45,shortName:"DE & LinAlg"},{icon:"ℂ",colorHex:"#10b981",difficulty:"advanced",estimatedHours:45,shortName:"Math Methods"},{icon:"ℒ",colorHex:"#059669",difficulty:"advanced",estimatedHours:35,shortName:"Lagrangian"},{icon:"∇\xd7",colorHex:"#047857",difficulty:"advanced",estimatedHours:40,shortName:"Electrodynamics"},{icon:"ψ",colorHex:"#14b8a6",difficulty:"advanced",estimatedHours:40,shortName:"Quantum I"},{icon:"⟨ ⟩",colorHex:"#0d9488",difficulty:"advanced",estimatedHours:35,shortName:"Quantum II"},{icon:"S",colorHex:"#0f766e",difficulty:"advanced",estimatedHours:35,shortName:"Stat Mech"},{icon:">_",colorHex:"#115e59",difficulty:"advanced",estimatedHours:25,shortName:"Computation"},{icon:"Si",colorHex:"#a855f7",difficulty:"advanced",estimatedHours:30,shortName:"Solid State"},{icon:"q",colorHex:"#9333ea",difficulty:"advanced",estimatedHours:28,shortName:"Particles"},{icon:"★",colorHex:"#7e22ce",difficulty:"advanced",estimatedHours:28,shortName:"Astro"},{icon:"g",colorHex:"#6b21a8",difficulty:"advanced",estimatedHours:35,shortName:"GR"},{icon:"φ",colorHex:"#581c87",difficulty:"advanced",estimatedHours:25,shortName:"QFT"}],s=[{id:"numbers-measurement-proportion",number:1,title:"Numbers, Measurement & Proportion",description:"Rebuild arithmetic to automaticity and conquer proportional reasoning — the grammar of every physics formula. Math track I.",phase:1,chapters:[{id:"numbers-rebuilt",title:"Numbers Rebuilt",subtitle:"Place value, mental arithmetic, negative numbers, and the estimation habits every physicist runs on",sections:[{id:"place-value-and-the-number-line",title:"Place Value & the Number Line",content:'\n<p>Every number you will ever meet in physics lives in one system: <strong>positional notation</strong>. The numeral 4,072 doesn\'t contain a four, a zero, a seven, and a two — it contains 4 thousands, 0 hundreds, 7 tens, and 2 ones. Each step to the left multiplies the value of a digit by ten; each step to the right divides it by ten. That single idea — <strong>each place is worth ten times its neighbor</strong> — is the engine behind decimals, scientific notation, metric units, and orders of magnitude. Master it here and four later chapters get easier.</p>\n<p>The second mental tool is the <strong>number line</strong>: an infinite ruler with zero in the middle, positives stretching right, negatives stretching left. It turns arithmetic into geometry:</p>\n<ul>\n  <li><strong>Addition</strong> is a move to the right: 3 + 5 means "start at 3, walk 5 right."</li>\n  <li><strong>Subtraction</strong> is a move to the left — or better, a <strong>distance</strong>: 9 − 4 asks "how far from 4 to 9?"</li>\n  <li><strong>Comparing</strong> numbers means asking which sits further right: −2 is greater than −7 because it is closer to zero on the right side.</li>\n</ul>\n<div class="key-concept">\n  <h3>Key Concept: Numbers Are Positions, Operations Are Movements</h3>\n  <p>A thermometer, a voltmeter, an altitude readout — every instrument in physics is a number line with a label. When a temperature "drops 12 degrees" or a charge "goes negative," you are watching a point slide along a line. If you can see arithmetic as motion, half of introductory physics becomes familiar territory.</p>\n</div>\n<p>Worked example: a weather station reads −3\xb0C at dawn. By noon the temperature has risen 11 degrees. Where are we? Start at −3, walk 11 to the right: three steps bring you to 0, and the remaining eight land you at <strong>8\xb0C</strong>. No rule was memorized — you just moved along the line.</p>\n<p>Physics will soon hand you quantities spread across this line at wild scales: the charge of an electron near zero, the mass of the Earth far to the right. The number line is where you will hang all of them.</p>'},{id:"arithmetic-and-mental-math",title:"Arithmetic That Runs Itself",content:"\n<p>You are not relearning arithmetic to pass a test — you are rebuilding it to <strong>automaticity</strong>, so that when a physics problem needs 25 \xd7 12, your working memory stays free for the physics. The trick adults were rarely taught: fast arithmetic isn't about speed, it's about <strong>restructuring numbers before you compute</strong>.</p>\n<p>Three moves cover most mental math:</p>\n<ol>\n  <li><strong>Break numbers apart (decomposition).</strong> 25 \xd7 12 = 25 \xd7 10 + 25 \xd7 2 = 250 + 50 = <strong>300</strong>. You never multiplied anything harder than 25 \xd7 2.</li>\n  <li><strong>Compensate.</strong> 47 + 38: add 40 (getting 87), then take back 2 → <strong>85</strong>. Or 6 \xd7 99 = 6 \xd7 100 − 6 = <strong>594</strong>.</li>\n  <li><strong>Use friendly pairs.</strong> Numbers that make 10, 100, or 1000 love each other: 4 \xd7 25 = 100, 8 \xd7 125 = 1000, 2 \xd7 50 = 100. Spot them and rearrange: 4 \xd7 7 \xd7 25 = (4 \xd7 25) \xd7 7 = 700.</li>\n</ol>\n<div class=\"analogy\">\n  <h3>Analogy: Touch Typing for Numbers</h3>\n  <p>A touch typist doesn't think about individual keys; their fingers handle the letters while their mind composes the sentence. That's the goal for arithmetic. In a physics problem about a falling ball, the thinking should go into \"what does gravity do here?\" — not into 4.9 \xd7 4. Fluency isn't a party trick; it's freed-up brainpower.</p>\n</div>\n<p>Worked example, physics-flavored: a car travels at 72 km per hour. How far does it go in 40 minutes? Restructure: 40 minutes is ⅔ of an hour. One third of 72 is 24, so two thirds is <strong>48 km</strong>. Notice what happened — the \"hard\" division became a friendly fraction because you reshaped the problem first.</p>\n<p>Practice deliberately for a week or two: double and halve numbers, multiply by 5 (multiply by 10, halve it), multiply by 25 (multiply by 100, quarter it). These aren't tricks to collect; they're the same idea — <strong>ten is the hub, and everything routes through it</strong>.</p>"},{id:"negative-numbers",title:"Below Zero: Negative Numbers",content:'\n<p>Negative numbers make many adults quietly nervous, and physics uses them <em>constantly</em>: negative charge, negative velocity, negative energy, temperatures below zero. Here\'s the reframe that makes them tame: a negative number is not a "weird number" — it\'s an ordinary size pointing the <strong>opposite direction</strong>. The minus sign is a direction flag.</p>\n<p>With that picture, the rules stop being arbitrary:</p>\n<ul>\n  <li><strong>Adding a negative = subtracting.</strong> Gaining a debt of 5 dollars is losing 5 dollars: 8 + (−5) = 3.</li>\n  <li><strong>Subtracting a negative = adding.</strong> Removing a debt makes you richer: 8 − (−5) = 13.</li>\n  <li><strong>Multiplying flips or keeps direction.</strong> Multiplying by −1 means "reverse." So (−3) \xd7 4 = −12 (a reversal), and (−3) \xd7 (−4) = +12 — reversing a reversal points you forward again. Two wrongs don\'t make a right, but two reversals do.</li>\n</ul>\n<div class="key-concept">\n  <h3>Key Concept: Sign = Direction, Size = Magnitude</h3>\n  <p>Physicists split every signed quantity into two pieces: its <strong>magnitude</strong> (how much) and its <strong>sign</strong> (which way). A velocity of −20 m/s isn\'t slower than +20 m/s — it\'s just as fast, headed the other way. When physics answers come out negative, the number is telling you a direction, not an error.</p>\n</div>\n<p>Worked example: a diver is 6 m below the surface (position −6 m) and descends another 9 m. New position: −6 + (−9) = <strong>−15 m</strong>. Now she rises 4 m: −15 + 4 = <strong>−11 m</strong>. The arithmetic is just walking the number line; the signs track "up versus down" for you automatically.</p>\n<div class="did-you-know">\n  <h4>Did You Know?</h4>\n  <p>European mathematicians resisted negative numbers into the 1700s, calling them "absurd" and "fictitious." Meanwhile, Chinese mathematicians had computed with them for over 1,500 years, using red rods for positives and black rods for negatives. If negatives feel unnatural, you\'re in historically excellent company — and, like the holdouts, you\'ll get over it.</p>\n</div>\n<p>One warning worth its own sentence: −3\xb2 means −(3\xb2) = −9, while (−3)\xb2 = +9. The square binds tighter than the minus. That distinction will matter the first time you plug a negative velocity into an energy formula.</p>'},{id:"order-of-operations",title:"Order of Operations",content:"\n<p>Order of operations is not a schoolroom ritual — it's the <strong>grammar that makes formulas unambiguous</strong>. Physics is written in this grammar. The kinetic-energy formula E = \xbdmv\xb2 only means what it should because everyone agrees the square applies to v alone, before the multiplication. Misread the order, and every formula you meet will silently betray you.</p>\n<p>The hierarchy, from strongest binding to weakest:</p>\n<ol>\n  <li><strong>Parentheses</strong> — whatever is grouped happens first.</li>\n  <li><strong>Exponents and roots</strong> — squares, cubes, square roots.</li>\n  <li><strong>Multiplication and division</strong> — equal rank, left to right.</li>\n  <li><strong>Addition and subtraction</strong> — equal rank, left to right.</li>\n</ol>\n<p>Two clarifications that fix most adult confusion:</p>\n<ul>\n  <li>Multiplication does <strong>not</strong> beat division (nor addition beat subtraction). They're peers, processed left to right: 12 \xf7 3 \xd7 2 = 4 \xd7 2 = 8, not 12 \xf7 6 = 2.</li>\n  <li>A fraction bar is <strong>invisible parentheses</strong> around top and bottom. The expression (6 + 4) \xf7 (2 + 3) written as a tall fraction hides both sets of brackets in the bar — evaluate top and bottom fully before dividing.</li>\n</ul>\n<p>Worked example with a real formula. Kinetic energy: E = \xbd \xd7 m \xd7 v\xb2. For m = 2 kg and v = 10 m/s:</p>\n<ul>\n  <li>Exponent first: v\xb2 = 10\xb2 = 100</li>\n  <li>Then multiply left to right: \xbd \xd7 2 \xd7 100 = 1 \xd7 100 = <strong>100 joules</strong></li>\n</ul>\n<p>The classic wrong turn is squaring (\xbd \xd7 2 \xd7 10) = 10 into 100... which happens to give 100 here — a cruel coincidence. Try v = 4: correct is \xbd \xd7 2 \xd7 16 = 16 J; the wrong order gives (\xbd \xd7 2 \xd7 4)\xb2 = 16 too! Fine, this formula is forgiving with m = 2. Take m = 3, v = 4: correct is \xbd \xd7 3 \xd7 16 = 24 J; wrong order gives (\xbd \xd7 3 \xd7 4)\xb2 = 36 J. Different answers, real consequences.</p>\n<div class=\"key-concept\">\n  <h3>Key Concept: When in Doubt, Add Parentheses</h3>\n  <p>Parentheses are free. Writing (\xbd \xd7 m) \xd7 (v\xb2) costs nothing and removes all ambiguity — for you, for your calculator, and later for your code. Professional physicists over-parenthesize all the time; ambiguity is the only sin.</p>\n</div>"},{id:"estimation-and-rounding",title:"Estimation & Rounding",content:"\n<p>Here is a professional secret: physicists estimate <em>before</em> they calculate, every single time. An estimate is a cheap insurance policy — if your careful calculation says a bicycle travels 4,000 km in an hour, the rough estimate you made first is what catches the error. Estimation is not laziness; it is <strong>quality control for thinking</strong>.</p>\n<p>Rounding is the tool. The rule you remember (round the digit up if the next digit is 5 or more) is fine, but the skill is choosing <strong>what to round to</strong>:</p>\n<ul>\n  <li><strong>Round to one or two significant digits</strong> for a quick check: 387 \xd7 52 ≈ 400 \xd7 50 = 20,000. (True answer: 20,124. The estimate did its job.)</li>\n  <li><strong>Round in opposite directions when you can.</strong> Rounding 387 up and 52 down means the errors partly cancel — that's why 400 \xd7 50 landed so close.</li>\n  <li><strong>Track whether your estimate is high or low.</strong> 9.8 rounded to 10 makes gravity slightly \"too strong,\" so your estimated fall time will come out slightly short. Knowing the direction of the error is half of error analysis, which you'll meet formally later.</li>\n</ul>\n<div class=\"analogy\">\n  <h3>Analogy: The Restaurant Bill</h3>\n  <p>You don't add a dinner bill to the cent in your head — you round each dish to the nearest dollar and keep a running total. If the waiter's total is wildly off from yours, you check the itemized bill. Physicists treat every calculation like that bill: the rough total comes first, and the precise answer must agree with it or someone has made a mistake.</p>\n</div>\n<p>Worked example: roughly how many seconds are in a year? Estimate: 365 days ≈ 400 days is too crude; keep 365. Each day has 24 hours ≈ 25; each hour has 3,600 seconds ≈ 3,500. So 365 \xd7 25 ≈ 9,000 hours, and 9,000 \xd7 3,500 ≈ 31,500,000 — about <strong>3 \xd7 10⁷ seconds</strong>. The exact value is 31,536,000. Our two-minute estimate landed within 1%.</p>\n<p>That habit — <em>estimate, then compute, then compare</em> — will run underneath everything you do in this course, and it becomes a superpower in Chapter 4 when we scale it up to Fermi estimation.</p>"}],quiz:[{question:"The temperature is −7\xb0C and rises by 12 degrees. What is it now, and what mental model gets you there fastest?",options:["5\xb0C — start at −7 on the number line and move 12 to the right","−19\xb0C — negative numbers make additions negative","19\xb0C — drop the minus sign and add","−5\xb0C — move 12 to the left from −7"],correctIndex:0,explanation:"Addition is a rightward move on the number line: from −7, seven steps reach 0 and the remaining five land at +5\xb0C. Seeing signed arithmetic as motion along a line is exactly how physics treats temperature, position, and velocity changes."},{question:"What is 12 \xf7 3 \xd7 2?",options:["2, because multiplication is done before division","8, because multiplication and division have equal rank and are done left to right","18, because you always work right to left","2, because the 3 \xd7 2 is implicitly grouped"],correctIndex:1,explanation:"Multiplication and division are peers, evaluated left to right: 12 \xf7 3 = 4, then 4 \xd7 2 = 8. The belief that multiplication 'beats' division is one of the most common adult misconceptions — and formulas like v = d \xf7 t \xd7 conversion factors will punish it."},{question:"Using E = \xbdmv\xb2 with m = 3 kg and v = 4 m/s, what is the kinetic energy?",options:["36 J — compute \xbd \xd7 3 \xd7 4 first, then square","6 J — square applies to the whole right side","24 J — square v first (v\xb2 = 16), then multiply: \xbd \xd7 3 \xd7 16","48 J — ignore the \xbd since it is less than 1"],correctIndex:2,explanation:"Exponents bind before multiplication, and the square applies only to v. So v\xb2 = 16, then \xbd \xd7 3 \xd7 16 = 24 J. Squaring the whole product (36 J) is the classic order-of-operations error, and it produces confidently wrong physics."},{question:"You estimate 387 \xd7 52 by rounding to 400 \xd7 50 = 20,000. The exact answer is 20,124. Why did this estimate land so close?",options:["Rounding always produces errors under 1%","One number was rounded up and the other down, so the errors partly cancelled","Multiplication is immune to rounding errors","It was luck — estimates cannot be systematically accurate"],correctIndex:1,explanation:"Rounding 387 up (+3%) and 52 down (−4%) pushes the product in opposite directions, so the errors largely cancel. Deliberately rounding in opposite directions is a professional estimator's habit — and tracking the direction of errors is the seed of physics error analysis."},{question:"What is (−3) \xd7 (−4), and what does the sign rule mean?",options:["−12 — two negatives stay negative","−7 — multiply then subtract","+12, but only as an arbitrary convention","+12 — multiplying by a negative means reversing direction, and two reversals point forward again"],correctIndex:3,explanation:"Multiplying by −1 means 'reverse direction' on the number line. Reversing twice restores the original direction, so (−3) \xd7 (−4) = +12. This is not an arbitrary rule: physics uses it whenever a reversed velocity or force is reversed again."}]},{id:"fractions-decimals-percent",title:"Fractions, Decimals & Percent",subtitle:"Three costumes for the same idea — crossing the rational-number wall that stops most adult relearners",sections:[{id:"what-a-fraction-really-is",title:"What a Fraction Really Is",content:"\n<p>Research on adult numeracy keeps finding the same bottleneck: fractions. Educators call it the <strong>rational-number wall</strong>, and it's the single best-documented gap between people who find physics readable and people who find it hostile. So let's rebuild the concept from the floor.</p>\n<p>A fraction is <strong>one number, not two</strong>. The symbol \xbe is not \"a 3 and a 4 in a costume\" — it is a single point on the number line, sitting three quarters of the way from 0 to 1. The bar means division: \xbe literally equals 3 \xf7 4 = 0.75. Everything else follows from three readings, and fluency means switching between them freely:</p>\n<ul>\n  <li><strong>Part of a whole:</strong> \xbe of a pizza — 3 slices when the pizza is cut into 4.</li>\n  <li><strong>A division:</strong> 3 chocolate bars shared among 4 people — each gets \xbe of a bar.</li>\n  <li><strong>A ratio or rate:</strong> 3 parts salt to 4 parts water; 3 meters per 4 seconds. <em>This</em> reading is the one physics runs on.</li>\n</ul>\n<div class=\"key-concept\">\n  <h3>Key Concept: Equivalent Fractions Are the Same Point</h3>\n  <p>\xbd = 2⁄4 = 50⁄100 = 0.5. Different names, one point on the line. Multiplying top and bottom by the same number doesn't change the value, because you're multiplying by something equal to 1 (like 2⁄2). Hold onto that phrase — <strong>multiplying by a clever form of 1</strong> — because in Chapter 5 it becomes the entire method of unit conversion.</p>\n</div>\n<p>Worked example: which is larger, 5⁄8 or 2⁄3? Rewrite both over 24 (the least common multiple of 8 and 3): 5⁄8 = 15⁄24 and 2⁄3 = 16⁄24. So <strong>2⁄3 is larger</strong>, by exactly 1⁄24. No decimals needed — though converting works too: 0.625 versus 0.667.</p>\n<p>Why physics cares: nearly every formula you'll meet is a fraction in disguise. Speed is distance over time. Density is mass over volume. Pressure is force over area. If fractions feel like fog, those formulas feel like fog. Clear the fog here, and Chapter 3 will feel like revision instead of a wall.</p>"},{id:"operations-on-fractions",title:"Adding, Subtracting, Multiplying, Dividing",content:'\n<p>The four operations on fractions each have a <em>reason</em>, and knowing the reasons beats memorizing the recipes — recipes evaporate under exam pressure; reasons don\'t.</p>\n<p><strong>Addition and subtraction need matching pieces.</strong> You can\'t add 1⁄2 + 1⁄3 directly, for the same reason you can\'t add 2 meters + 3 feet: the units differ. Halves and thirds are different sizes of piece. Convert both to sixths — pieces that fit both: 1⁄2 = 3⁄6 and 1⁄3 = 2⁄6, so the sum is <strong>5⁄6</strong>. The "common denominator" is just a common unit.</p>\n<p><strong>Multiplication means "of."</strong> \xbd \xd7 \xbe asks: what is half <em>of</em> three quarters? Take \xbe, cut it in half: 3⁄8. The recipe (multiply tops, multiply bottoms) falls straight out. Notice the humbling consequence: multiplying by a fraction smaller than 1 makes things <em>smaller</em>. Adults who learned "multiplication makes bigger" in childhood trip on this for years.</p>\n<p><strong>Division asks "how many fit?"</strong> 3 \xf7 \xbd asks how many half-pizzas fit in 3 pizzas: 6. Hence dividing by a fraction multiplies by its reciprocal: 3 \xf7 \xbd = 3 \xd7 2 = 6. Likewise \xbe \xf7 \xbc = \xbe \xd7 4 = 3 — three quarter-pieces fit in three-quarters. Dividing by a small number gives a big answer, a fact with deep physics echoes (huge pressure from a small area; huge acceleration from a small mass).</p>\n<div class="analogy">\n  <h3>Analogy: Coins Before Adding</h3>\n  <p>You can\'t add 3 dimes and 2 quarters by writing "5 somethings" — you convert both to cents (30 + 50 = 80) first. Common denominators are exactly that conversion. Nobody finds the coin version hard; the fraction version is the same move with worse marketing.</p>\n</div>\n<p>Worked example: a rod of length ⅚ m has \xbc of it painted. How much rod is painted? "\xbc of ⅚" → \xbc \xd7 ⅚ = 5⁄24 m ≈ 0.21 m. And how much is unpainted? 1 − \xbc = \xbe of it: \xbe \xd7 ⅚ = 15⁄24 = ⅝ m. Check: 5⁄24 + 15⁄24 = 20⁄24 = ⅚ ✓. That closing check — do the parts rebuild the whole? — is a habit worth keeping for life.</p>'},{id:"decimals",title:"Decimals: Fractions in Base Ten",content:'\n<p>A decimal is not a new kind of number — it\'s a fraction whose denominator is a power of ten, written using the place-value system you rebuilt in Chapter 1. The places right of the decimal point continue the tenfold pattern: tenths, hundredths, thousandths. So 0.375 means 3⁄10 + 7⁄100 + 5⁄1000 = 375⁄1000 = ⅜.</p>\n<p>Why science runs on decimals rather than fractions: <strong>decimals compare instantly</strong>. Which is bigger, 7⁄16 or 4⁄9? Not obvious. Which is bigger, 0.4375 or 0.444...? Read left to right, done. Instruments agree — every digital meter, scale, and sensor speaks decimal.</p>\n<p>The three skills to make automatic:</p>\n<ul>\n  <li><strong>Multiplying and dividing by 10, 100, 1000 just slides the decimal point.</strong> 3.75 \xd7 100 = 375; 3.75 \xf7 10 = 0.375. Nothing is really moving but your bookkeeping — each slide is a place-value shift. This is the mechanical heart of metric conversions (2.5 km = 2,500 m) and scientific notation.</li>\n  <li><strong>Converting a fraction: just divide.</strong> ⅝ = 5 \xf7 8 = 0.625. Some fractions terminate (⅝ = 0.625), others repeat forever (⅓ = 0.333...). A fraction terminates exactly when its denominator\'s only prime factors are 2 and 5 — the primes of ten.</li>\n  <li><strong>Comparing: pad with zeros and read.</strong> Is 0.72 bigger than 0.598? Write 0.720 versus 0.598: yes. The common adult error is thinking "598 is longer than 72, so 0.598 wins" — length of digits means nothing; position means everything.</li>\n</ul>\n<div class="did-you-know">\n  <h4>Did You Know?</h4>\n  <p>Decimal notation is startlingly recent. Simon Stevin only popularized decimal fractions in Europe in 1585, in a pamphlet promising to teach "all computations... by whole numbers without fractions." Newton had decimals for barely a century of mathematical tradition when he wrote the Principia; you have five.</p>\n</div>\n<p>Worked example: a lab balance reads 0.048 kg, and a second object reads 0.31 kg. Total mass? Line up the decimal points — 0.048 + 0.310 = <strong>0.358 kg</strong>. Lining up decimal points is lining up place values: tenths under tenths, hundredths under hundredths. Misalignment is the number-one decimal arithmetic error, and in a lab notebook it produces masses that are wrong by a factor of ten.</p>'},{id:"percent",title:"Percent: The Universal Comparison",content:'\n<p><strong>Percent</strong> means "per hundred" — that\'s the whole definition. 35% is 35⁄100 is 0.35. It exists because comparing raw fractions is awkward (is 17⁄40 better than 22⁄50?), while rescaling everything to a denominator of 100 makes comparison instant (42.5% versus 44%).</p>\n<p>The one move that unlocks every percent problem: <strong>translate the percent into a decimal multiplier, and the word "of" into \xd7</strong>.</p>\n<ul>\n  <li>30% of 250 → 0.30 \xd7 250 = <strong>75</strong></li>\n  <li>A 15% increase → multiply by 1.15 (the original 100% plus 15% more)</li>\n  <li>A 20% decrease → multiply by 0.80 (only 80% remains)</li>\n</ul>\n<p>That multiplier view solves the problems that ambush people. If a $200 jacket is marked up 25% and then discounted 25%, is it back to $200? No: 200 \xd7 1.25 \xd7 0.75 = $187.50. The second 25% acted on a <em>bigger</em> base than the first. <strong>Percent changes don\'t cancel, because percent is always relative to the current value.</strong></p>\n<div class="key-concept">\n  <h3>Key Concept: Always Ask "Percent of What?"</h3>\n  <p>A percent without a stated base is meaningless. "Efficiency rose 5%" — of the original efficiency, or 5 percentage points? Physics is fussy about this: when you later compute that a heat engine is 35% efficient or a measurement has 2% uncertainty, the base (energy input; measured value) is always explicit. Building that reflex now costs minutes and saves whole homework sets.</p>\n</div>\n<p>Worked examples:</p>\n<ol>\n  <li>A battery\'s charge drops from 80% to 60%. That\'s a fall of 20 <em>percentage points</em>, but a fall of 20⁄80 = <strong>25 percent</strong> of the charge it had. Both statements are true; they answer different questions.</li>\n  <li>Reverse percentage — a price after a 20% discount is $64. Original? The $64 is 80% of it, so original = 64 \xf7 0.80 = <strong>$80</strong>. Dividing by the multiplier undoes it — the same undo move you\'ll use to rearrange physics formulas.</li>\n</ol>\n<p>In physics, percent is the language of efficiency, uncertainty, and composition (the air is 21% oxygen). It\'s a small idea used daily forever.</p>'},{id:"three-faces-one-number",title:"Conversions: Three Faces, One Number",content:'\n<p>Here is the summit of the rational-number wall: seeing instantly that ⅗, 0.6, and 60% are <strong>one number wearing three costumes</strong>. Fluency means converting between all three without ceremony, and choosing the costume that makes the current problem easiest.</p>\n<table>\n  <thead>\n    <tr><th>Fraction</th><th>Decimal</th><th>Percent</th><th>Worth memorizing because...</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>\xbd</td><td>0.5</td><td>50%</td><td>the everywhere-benchmark</td></tr>\n    <tr><td>\xbc , \xbe</td><td>0.25, 0.75</td><td>25%, 75%</td><td>quarters rule money, angles, time</td></tr>\n    <tr><td>⅓ , ⅔</td><td>0.333..., 0.667</td><td>33⅓%, 66⅔%</td><td>the repeating pair everyone rounds</td></tr>\n    <tr><td>⅕ , ⅖ , ⅗ , ⅘</td><td>0.2, 0.4, 0.6, 0.8</td><td>20–80%</td><td>fifths are the metric-friendly family</td></tr>\n    <tr><td>⅛</td><td>0.125</td><td>12.5%</td><td>halving \xbc; appears in energy problems</td></tr>\n    <tr><td>1⁄10</td><td>0.1</td><td>10%</td><td>the decimal system itself</td></tr>\n  </tbody>\n</table>\n<p>The conversion rules are two arrows: <strong>fraction → decimal</strong> is a division (⅗ = 3 \xf7 5 = 0.6); <strong>decimal → percent</strong> slides the point two places right (0.6 = 60%). Reverse the arrows to go back. That\'s the entire machinery.</p>\n<p>Which costume when?</p>\n<ul>\n  <li><strong>Fractions</strong> for exact reasoning and cancellation: ⅓ \xd7 3 = 1 exactly, while 0.333 \xd7 3 = 0.999.</li>\n  <li><strong>Decimals</strong> for comparing, measuring, and calculators.</li>\n  <li><strong>Percents</strong> for communicating to humans.</li>\n</ul>\n<div class="analogy">\n  <h3>Analogy: One Person, Three Outfits</h3>\n  <p>The same person wears gym clothes, work clothes, and a wedding suit — different contexts, one identity. Your job is to recognize the person regardless of outfit. When a physics solution flips from "the ball loses \xbc of its energy" to "0.75 of the energy remains" to "75% efficiency," it\'s one fact changing clothes mid-sentence. Textbooks do this without warning; from now on, so can you.</p>\n</div>\n<p>Worked example: light passes through two filters. The first transmits ⅔ of the light, the second 75%. Total transmission? Same costume first: ⅔ \xd7 \xbe = \xbd = 0.5 = <strong>50%</strong>. Pick fractions, and the cancellation is effortless.</p>'}],quiz:[{question:"Which of these is NOT equal to the others?",options:["⅗","0.6","60%","6⁄100"],correctIndex:3,explanation:"⅗ = 3 \xf7 5 = 0.6 = 60% — one number in three costumes. But 6⁄100 = 0.06 = 6%, ten times smaller. Reading 0.6 as 6⁄100 (instead of 6⁄10) is a classic place-value slip: the first digit after the point counts tenths, not hundredths."},{question:"Why does 1⁄2 + 1⁄3 require a common denominator?",options:["It's a convention with no deeper reason","Halves and thirds are different-sized pieces — like meters and feet, they must be converted to a common unit (sixths) before adding","Because addition of fractions is only defined for even denominators","To make the answer smaller than 1"],correctIndex:1,explanation:"Adding requires matching units. 1⁄2 = 3⁄6 and 1⁄3 = 2⁄6, so the sum is 5⁄6. Adding tops and bottoms directly (giving 2⁄5) is like adding 3 dimes and 2 quarters and calling it '5 coins worth' — the pieces were never the same size."},{question:"A $200 item is marked up 25%, then discounted 25%. What is the final price?",options:["$200 — the changes cancel","$187.50 — the discount acts on the larger, marked-up price","$150 — subtract 50% total","$212.50 — percents always compound upward"],correctIndex:1,explanation:"200 \xd7 1.25 = 250, then 250 \xd7 0.75 = 187.50. Percent changes never cancel because each acts on the current value, not the original. The multiplier view (\xd71.25, \xd70.75) makes this visible at a glance — and it is exactly how compounding works in radioactive decay and interest alike."},{question:"What is 3 \xf7 \xbd, and what question does it answer?",options:["1.5 — dividing always makes numbers smaller","6 — it asks how many half-sized pieces fit into 3 wholes","⅙ — flip the first fraction and multiply","5 — subtract the denominator"],correctIndex:1,explanation:"Division asks 'how many fit?' Six halves fit into 3, so 3 \xf7 \xbd = 3 \xd7 2 = 6. Dividing by a number smaller than 1 gives a larger answer — the same logic that later explains why a small area under a force produces enormous pressure (P = F \xf7 A)."},{question:"Two filters transmit ⅔ and 75% of light respectively. What fraction of light passes through both?",options:["\xbd — convert to one form and multiply: ⅔ \xd7 \xbe = \xbd","About 1.42 — add the two transmissions","⅔ — the weaker filter decides alone","5⁄7 — average the two fractions"],correctIndex:0,explanation:"Successive 'of' operations multiply: \xbe of ⅔ of the light survives, and ⅔ \xd7 \xbe = 6⁄12 = \xbd = 50%. Converting 75% into the fraction costume first makes the cancellation trivial — choosing the convenient representation is the real skill being tested."}]},{id:"ratio-rate-proportion",title:"Ratio, Rate & Proportion",subtitle:"The single most important chapter in the math track — the reasoning pattern behind speed, density, and nearly every physics formula",sections:[{id:"ratios-and-rates",title:"Ratios & Rates: Comparing by Division",content:'\n<p>If this course has one chapter you must not skim, it\'s this one. Research on physics learning is blunt: students who can reason proportionally can learn physics, and students who can\'t, struggle everywhere — because <strong>most physics formulas are ratio statements</strong>. Speed, density, pressure, resistance, concentration: all of them are "this per that."</p>\n<p>There are two ways to compare quantities. <strong>Comparison by subtraction</strong> asks "how much more?" — a 6 kg dog outweighs a 2 kg cat by 4 kg. <strong>Comparison by division</strong> asks "how many times as much?" — the dog is 3 times the cat\'s mass. That second kind is a <strong>ratio</strong>, and it has a superpower: it survives rescaling. Photograph the dog and cat at half size and the 4 kg difference becomes meaningless, but the 3-to-1 ratio still holds. Ratios capture <em>structure</em>; differences capture only amounts.</p>\n<p>A <strong>rate</strong> is a ratio between different kinds of quantity: 150 km per 2 hours, 30 grams per 3 cm\xb3, $12 per kg. The most useful form is the <strong>unit rate</strong> — how much per <em>one</em>: 75 km per hour, 10 g per cm\xb3. Finding the unit rate first, then scaling to whatever you need, is called the <strong>unitary method</strong>, and it is quietly the most reliable problem-solving algorithm in elementary math:</p>\n<ol>\n  <li>5 identical books cost $60. Cost per book: 60 \xf7 5 = $12.</li>\n  <li>Cost of 8 books: 8 \xd7 12 = <strong>$96</strong>.</li>\n</ol>\n<p>Down to one, up to many. It never fails, and it works unchanged in physics: if a pump moves 240 liters in 8 minutes, it moves 30 L per minute, so 11 minutes moves 330 L.</p>\n<div class="key-concept">\n  <h3>Key Concept: A Rate Is a Ratio With a Physical Meaning</h3>\n  <p>"Per" is the most important small word in science. Speed is kilometers <em>per</em> hour. Density is grams <em>per</em> cubic centimeter. Power is joules <em>per</em> second. Whenever you see "per," you are looking at a division — and the number tells you how much of the first thing rides along with one unit of the second. Learn to hear "per" as \xf7 and half the formulas in this course become sentences you can read.</p>\n</div>'},{id:"bar-models",title:"Bar Models: Seeing Ratio Problems",content:"\n<p>Singapore's math curriculum — a perennial world number one — teaches ratio with a deceptively simple drawing tool: the <strong>bar model</strong>. Instead of jumping to equations, you draw rectangles whose lengths represent quantities. The picture does the algebra for you, and for adults it's a genuinely faster way to crack word problems.</p>\n<p><strong>Worked example 1.</strong> Alex and Ben share $120 in the ratio 3 : 2. How much does each get?</p>\n<p>Draw Alex as 3 equal boxes and Ben as 2 equal boxes — 5 boxes total sharing $120. Each box is 120 \xf7 5 = $24. So Alex gets 3 \xd7 24 = <strong>$72</strong> and Ben gets 2 \xd7 24 = <strong>$48</strong>. The bar model turned an algebra problem into counting boxes.</p>\n<p><strong>Worked example 2 (harder).</strong> After spending ⅖ of her money, Maya has $36 left. How much did she start with?</p>\n<p>Draw her money as 5 boxes; she spent 2, so 3 boxes remain and equal $36. One box = 12; five boxes = <strong>$60</strong>. Notice how the model dissolves the usual panic of \"reverse\" problems — the leftover is <em>visibly</em> 3 boxes, so you never mistakenly compute ⅖ of 36.</p>\n<div class=\"analogy\">\n  <h3>Analogy: Scaffolding, Not a Crutch</h3>\n  <p>The bar model is scaffolding for the equation x + \xb2⁄₃x = 120 you'll write comfortably after the algebra course (Subject 4). Scaffolding isn't cheating — it's how the building goes up. Even physicists sketch before they calculate; a force diagram is nothing but a grown-up bar model for vectors.</p>\n</div>\n<p><strong>Worked example 3, physics-flavored.</strong> Bronze is 7 parts copper to 1 part tin by mass. How much copper is in 4 kg of bronze? Eight boxes total; each box is 4 \xf7 8 = 0.5 kg; copper is 7 boxes = <strong>3.5 kg</strong>. Mixture and alloy problems — and later, mole-ratio chemistry and circuit current-splitting — are exactly this picture.</p>\n<p>Draw bars until you don't need to. The day the boxes appear in your head unbidden, you have acquired what teachers call proportional reasoning — and you'll spend the rest of this curriculum cashing it in.</p>"},{id:"direct-and-inverse-proportion",title:"Direct & Inverse Proportion",content:"\n<p>Two quantities are <strong>directly proportional</strong> when doubling one doubles the other — their <em>ratio</em> stays fixed. Distance at constant speed is the classic case: twice the time, twice the distance; d \xf7 t never changes. Writing it generally: y = kx for some constant k. The graph is a straight line <strong>through the origin</strong> — zero time, zero distance.</p>\n<p>Two quantities are <strong>inversely proportional</strong> when doubling one <em>halves</em> the other — their <em>product</em> stays fixed. Sharing a fixed job is the classic case: twice the workers, half the time; workers \xd7 time is constant. Generally: y = k \xf7 x, or equivalently x\xb7y = k.</p>\n<table>\n  <thead>\n    <tr><th></th><th>Direct (y = kx)</th><th>Inverse (x\xb7y = k)</th></tr>\n  </thead>\n  <tbody>\n    <tr><td><strong>Double x...</strong></td><td>y doubles</td><td>y halves</td></tr>\n    <tr><td><strong>What's constant</strong></td><td>the ratio y \xf7 x</td><td>the product x\xb7y</td></tr>\n    <tr><td><strong>Physics examples</strong></td><td>distance & time (fixed speed); mass & volume (fixed density); voltage & current (fixed resistance — Ohm's law)</td><td>pressure & volume of a gas (Boyle's law); speed & travel time (fixed distance); current & resistance (fixed voltage)</td></tr>\n  </tbody>\n</table>\n<p><strong>Worked example (direct):</strong> 3 m of wire has mass 45 g. Mass of 8 m? Unit rate: 15 g per meter, so 8 \xd7 15 = <strong>120 g</strong>.</p>\n<p><strong>Worked example (inverse):</strong> a journey takes 6 hours at 40 km/h. How long at 60 km/h? The product speed \xd7 time is the fixed distance: 40 \xd7 6 = 240 km. Then 240 \xf7 60 = <strong>4 hours</strong>. Speeding up by half (\xd71.5) cut the time by the same factor (\xf71.5).</p>\n<div class=\"key-concept\">\n  <h3>Key Concept: Ask \"What Stays Constant?\"</h3>\n  <p>This question is the master key. Every proportion problem — and a shocking fraction of physics problems — is solved by identifying the invariant. Fixed ratio → direct. Fixed product → inverse. Later, whole subjects hang on invariants: energy conservation, momentum conservation, Boyle's law. Chapter 3 of a math course is where physicists are actually made.</p>\n</div>\n<p>One caution: not every increasing relationship is proportional. A taxi fare with a $5 flag-fall rises with distance but isn't proportional to it — its graph misses the origin, and doubling the distance doesn't double the fare. Always test with the doubling question before you deploy proportion machinery.</p>"},{id:"speed-distance-time",title:"Speed, Distance & Time",content:'\n<p>Your first real physics formula, arriving a full phase ahead of the physics course: <strong>speed = distance \xf7 time</strong>, or v = d \xf7 t. It\'s nothing but a unit rate — kilometers per one hour — which is why it belongs in this chapter. Every technique you\'ve built (unitary method, ratios, proportion) now gets a test drive on the most-used relationship in mechanics.</p>\n<p>One relationship, three rearrangements:</p>\n<ul>\n  <li>v = d \xf7 t — how fast? (unit rate)</li>\n  <li>d = v \xd7 t — how far? (rate \xd7 how long)</li>\n  <li>t = d \xf7 v — how long? (distance shared out at v per hour)</li>\n</ul>\n<p>Don\'t memorize a triangle diagram; instead <em>hear the sentence</em>: "at 60 km per hour, each hour delivers 60 km." From that sentence all three forms are obvious.</p>\n<p><strong>Worked example 1.</strong> A train covers 210 km in 2 h 30 min. Average speed? Convert time to hours: 2.5 h. Then v = 210 \xf7 2.5 = <strong>84 km/h</strong>. (Mixed units — kilometers with minutes — are the number-one source of wrong answers; convert first, always.)</p>\n<p><strong>Worked example 2 (the classic trap).</strong> A cyclist rides 30 km out at 15 km/h and returns at 10 km/h. Average speed for the round trip? <em>Not</em> 12.5. Average speed is total distance \xf7 total time. Out: 30 \xf7 15 = 2 h. Back: 30 \xf7 10 = 3 h. Total: 60 km in 5 h → <strong>12 km/h</strong>. You can\'t average rates directly, because the slower leg eats more time and drags the average toward itself.</p>\n<div class="did-you-know">\n  <h4>Did You Know?</h4>\n  <p>"Speed" hides an assumption: that it was constant. Real trips speed up and slow down, so v = d \xf7 t gives the <em>average</em> speed. The instant-by-instant speed — what the speedometer shows — needs the idea of a limit, and chasing that idea rigorously is precisely what forced Newton to invent calculus. You are, right now, one honest question away from calculus.</p>\n</div>\n<p>Sanity-check habit: before computing, estimate. A 210 km trip in "about two and a half hours" should be "a bit over 80 km/h" — brisk highway driving, plausible. If your calculation had produced 840, the estimate would have flagged the slipped decimal instantly. Numbers in physics always mean something; check them against the world.</p>'},{id:"density-as-a-ratio",title:"Density: Your Second Physics Formula",content:'\n<p>Why do density problems feel hard for so many students? Not because density is deep — because density is a <em>ratio</em>, and ratio reasoning is exactly the skill schools under-built. You\'ve now built it, so let\'s collect the reward.</p>\n<p><strong>Density is mass per unit volume:</strong> ρ = m \xf7 V (physicists write density with the Greek letter ρ, "rho"). It answers: how much stuff is packed into each cubic centimeter? Water: 1 g/cm\xb3. Iron: 7.9 g/cm\xb3. Air: about 0.0012 g/cm\xb3. Same-size boxes of different materials have very different masses — density is the number that captures that.</p>\n<p>The crucial mental step: <strong>density belongs to the material, not the object</strong>. Cut an iron bar in half and each half has half the mass and half the volume — but the ratio, 7.9 g/cm\xb3, is untouched. A ratio that stays fixed while amounts change is exactly the "what stays constant?" invariant from the proportion section: for a given material, m and V are directly proportional, and density is the constant of proportionality. Speed is to distance-and-time what density is to mass-and-volume. One reasoning pattern, two costumes.</p>\n<p><strong>Worked example 1.</strong> A block measures 4 cm \xd7 5 cm \xd7 2 cm and has mass 316 g. Density? Volume = 40 cm\xb3, so ρ = 316 \xf7 40 = <strong>7.9 g/cm\xb3</strong> — matching iron. Congratulations: you\'ve just identified a metal with arithmetic, which is precisely how Archimedes audited the king\'s crown.</p>\n<p><strong>Worked example 2.</strong> What is the mass of 250 cm\xb3 of water? m = ρ \xd7 V = 1 \xd7 250 = <strong>250 g</strong>. And of 250 cm\xb3 of air? 0.0012 \xd7 250 = 0.3 g. Same volume, mass differing by a factor of ≈800 — which is why a "full" balloon still feels empty.</p>\n<div class="analogy">\n  <h3>Analogy: Crowdedness</h3>\n  <p>Density is crowdedness. A packed elevator and a packed stadium have wildly different numbers of people, but can have the same people-per-square-meter. Asking "which is denser?" is never asking "which is bigger or heavier?" — it\'s asking "which is more crowded?" Floating hangs on this: wood floats not because it\'s light (a log outweighs a nail) but because it\'s less crowded than water.</p>\n</div>\n<p>When density problems appear in Subject 5, they will offer you three quantities and ask for one. That\'s not a physics puzzle — it\'s the unitary method wearing a lab coat. You already know the move.</p>'}],quiz:[{question:"Alex and Ben share $150 in the ratio 2 : 3. Using a bar model, how much does Ben receive?",options:["$60 — Ben has 2 of the 5 boxes","$90 — five equal boxes of $30 each, and Ben has three of them","$100 — Ben gets two thirds","$75 — they split it evenly"],correctIndex:1,explanation:"Draw 2 boxes for Alex and 3 for Ben: 5 equal boxes share $150, so each box is $30. Ben's three boxes make $90 (Alex gets $60). The bar model reduces ratio-sharing to counting boxes — no algebra required."},{question:"A journey takes 6 hours at 40 km/h. How long does it take at 80 km/h, and why?",options:["12 hours — time is directly proportional to speed","4 hours — subtract the speed increase from the time","3 hours — speed and time are inversely proportional when distance is fixed: doubling speed halves the time","6 hours — travel time depends only on the route"],correctIndex:2,explanation:"The invariant is the distance: speed \xd7 time = 40 \xd7 6 = 240 km stays fixed. At 80 km/h, time = 240 \xf7 80 = 3 h. Recognizing 'fixed product → inverse proportion' is the master move; the same logic later runs Boyle's law for gases."},{question:"A cyclist travels 30 km at 15 km/h and returns at 10 km/h. What is the average speed for the whole trip?",options:["12.5 km/h — the average of 15 and 10","12 km/h — total distance (60 km) divided by total time (5 h)","13 km/h — weighted toward the faster leg","25 km/h — add the speeds"],correctIndex:1,explanation:"Average speed is always total distance \xf7 total time, never the average of the speeds. The slow leg takes 3 hours against the fast leg's 2, so the slow speed dominates: 60 \xf7 5 = 12 km/h. Rates can't be averaged directly because they carry unequal time weights."},{question:"A metal block has volume 40 cm\xb3 and mass 316 g. Its density is 7.9 g/cm\xb3. If the block is cut exactly in half, the density of each piece is...",options:["7.9 g/cm\xb3 — density is a ratio belonging to the material, unchanged by the amount","3.95 g/cm\xb3 — half the block, half the density","15.8 g/cm\xb3 — the same mass packs into less volume","Impossible to say without weighing the pieces"],correctIndex:0,explanation:"Halving the block halves both mass (158 g) and volume (20 cm\xb3), so the ratio 158 \xf7 20 = 7.9 g/cm\xb3 is untouched. This is what makes density an identifier of materials — and it's the same 'fixed ratio' structure as constant speed. Students who miss this are missing the ratio concept, not the physics."},{question:"A taxi charges a $5 flag-fall plus $2 per km. Why is the fare NOT directly proportional to distance?",options:["Because the fare involves money rather than physical quantities","Because doubling the distance doesn't double the fare, and the graph doesn't pass through the origin","It is directly proportional — the fare rises when distance rises","Because proportionality only applies to decreasing quantities"],correctIndex:1,explanation:"Direct proportion demands a fixed ratio: y = kx, a straight line through the origin. A 1 km ride costs $7 ($7/km) but a 10 km ride costs $25 ($2.50/km) — the ratio isn't constant, and at zero distance the fare is $5, not $0. 'It increases' is not enough; always apply the doubling test."}]},{id:"powers-roots-scientific-notation",title:"Powers, Roots & Scientific Notation",subtitle:"From repeated multiplication to the size of the universe — the notation that makes physics' huge and tiny numbers manageable",sections:[{id:"exponents-and-roots",title:"Exponents & Roots",content:'\n<p>An exponent is compressed multiplication: 2⁵ means 2 \xd7 2 \xd7 2 \xd7 2 \xd7 2 = 32. Say it as "2 to the 5th power." The notation earns its keep because physics quantities multiply <em>relentlessly</em> — areas are lengths squared, volumes are lengths cubed, energies go as speeds squared — and because exponents obey beautifully simple rules:</p>\n<ul>\n  <li><strong>Multiplying powers adds exponents:</strong> 10\xb3 \xd7 10⁴ = 10⁷. (Three tens times four tens is seven tens multiplied together.)</li>\n  <li><strong>Dividing subtracts:</strong> 10⁷ \xf7 10\xb3 = 10⁴.</li>\n  <li><strong>A power of a power multiplies:</strong> (10\xb3)\xb2 = 10⁶.</li>\n</ul>\n<p>Push the subtraction rule to its edges and two famous results fall out, no decree required. 10\xb3 \xf7 10\xb3 = 10⁰, but anything divided by itself is 1 — so <strong>10⁰ = 1</strong>. And 10\xb2 \xf7 10\xb3 = 10⁻\xb9, but 100 \xf7 1000 = 1⁄10 — so <strong>a negative exponent means a reciprocal</strong>: 10⁻\xb3 = 1⁄1000 = 0.001. Negative exponents aren\'t negative numbers; they\'re small positive ones. That distinction will matter every day of this course.</p>\n<p><strong>Roots undo powers.</strong> The square root of 49 asks: what number, squared, gives 49? Answer 7, written √49 = 7. Cube roots undo cubes: ∛64 = 4, since 4\xb3 = 64. Physics reaches for roots whenever it reasons backwards from an area, a volume, or an energy: if a square field has area 200 m\xb2, its side is √200 ≈ 14.1 m. If kinetic energy quadruples, speed only doubled — because energy carries a v\xb2, undone by a square root.</p>\n<div class="key-concept">\n  <h3>Key Concept: Squares Grow Fast, and Physics Feels It</h3>\n  <p>Doubling a speed quadruples the kinetic energy (2\xb2 = 4) — which is why a crash at 100 km/h is four times as destructive as at 50, not twice. Tripling the distance from a planet cuts gravity to a ninth (3\xb2 = 9). The nonlinear world of physics is largely the arithmetic of squares.</p>\n</div>\n<p>Worked example: fold a paper 0.1 mm thick 42 times (in imagination — physical folding gives out near 7). Thickness: 0.1 mm \xd7 2⁴\xb2 ≈ 0.1 \xd7 4.4 \xd7 10\xb9\xb2 mm ≈ 440,000 km — past the Moon. Exponential growth is not intuition-friendly; that\'s precisely why we need the notation.</p>'},{id:"scientific-notation",title:"Scientific Notation",content:'\n<p>Physics traffics in absurd numbers. The mass of the Earth: 5,972,000,000,000,000,000,000,000 kg. The mass of an electron: 0.000 000 000 000 000 000 000 000 000 000 911 kg. Written that way, they\'re unusable — uncountable zeros, invisible errors. <strong>Scientific notation</strong> fixes this by splitting every number into two jobs:</p>\n<p style="text-align:center"><strong>(a number between 1 and 10) \xd7 (a power of ten)</strong></p>\n<p>Earth\'s mass: 5.972 \xd7 10\xb2⁴ kg. Electron: 9.11 \xd7 10⁻\xb3\xb9 kg. The first factor carries the <em>digits</em> (the precision); the exponent carries the <em>size</em>. Two jobs, cleanly separated.</p>\n<p>Converting is place-value gymnastics from Chapter 1: count how many places the decimal point must slide to leave one nonzero digit in front. 34,500 → 3.45 \xd7 10⁴ (four slides left). 0.0072 → 7.2 \xd7 10⁻\xb3 (three slides right; small numbers get negative exponents).</p>\n<p>The real payoff is arithmetic — the exponent rules take over the heavy lifting:</p>\n<ul>\n  <li><strong>Multiply:</strong> multiply the fronts, add the exponents. (3 \xd7 10⁸) \xd7 (2 \xd7 10⁻⁵) = 6 \xd7 10\xb3.</li>\n  <li><strong>Divide:</strong> divide the fronts, subtract the exponents. (8 \xd7 10⁶) \xf7 (4 \xd7 10\xb2) = 2 \xd7 10⁴.</li>\n  <li><strong>Tidy up:</strong> if the front leaves the 1–10 range, slide once more: 60 \xd7 10\xb3 → 6 \xd7 10⁴.</li>\n</ul>\n<p><strong>Worked example.</strong> How long does sunlight take to reach Earth? Distance ≈ 1.5 \xd7 10\xb9\xb9 m; light speed ≈ 3 \xd7 10⁸ m/s. Time = distance \xf7 speed = (1.5 \xf7 3) \xd7 10\xb9\xb9⁻⁸ = 0.5 \xd7 10\xb3 = 5 \xd7 10\xb2 s = <strong>500 seconds ≈ 8⅓ minutes</strong>. A calculation spanning eleven orders of magnitude, done in one line, in your head.</p>\n<div class="did-you-know">\n  <h4>Did You Know?</h4>\n  <p>Your calculator\'s "E notation" — 5.972E24 — is scientific notation wearing a keyboard-friendly disguise: E24 means \xd7 10\xb2⁴. Knowing this saves you from the classic blunder of typing 5.972 \xd7 10 ^ 24 with stray parentheses and getting an answer that is off by a factor of ten — an error scientific notation was invented to prevent.</p>\n</div>'},{id:"orders-of-magnitude",title:"Orders of Magnitude",content:'\n<p>An <strong>order of magnitude</strong> is a factor of ten. Two numbers are "an order of magnitude apart" when one is about ten times the other; "three orders" means a factor of about a thousand. It sounds like jargon, but it\'s really a decision to care about the <em>exponent</em> and treat the front number as a detail — physics\' favorite level of precision for a first look at anything.</p>\n<p>Why coarse-grain like this? Because at first contact with a problem, the exponent carries almost all the information. Whether a bacterium is 1 or 3 micrometers long barely matters; that it\'s 10⁻⁶ m rather than 10⁻\xb3 m is everything. A ladder to keep in your head:</p>\n<table>\n  <thead>\n    <tr><th>Scale (m)</th><th>Roughly...</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>10⁻\xb9⁵</td><td>a proton</td></tr>\n    <tr><td>10⁻\xb9⁰</td><td>an atom</td></tr>\n    <tr><td>10⁻⁶</td><td>a bacterium</td></tr>\n    <tr><td>10⁰</td><td>you (≈1–2 m)</td></tr>\n    <tr><td>10⁷</td><td>Earth\'s diameter (1.3 \xd7 10⁷ m)</td></tr>\n    <tr><td>10\xb9\xb9</td><td>Earth–Sun distance</td></tr>\n    <tr><td>10\xb9⁶</td><td>one light-year</td></tr>\n    <tr><td>10\xb2\xb9</td><td>the Milky Way\'s diameter</td></tr>\n    <tr><td>10\xb2⁶</td><td>the observable universe</td></tr>\n  </tbody>\n</table>\n<p>Notice the symmetry worth savoring: you stand roughly halfway (in factors of ten) between a proton and the observable universe — about 41 orders of magnitude in each direction? Not quite: 15 below, 26 above. Closer to atoms than to galaxies, but a middle creature either way.</p>\n<div class="analogy">\n  <h3>Analogy: The Zoom Slider</h3>\n  <p>Think of reality as a map app with a zoom slider, where each notch is \xd710. Nine notches out from your street: the whole planet. Nine notches in: a virus. The famous 1977 film <em>Powers of Ten</em> is exactly this ride, and the mental slider it installs is a permanent piece of physics equipment.</p>\n</div>\n<p><strong>Worked example.</strong> How many times more massive is the Sun (2 \xd7 10\xb3⁰ kg) than the Earth (6 \xd7 10\xb2⁴ kg)? Exponents first: 10\xb3⁰ \xf7 10\xb2⁴ = 10⁶ — about a million. Fronts: 2 \xf7 6 ≈ 0.33. Answer: ≈ 3.3 \xd7 10⁵, a third of a million. For most purposes, "the Sun is five to six orders of magnitude heavier" is the memorable, useful fact — and you computed it without a calculator.</p>'},{id:"fermi-estimation",title:"Fermi Estimation",content:"\n<p>The physicist Enrico Fermi was famous for producing good rough answers to seemingly impossible questions — how many piano tuners work in Chicago? — using nothing but everyday knowledge and powers of ten. A <strong>Fermi estimate</strong> aims not for the right answer but for the right <em>order of magnitude</em>: within a factor of ten. That sounds unambitious until you see how much it buys.</p>\n<p>The method:</p>\n<ol>\n  <li><strong>Break the question into factors you can roughly guess.</strong></li>\n  <li><strong>Round each factor to one digit times a power of ten.</strong></li>\n  <li><strong>Multiply, adding exponents as you go.</strong></li>\n</ol>\n<p>The magic is error cancellation: with several independently guessed factors, some guesses run high and others low, and the product usually lands within a factor of 2–3 of truth — the same opposite-direction cancellation you met while rounding in Chapter 1, now industrialized.</p>\n<p><strong>Worked example: how many breaths do you take in a lifetime?</strong></p>\n<ul>\n  <li>Breathing rate: ≈ 15 per minute ≈ 1.5 \xd7 10\xb9</li>\n  <li>Minutes per day: 60 \xd7 24 = 1,440 ≈ 1.5 \xd7 10\xb3</li>\n  <li>Days per year: ≈ 4 \xd7 10\xb2</li>\n  <li>Years: ≈ 8 \xd7 10\xb9</li>\n</ul>\n<p>Multiply fronts: 1.5 \xd7 1.5 \xd7 4 \xd7 8 ≈ 72. Add exponents: 10\xb9⁺\xb3⁺\xb2⁺\xb9 = 10⁷. Total ≈ 72 \xd7 10⁷ ≈ <strong>7 \xd7 10⁸ breaths</strong> — roughly a billion, give or take. No reference book on Earth has this number; you just manufactured it from things you already knew.</p>\n<p><strong>Worked example 2: could all of humanity fit in Lake Superior?</strong> A person's volume ≈ 0.07 m\xb3 (they mostly float, like water, and weigh ≈ 70 kg — density reasoning from Chapter 3!). Humanity: 8 \xd7 10⁹ people \xd7 7 \xd7 10⁻\xb2 m\xb3 ≈ 5.6 \xd7 10⁸ m\xb3. Lake Superior holds ≈ 1.2 \xd7 10\xb9\xb3 m\xb3. Verdict: humanity would fill about 0.005% of the lake. All of us, one lake, a rounding error.</p>\n<div class=\"key-concept\">\n  <h3>Key Concept: Estimation Is a Physicist's License</h3>\n  <p>Fermi problems train the exact reflexes real physics demands: decompose, approximate, track powers of ten, and sanity-check the result. Interviewers at national labs and tech firms still pose them, because the skill they reveal — reasoning confidently under uncertainty — is the job. From now on, estimate one absurd thing per week. It's the most enjoyable homework in this course.</p>\n</div>"}],quiz:[{question:"What is 10⁻\xb3 as an ordinary number?",options:["−1000 — the minus makes it negative","0.001 — a negative exponent means a reciprocal: 1⁄10\xb3","−0.001 — negative and small","0.003 — the 3 moves after the decimal point"],correctIndex:1,explanation:"A negative exponent is a reciprocal, not a negative number: 10⁻\xb3 = 1⁄10\xb3 = 1⁄1000 = 0.001, a small positive value. This follows from the division rule (10\xb2 \xf7 10\xb3 = 10⁻\xb9 = 1⁄10). Physics is full of 10⁻\xb9⁹s and 10⁻\xb3\xb9s — all tiny, none negative."},{question:"Light travels at 3 \xd7 10⁸ m/s and the Sun is 1.5 \xd7 10\xb9\xb9 m away. How long does sunlight take to reach Earth?",options:["500 s (about 8 minutes) — divide fronts (1.5 \xf7 3 = 0.5) and subtract exponents (11 − 8 = 3)","0.002 s — light is essentially instantaneous","4.5 \xd7 10\xb9⁹ s — multiply the numbers","50 s — subtract exponents to get 10\xb3 but ignore the fronts"],correctIndex:0,explanation:"Time = distance \xf7 speed = (1.5 \xf7 3) \xd7 10\xb9\xb9⁻⁸ = 0.5 \xd7 10\xb3 = 500 s ≈ 8⅓ min. Scientific notation turns an 11-orders-of-magnitude calculation into one-digit arithmetic plus exponent subtraction — the entire point of the notation."},{question:"Kinetic energy grows as the square of speed. A car doubles its speed from 50 to 100 km/h. Its kinetic energy...",options:["doubles — energy tracks speed","triples — one factor for speed, one for mass, one extra","quadruples — 2\xb2 = 4, which is why high-speed crashes are so disproportionately destructive","increases by 50 km/h worth"],correctIndex:2,explanation:"Squares turn a doubling into a quadrupling: (2v)\xb2 = 4v\xb2. This is the single most practical fact about exponents — stopping distances, crash energies, and wind loads all carry squares, so modest speed increases buy severe consequences."},{question:"In a Fermi estimate with several guessed factors, why does the final answer usually land within a factor of 2–3 of the truth?",options:["Because each individual guess is highly accurate","Because independent guesses err in both directions, and their errors partly cancel in the product","Because powers of ten cannot compound errors","It doesn't — Fermi estimates are typically off by factors of 100 or more"],correctIndex:1,explanation:"Each factor might be off by 2\xd7 either way, but overestimates and underestimates multiply against each other and largely cancel. This statistical mercy is why order-of-magnitude reasoning works at all — and why breaking a question into more independent factors often makes the estimate better, not worse."},{question:"Which is the correct scientific-notation form of 0.00042?",options:["42 \xd7 10⁻⁵ — front number can be anything","4.2 \xd7 10⁴ — count the four decimal places","0.42 \xd7 10⁻\xb3 — slide three places","4.2 \xd7 10⁻⁴ — one nonzero digit before the point, decimal slid four places right"],correctIndex:3,explanation:"Standard form requires the front number to sit between 1 and 10: 4.2. The decimal point slides four places right to get there, so the exponent is −4 (small number, negative exponent). The forms 42 \xd7 10⁻⁵ and 0.42 \xd7 10⁻\xb3 equal the same value but break the convention that makes numbers instantly comparable."}]},{id:"units-and-measurement",title:"Units & Measurement",subtitle:"SI units, conversion as multiplication by 1, dimensional thinking, and honest numbers — where math becomes measurement",sections:[{id:"the-si-system",title:"The SI System: One Language for Measurement",content:"\n<p>A measurement without a unit is a rumor. \"The rope is 12\" — twelve what? Physics enforces the rule absolutely: <strong>every measured quantity is a number times a unit</strong>, and the unit is not decoration — it's half the information. In 1999, NASA's $327-million Mars Climate Orbiter burned up because one team supplied thrust data in pound-force units while another read them as newtons. Units are not pedantry. Units are survival.</p>\n<p>The <strong>SI system</strong> (Syst\xe8me International) is science's shared measurement language. Everything you'll meet in this course is built from a handful of base units:</p>\n<table>\n  <thead>\n    <tr><th>Quantity</th><th>Unit</th><th>Symbol</th><th>Everyday anchor</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>Length</td><td>meter</td><td>m</td><td>a long stride</td></tr>\n    <tr><td>Mass</td><td>kilogram</td><td>kg</td><td>a liter of water</td></tr>\n    <tr><td>Time</td><td>second</td><td>s</td><td>one \"one-Mississippi\"</td></tr>\n    <tr><td>Temperature</td><td>kelvin</td><td>K</td><td>Celsius shifted so 0 K is absolute zero (0\xb0C = 273.15 K)</td></tr>\n    <tr><td>Electric current</td><td>ampere</td><td>A</td><td>a bright LED bulb draws ≈ 0.05 A</td></tr>\n  </tbody>\n</table>\n<p>Everything else is <strong>derived</strong> by combining these: speed in m/s, volume in m\xb3, density in kg/m\xb3, and later force in kg\xb7m/s\xb2 (honored with its own name, the newton). Recognizing derived units as combinations is a preview of dimensional thinking, two sections from now.</p>\n<p>SI's masterstroke is its <strong>prefixes</strong> — the place-value system from Chapter 1, bolted onto units. Each prefix is a power of ten: kilo (10\xb3), mega (10⁶), giga (10⁹); going down, centi (10⁻\xb2), milli (10⁻\xb3), micro (10⁻⁶), nano (10⁻⁹). One set of prefixes, every unit: a kilometer, a kilogram, a kilowatt; a millimeter, a milliliter, a millisecond. Learn nine prefixes and you can read every instrument in a laboratory.</p>\n<div class=\"did-you-know\">\n  <h4>Did You Know?</h4>\n  <p>Since 2019, every SI base unit is defined by fixing a constant of nature — the second by a cesium atom's vibration, the meter by the speed of light, the kilogram via Planck's constant. The platinum-iridium kilogram cylinder in a Paris vault, humanity's last physical unit standard, is now a museum piece. Measurement no longer rests on any object anyone could scratch, steal, or lose.</p>\n</div>"},{id:"unit-conversion-as-multiplication-by-one",title:"Unit Conversion: Multiplying by 1",content:'\n<p>Most people convert units by half-remembered folklore: "multiply by 1000... or was it divide?" Physics has a method with no folklore in it, and it will carry you from this chapter through relativity: <strong>every unit conversion is a multiplication by 1</strong>.</p>\n<p>The trick: since 1 km = 1000 m, the fraction (1000 m ⁄ 1 km) equals exactly 1 — top and bottom are the same length in different costumes. Multiplying by it changes nothing real; it only changes the label. Then you let the units <strong>cancel like fractions</strong>:</p>\n<p style="text-align:center">3.5 km \xd7 (1000 m ⁄ 1 km) = 3,500 m — the km upstairs cancels the km downstairs.</p>\n<p>Which way up does the factor go? Let the cancellation decide: put the unit you\'re <em>leaving</em> where it will cancel. If nothing cancels, the factor is upside down — flip it. The method is self-correcting, which folklore never is.</p>\n<p><strong>Worked example (chained factors).</strong> Convert 90 km/h to m/s:</p>\n<p style="text-align:center">90 km⁄h \xd7 (1000 m ⁄ 1 km) \xd7 (1 h ⁄ 3600 s) = 90 \xd7 1000 \xf7 3600 = <strong>25 m/s</strong></p>\n<p>Each factor equals 1; km cancels km, h cancels h; only m/s survives. (The shortcut worth memorizing after you trust it: km/h \xf7 3.6 = m/s.)</p>\n<p><strong>Worked example (squared units — where folklore dies).</strong> Convert 2.5 m\xb2 to cm\xb2. Not 250! A square meter is a 100 cm \xd7 100 cm square: 10,000 cm\xb2. So 2.5 m\xb2 \xd7 (100 cm ⁄ 1 m) \xd7 (100 cm ⁄ 1 m) = <strong>25,000 cm\xb2</strong>. The conversion factor gets applied once per dimension — automatic with this method, invisible without it.</p>\n<div class="key-concept">\n  <h3>Key Concept: The Same "Clever 1" You Already Know</h3>\n  <p>In Chapter 2 you made equivalent fractions by multiplying by 2⁄2. This is the identical move with units in the costume: (1000 m ⁄ 1 km) is just a clever form of 1. One idea — multiplying by 1 never changes a value, only its appearance — now runs your fraction work AND your unit work. Physics is full of such economies.</p>\n</div>\n<p>From here on, treat units as algebraic objects that multiply, divide, and cancel. That single habit prevents the most common wrong answers in all of introductory physics — and it\'s the warm-up for the next section, where units stop being bookkeeping and start doing physics for you.</p>'},{id:"dimensional-thinking",title:"Dimensional Thinking",content:"\n<p>Here's a superpower disguised as bookkeeping. Every physical quantity has a <strong>dimension</strong> — its recipe in terms of length (L), mass (M), and time (T), regardless of which units dress it up. Speed has dimension L⁄T whether measured in m/s or furlongs per fortnight. Area is L\xb2. Density is M⁄L\xb3. Acceleration — speed's rate of change — is L⁄T\xb2.</p>\n<p>The power comes from one iron rule: <strong>an equation must have the same dimensions on both sides</strong>. You cannot equate meters to seconds, any more than you can owe someone 5 kilograms of money. Consequences:</p>\n<ul>\n  <li><strong>Error detection.</strong> Suppose you misremember distance fallen as d = \xbdgt (should it be t\xb2?). Check: g is L⁄T\xb2, times t gives L⁄T — a speed, not a distance. Wrong, caught in five seconds, no experiment needed. With t\xb2: L⁄T\xb2 \xd7 T\xb2 = L ✓.</li>\n  <li><strong>Formula reconstruction.</strong> Forgot the pendulum period formula? It should involve length ℓ and gravity g (L⁄T\xb2). To build a time from L and L⁄T\xb2: divide ℓ by g to get T\xb2, then square-root. So the period ≈ √(ℓ⁄g) — correct up to the dimensionless 2π that dimensions can never see. You just recovered physics from bookkeeping.</li>\n  <li><strong>Sanity in every answer.</strong> If a problem asks for a mass and your result carries m\xb3, no further review is required: it's wrong.</li>\n</ul>\n<div class=\"analogy\">\n  <h3>Analogy: Grammar Check for Equations</h3>\n  <p>\"The purple seven slept furiously\" is grammatical nonsense even before you ask if it's true. Dimensional analysis is grammar-checking for physics: it can't confirm an equation is <em>right</em>, but it instantly exposes whole categories of wrongness — and physicists run this check reflexively on every formula they write or recall.</p>\n</div>\n<p><strong>Worked example.</strong> A student derives that a dropped object's landing speed is v = √(2gh). Check it: inside the root, g \xd7 h has dimensions (L⁄T\xb2) \xd7 L = L\xb2⁄T\xb2. The square root gives L⁄T — a speed ✓. Note what the check costs: nothing. Note what it catches over a career: everything from sign-of-exhaustion slips to deep misunderstandings.</p>\n<p>When formulas multiply in Phase 2 — and they will — dimensional thinking is what separates students who memorize twenty formulas nervously from students who carry three ideas confidently and rebuild the rest on demand. Build the reflex now: <em>every</em> equation you meet, ask it to show its dimensions at the door.</p>"},{id:"significant-figures",title:"Significant Figures: Honest Numbers",content:"\n<p>Measure a table with a ruler marked in millimeters and report the length as 1.274063 m, and you have told a lie — not about the table, but about your ruler. No instrument justifies those last four digits. <strong>Significant figures</strong> are the discipline of reporting exactly as much precision as you actually have: every digit you write is a claim, and honest numbers make only defensible claims.</p>\n<p>Reading significance:</p>\n<ul>\n  <li><strong>Nonzero digits always count:</strong> 47.3 has three sig figs.</li>\n  <li><strong>Zeros between digits count:</strong> 4,003 has four.</li>\n  <li><strong>Leading zeros never count:</strong> 0.0052 has two — the zeros just locate the decimal point. (Scientific notation says it cleanly: 5.2 \xd7 10⁻\xb3.)</li>\n  <li><strong>Trailing zeros after a decimal point count:</strong> 2.500 has four — writing them is a deliberate claim of precision. A bare 2,500 is ambiguous, which is precisely why scientists prefer 2.5 \xd7 10\xb3 (two sig figs) or 2.500 \xd7 10\xb3 (four).</li>\n</ul>\n<p>Calculating without inflating precision:</p>\n<ul>\n  <li><strong>Multiplying/dividing:</strong> the answer keeps as many sig figs as the <em>least</em> precise input. 12.3 (three) \xd7 4.6 (two) = 56.58 → report <strong>57</strong>.</li>\n  <li><strong>Adding/subtracting:</strong> the answer keeps the least precise <em>decimal place</em>. 12.11 + 0.043 = 12.153 → report <strong>12.15</strong>.</li>\n  <li><strong>Round only at the end.</strong> Carry full digits through intermediate steps; premature rounding compounds.</li>\n</ul>\n<div class=\"key-concept\">\n  <h3>Key Concept: A Chain Is as Precise as Its Weakest Measurement</h3>\n  <p>Multiplying a superbly measured 3.14159 by a crudely measured 2.1 yields a crude product. No arithmetic can add information that a measurement failed to capture. Calculators are the enemy here — they will happily hand you ten digits of fiction; sig figs are how you decline.</p>\n</div>\n<p><strong>Worked example.</strong> A block's sides measure 2.1 cm, 3.45 cm, 1.2 cm. Volume: 2.1 \xd7 3.45 \xd7 1.2 = 8.694 cm\xb3. The stingiest inputs have two sig figs, so report <strong>8.7 cm\xb3</strong>. If its mass is 68.5 g, density = 68.5 \xf7 8.694 ≈ 7.879... → <strong>7.9 g/cm\xb3</strong> (two sig figs) — iron again, and now stated with exactly the confidence the ruler deserves.</p>\n<p>This is your first taste of measurement uncertainty, which Subject 3 develops properly and lab work lives by. The theme deserves its banner: <strong>physics is not about exact numbers; it's about known precision</strong>.</p>"}],quiz:[{question:"Convert 90 km/h to m/s using conversion factors. Which is the correct setup and result?",options:["90 \xd7 (1000 m ⁄ 1 km) \xd7 (1 h ⁄ 3600 s) = 25 m/s — each factor equals 1, and km and h cancel","90 \xd7 3600 \xf7 1000 = 324 m/s — hours convert first","90 \xf7 1000 \xd7 3600 = 324 m/s — the factors flip","90 \xf7 60 = 1.5 m/s — divide by minutes"],correctIndex:0,explanation:"Each factor is a 'clever form of 1' (top equals bottom), so the value is unchanged while km cancels km and h cancels h: 90 \xd7 1000 \xf7 3600 = 25 m/s. If units don't cancel, a factor is upside down — the method is self-correcting, which is why physicists trust it over memorized rules."},{question:"How many cm\xb2 are in 2.5 m\xb2?",options:["250 — multiply by 100","2,500 — multiply by 1000","25,000 — the factor of 100 applies once per dimension: 2.5 \xd7 100 \xd7 100","250,000 — apply 100 three times"],correctIndex:2,explanation:"A square meter is a 100 cm \xd7 100 cm square = 10,000 cm\xb2. Squared units need the conversion factor squared: 2.5 \xd7 10⁴ = 25,000 cm\xb2. Writing the factor (100 cm ⁄ 1 m) twice makes this automatic — forgetting it is the single most common conversion error in physics homework."},{question:"A student recalls the distance-fallen formula as d = \xbdgt (g in m/s\xb2, t in seconds). What does a dimensional check reveal?",options:["The formula is fine — the \xbd fixes the dimensions","The right side has dimensions L⁄T (a speed), not L, so a factor of t is missing: it must be t\xb2","Dimensions can't test formulas containing constants","The formula fails only for large values of t"],correctIndex:1,explanation:"g \xd7 t has dimensions (L⁄T\xb2) \xd7 T = L⁄T — a speed, not a distance, so the equation is grammatically impossible; with t\xb2 it gives L ✓. Pure numbers like \xbd carry no dimensions, so they can't rescue a mismatch. This five-second check catches misremembered formulas before they cost you a problem set."},{question:"How many significant figures does 0.00520 have?",options:["six — count every digit","five — count all zeros after the decimal point","two — trailing zeros never count","three — the leading zeros only place the decimal point, but the trailing zero is a deliberate claim of precision"],correctIndex:3,explanation:"Leading zeros are placeholders (not significant); the 5, the 2, and the final 0 are significant — that trailing zero asserts the measurement resolved that digit. Scientific notation removes all doubt: 5.20 \xd7 10⁻\xb3 displays exactly its three significant figures, which is one reason scientists prefer it."},{question:"Sides of a block measure 2.1 cm, 3.45 cm, and 1.2 cm. A calculator gives the volume as 8.694 cm\xb3. What should you report, and why?",options:["8.694 cm\xb3 — never discard computed digits","8.7 cm\xb3 — the least precise measurements have two significant figures, and no calculation can exceed its weakest input","8.69 cm\xb3 — match the most precise measurement","9 cm\xb3 — always round to whole numbers in a lab"],correctIndex:1,explanation:"For multiplication, the result inherits the sig-fig count of the least precise factor — here two (2.1 and 1.2). The extra calculator digits are fiction: they claim a precision the ruler never delivered. Report 8.7 cm\xb3. Honest precision is the foundation of the uncertainty analysis you'll meet in real lab work."}]}]},{id:"phenomena-of-physics",number:2,title:"The Phenomena of Physics",description:"The entire primary-science 'starter set' of the world's best school systems — every physics phenomenon, qualitatively, with at-home experiments.",phase:1,chapters:[{id:"matter-and-materials",title:"Matter & Materials",subtitle:"Solids, liquids, gases, and the particle picture that explains them all",sections:[{id:"three-states",title:"The Three States of Matter",content:'\n<p>Look around you right now. Everything you can see or touch — the chair beneath you, the water in your glass, the air filling the room — is <strong>matter</strong>, and almost all of it comes in one of three familiar states: <strong>solid</strong>, <strong>liquid</strong>, or <strong>gas</strong>.</p>\n<p>Each state behaves in its own recognizable way:</p>\n<ul>\n  <li><strong>Solids</strong> keep their shape and their size. A spoon stays spoon-shaped whether it sits on the table or in a drawer. You cannot squash it smaller by squeezing.</li>\n  <li><strong>Liquids</strong> keep their size but not their shape. Pour the same cup of water into a tall glass, a wide bowl, or a zig-zag straw and it takes the shape of whatever holds it — yet the amount never changes. Liquids also find their own level: the surface of still water is always flat and horizontal.</li>\n  <li><strong>Gases</strong> keep neither shape nor size. Open a bottle of perfume in one corner of a room and within minutes someone at the far side smells it. A gas spreads out to fill every bit of available space.</li>\n</ul>\n<p>The same substance can appear in all three states. Water is the everyday example: ice in the freezer, liquid water from the tap, and invisible water vapour in the air. It is still water throughout — nothing is added or removed, only the state changes.</p>\n<div class="analogy">\n  <h3>Analogy: A Crowd in Three Moods</h3>\n  <p>Picture people in a stadium. A solid is the seated crowd — everyone in a fixed place, jiggling slightly but not swapping seats. A liquid is the crowd on the concourse at half-time — packed shoulder to shoulder but sliding past one another. A gas is the crowd after the game, scattered across the whole city, each person moving freely with lots of empty space between them.</p>\n</div>\n<div class="key-concept">\n  <h3>Key Concept: State Is Behaviour, Not Identity</h3>\n  <p>Freezing water does not turn it into a new substance — it just makes the same substance behave differently. State describes how matter behaves, not what it is.</p>\n</div>'},{id:"properties-of-materials",title:"Properties of Materials",content:'\n<p>Why are windows made of glass, saucepans of metal, and raincoats of plastic-coated fabric? Because every material has a personality — a set of <strong>properties</strong> — and we choose materials whose properties match the job.</p>\n<p>Some properties you can test with your hands and eyes:</p>\n<ul>\n  <li><strong>Hardness</strong> — does it resist scratching and denting? Steel is hard; wax is soft.</li>\n  <li><strong>Flexibility</strong> — does it bend without breaking? A rubber band bends; a ceramic tile snaps.</li>\n  <li><strong>Strength</strong> — how much pulling or squashing can it take before it fails? A steel cable can hold up a bridge; a cotton thread cannot.</li>\n  <li><strong>Transparency</strong> — does light pass through? Glass yes, brick no.</li>\n  <li><strong>Waterproofness</strong> — does water soak in or run off? Compare a sponge with a plastic bag.</li>\n  <li><strong>Conduction</strong> — does heat (or electricity) travel through it easily? Metals feel cold to the touch because they carry heat away from your skin quickly; wood feels warmer because it does not.</li>\n</ul>\n<p>Notice that a property belongs to the <strong>material</strong>, not the object. A steel spoon and a steel bridge share the properties of steel. That is why engineers talk about "choosing a material" before they design anything.</p>\n<table>\n  <thead>\n    <tr><th>Job</th><th>Property needed</th><th>Good material</th><th>Bad material</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>Window</td><td>Transparent, rigid</td><td>Glass</td><td>Wood</td></tr>\n    <tr><td>Saucepan</td><td>Conducts heat, high melting point</td><td>Metal</td><td>Plastic</td></tr>\n    <tr><td>Saucepan handle</td><td>Does <em>not</em> conduct heat</td><td>Plastic, wood</td><td>Metal</td></tr>\n    <tr><td>Raincoat</td><td>Waterproof, flexible</td><td>Coated fabric</td><td>Paper</td></tr>\n  </tbody>\n</table>\n<div class="did-you-know">\n  <h4>Did You Know?</h4>\n  <p>Modern smartphone screens use a special glass that has been chemically treated to be far harder than ordinary window glass — a reminder that we can engineer a material\'s properties, not just accept them.</p>\n</div>'},{id:"changing-state",title:"Melting, Freezing & Evaporation",content:'\n<p>Matter changes state when it is heated or cooled, and every change has a name:</p>\n<ul>\n  <li><strong>Melting:</strong> solid → liquid (ice cube → puddle). Happens when a solid is warmed enough.</li>\n  <li><strong>Freezing:</strong> liquid → solid (water → ice). Happens when a liquid is cooled enough.</li>\n  <li><strong>Evaporation:</strong> liquid → gas, happening quietly from the surface at any temperature. This is why puddles vanish on a dry day even though the water never boils.</li>\n  <li><strong>Boiling:</strong> liquid → gas throughout the whole liquid at once — the rolling bubbles in a kettle.</li>\n  <li><strong>Condensation:</strong> gas → liquid (the mist on a cold mirror after a shower, the droplets on a cold drink can).</li>\n</ul>\n<p>Two everyday observations are worth savouring. First, each pure substance changes state at its own fixed temperature: water freezes at 0 \xb0C and boils at 100 \xb0C at sea level, while chocolate melts at roughly body temperature — which is precisely why it melts in your mouth. Second, these changes are <strong>reversible</strong>: melt ice, refreeze the water, and you are back where you started. Contrast that with toasting bread or frying an egg, which can never be undone — those are changes of substance, not just of state.</p>\n<p>Evaporation speeds up when the liquid is warmer, when it is spread out, and when air moves across it. Laundry knows all three rules: it dries fastest on a warm, breezy day with the clothes spread wide on the line.</p>\n<div class="did-you-know">\n  <h4>Try it yourself</h4>\n  <p>Pour equal small amounts of water into two saucers. Leave one flat and open; cover the other with an upturned bowl. Put both in the same warm spot and check after a day. The open saucer will be nearly dry while the covered one is still wet — the escaping water needed open air to evaporate into. Now breathe gently onto a cold mirror or window: the fog that appears is the reverse trip, water vapour from your breath condensing back into liquid.</p>\n</div>'},{id:"particle-picture",title:"The Particle Picture",content:'\n<p>Here is the single most powerful idea in this whole subject: <strong>all matter is made of tiny particles, far too small to see, and the particles are always moving</strong>. Accept that one sentence, and everything in the previous sections stops being a list of facts and becomes obvious.</p>\n<ul>\n  <li>In a <strong>solid</strong>, the particles are packed tightly in a regular arrangement, each one vibrating on the spot but held by its neighbours. That is why solids keep their shape and cannot be squashed.</li>\n  <li>In a <strong>liquid</strong>, the particles are still touching but can slide past one another. The substance holds together — fixed volume — yet flows into any shape.</li>\n  <li>In a <strong>gas</strong>, the particles are far apart and flying freely in all directions, colliding and rebounding. That is why gases spread to fill any space and can be squeezed into a smaller volume (there is mostly emptiness between the particles).</li>\n</ul>\n<p>Heating matter is simply making its particles move faster. Warm a solid and the vibrations grow until the particles shake loose from their positions — that is melting. Warm a liquid and the fastest particles at the surface break free entirely — that is evaporation. Cool a gas and slow-moving particles begin to stick when they collide — that is condensation. Temperature, state changes, why smells drift across a room, why a sealed balloon slowly deflates: one tiny-particle picture explains them all.</p>\n<div class="key-concept">\n  <h3>Key Concept: Nothing Appears, Nothing Vanishes</h3>\n  <p>When a puddle "disappears", every single particle of water still exists — the particles have merely escaped into the air one by one. Changes of state rearrange particles; they never create or destroy them.</p>\n</div>\n<div class="analogy">\n  <h3>Analogy: The Dance Floor</h3>\n  <p>Slow music: dancers sway in place, holding hands — a solid. Faster music: they let go and weave among each other, still close — a liquid. Turn the music all the way up: they leap apart and bounce around the whole hall — a gas. The dancers never change; only their energy does.</p>\n</div>'}],quiz:[{question:"Which state of matter keeps its volume but takes the shape of its container?",options:["Solid","Liquid","Gas","All three do"],correctIndex:1,explanation:"A liquid's particles stay in contact (so the volume is fixed) but can slide past one another (so the shape adapts to the container). Solids keep both shape and volume; gases keep neither."},{question:"A puddle dries up on a warm day even though the water never gets close to boiling. What is happening?",options:["The water soaks entirely into the ground","The water is destroyed by sunlight","The fastest particles at the surface escape into the air — evaporation","The water freezes and then disappears"],correctIndex:2,explanation:"Evaporation happens from the surface of a liquid at any temperature: the most energetic particles break free one by one and mix into the air. No particle is destroyed — they all still exist as invisible water vapour."},{question:"Why does a metal spoon feel colder than a wooden spoon at the same room temperature?",options:["Metal is genuinely at a lower temperature than wood","Wood generates its own heat","Metal contains frozen particles","Metal conducts heat away from your hand quickly; wood does not"],correctIndex:3,explanation:"Both spoons are at room temperature. The metal merely carries heat away from your warm skin much faster, and that rapid heat loss is what your nerves report as 'cold'. Feel is a measure of heat flow, not of temperature."},{question:"According to the particle picture, what changes when a solid melts?",options:["The particles gain enough energy to break loose from fixed positions and slide past each other","The particles themselves turn into liquid particles","New particles are created between the old ones","The particles shrink so they can flow"],correctIndex:0,explanation:"The particles are identical before and after melting. Heating makes them vibrate harder until they shake free of their fixed arrangement and can slide around — the same particles, just with more energy and more freedom."}]},{id:"forces-all-around",title:"Forces All Around",subtitle:"Pushes, pulls, gravity, friction, magnets, levers, and why things float or sink",sections:[{id:"pushes-pulls-gravity",title:"Pushes, Pulls & Gravity",content:'\n<p>A <strong>force</strong> is simply a push or a pull. That modest definition covers everything: kicking a ball (push), opening a drawer (pull), squeezing a sponge (a pair of pushes), stretching a rubber band (a pair of pulls). Forces are invisible, but their effects are not — a force can <strong>start</strong> something moving, <strong>stop</strong> it, <strong>speed it up</strong>, <strong>slow it down</strong>, <strong>change its direction</strong>, or <strong>change its shape</strong>.</p>\n<p>One pull acts on you every second of your life: <strong>gravity</strong>. The Earth pulls everything toward its centre, which is why dropped keys fall down and never sideways, why rivers flow downhill, and why "down" in Australia points in the opposite direction to "down" in Europe — both point toward the middle of the planet.</p>\n<p>This lets us untangle two words that everyday speech muddles together:</p>\n<ul>\n  <li><strong>Mass</strong> is how much matter something contains — how much "stuff" it is made of. Your mass would be the same on the Moon as on Earth.</li>\n  <li><strong>Weight</strong> is the pull of gravity on that mass. On the Moon, where gravity\'s pull is about one-sixth as strong, you would weigh about one-sixth as much — while being exactly the same person, made of exactly the same amount of stuff.</li>\n</ul>\n<div class="key-concept">\n  <h3>Key Concept: Forces Come in Interactions</h3>\n  <p>A force is never something an object "has"; it is something one object <em>does to another</em>. The Earth pulls the apple; your foot pushes the ball; the magnet pulls the pin. Every force sentence needs two characters.</p>\n</div>\n<div class="analogy">\n  <h3>Analogy: The Invisible Hands</h3>\n  <p>Imagine every force as an invisible hand. Watch a leaf settle to the ground and you can narrate the hands at work: gravity\'s hand pulling it steadily down, the air\'s hand brushing upward against it. Physicists never see forces either — they read them from what the motion does.</p>\n</div>'},{id:"friction-and-springs",title:"Friction & Elastic Forces",content:'\n<p>Slide a book across a table and it always stops. Nothing visible grabs it — what stops it is <strong>friction</strong>, the force that appears whenever two surfaces rub. Zoom in on even a polished tabletop and you would find a mountain range of microscopic bumps; sliding means dragging one mountain range across another, and that resistance is friction.</p>\n<p>Friction is a two-faced friend:</p>\n<ul>\n  <li><strong>We fight it</strong> when it wastes effort: oil in engines, ball bearings in wheels, wax on skis, the smooth ice of a rink — all are tricks for reducing friction.</li>\n  <li><strong>We depend on it</strong> constantly: without friction you could not walk (your shoes would slip as on perfect ice), cars could not grip the road, knots would untie themselves, and a nail would slide straight out of the wall. Tyre treads and shoe soles are designed to <em>increase</em> friction.</li>\n</ul>\n<p>A second everyday force lives in stretched and squashed things. Pull a rubber band and you feel it pull back; the further you stretch, the harder it resists. Squash a sponge and it pushes outward, springing back the moment you let go. This is the <strong>elastic force</strong>: certain materials fight to return to their natural shape. Springs in mattresses, trampolines, bows, pens, and bathroom scales all exploit it. (Bathroom scales literally measure how much your weight squashes a spring.)</p>\n<p>Stretch anything too far, though, and it stops springing back — a rubber band snaps, a spring stays bent. Every elastic material has its limit.</p>\n<div class="did-you-know">\n  <h4>Try it yourself</h4>\n  <p>Make a friction ramp: tilt a large book or tray and place a coin, an eraser, and an ice cube (or a wet bottle cap) at the top. Slowly increase the tilt. The ice slides first, the coin next, the rubbery eraser last — the grippier the surface pair, the steeper the slope needed before the pull of gravity beats friction. Now tape a strip of sandpaper or a rough cloth to the ramp and watch the order change.</p>\n</div>'},{id:"magnets-and-poles",title:"Magnets & Their Poles",content:'\n<p>Most forces need contact — you cannot push a door without touching it. Magnets break that rule: a magnet pulls a steel paper clip <strong>across empty space</strong>, through air, through a sheet of paper, even through water. This "action at a distance" is what makes magnets feel like magic, and it is your first meeting with the idea that a force can reach out through a region of space.</p>\n<p>The essential facts, all checkable at your kitchen table:</p>\n<ul>\n  <li>Every magnet has two ends called <strong>poles</strong> — north and south. Cut a magnet in half and you do not get a lone north and a lone south; you get two smaller magnets, each with both poles.</li>\n  <li><strong>Opposite poles attract; like poles repel.</strong> Bring two north poles together and you can feel a springy, invisible cushion pushing them apart. Repulsion is the sure test for a magnet — attraction alone might just mean unmagnetized steel.</li>\n  <li>Magnets attract only a few materials — iron and steel above all (plus nickel and cobalt). Aluminium foil, copper coins, plastic, glass, and wood are ignored completely. "Metal" and "magnetic" are not the same thing.</li>\n  <li>The pull weakens rapidly with distance: a paper clip leaps to a magnet a centimetre away but feels nothing from across the table.</li>\n</ul>\n<p>The Earth itself behaves like a colossal, weak magnet — which is why a freely swinging magnetized needle settles pointing north-south. That is all a compass is, and sailors trusted their lives to this piece of physics for a thousand years.</p>\n<div class="did-you-know">\n  <h4>Did You Know?</h4>\n  <p>Migrating birds, sea turtles, and even some bacteria can sense the Earth\'s magnetism and use it to navigate — a built-in compass, refined by evolution long before humans discovered lodestones.</p>\n</div>'},{id:"balance-levers-floating",title:"Balance, Levers & Floating",content:'\n<p>When two forces on an object pull with equal strength in opposite directions, they cancel: the forces are <strong>balanced</strong> and the object stays put. A book resting on a table is not force-free — gravity pulls it down while the table pushes it up, in a perfect standoff. A tug-of-war with neither side moving is the same standoff made visible.</p>\n<p>The <strong>lever</strong> is the oldest force-multiplying trick humans know. A rigid bar tipping about a fixed point (the <strong>pivot</strong>) lets a small push win against a big load — provided the small push acts far from the pivot and the load sits close to it. A see-saw says it plainly: a small child far from the middle balances a heavy adult sitting near it. <strong>Distance from the pivot trades against force.</strong> Crowbars, wheelbarrows, scissors, bottle openers, and door handles are all levers in disguise; that is why a longer wrench loosens a stubborn bolt more easily.</p>\n<p>Floating is a force standoff too. Push an inflated ball underwater and you feel the water pushing it firmly back up. Every liquid pushes upward on anything placed in it — the <strong>upthrust</strong>. Whether an object floats or sinks is a duel: gravity pulling down versus upthrust pushing up. A stone loses the duel and sinks; a cork wins and floats.</p>\n<p>What decides the winner is not weight alone but weight <em>for its size</em>. A massive steel ship floats because its hull encloses so much air that, taken as a whole, it is light for its enormous size; a small dense pebble sinks. Squeeze a lump of foil into a tight ball and it sinks; shape the same foil into a boat and it floats.</p>\n<div class="did-you-know">\n  <h4>Try it yourself</h4>\n  <p>Fill a bowl with water. Shape a piece of kitchen foil into a little boat — it floats, and will even carry a cargo of coins. Now crumple the identical piece of foil into a tight ball and it sinks. Same material, same weight; only the shape, and therefore the size for that weight, has changed.</p>\n</div>'}],quiz:[{question:"An astronaut travels from Earth to the Moon. What happens to her mass and weight?",options:["Both mass and weight stay the same","Mass stays the same; weight becomes about one-sixth","Weight stays the same; mass becomes about one-sixth","Both become about one-sixth"],correctIndex:1,explanation:"Mass is the amount of matter in her body, and no journey changes that. Weight is the pull of gravity on that mass — and since the Moon's gravity is about one-sixth as strong as Earth's, her weight drops to about one-sixth while her mass is untouched."},{question:"Which situation shows friction being helpful rather than a nuisance?",options:["A car's brakes gripping the wheels to stop at a red light","An engine part wearing out from rubbing","A drawer that sticks and is hard to open","A cyclist slowed down by a rusty, unoiled chain"],correctIndex:0,explanation:"Brakes work entirely by friction: pads rub against the wheel and the grip slows the car. Walking, driving, and holding objects all depend on friction — it is only a nuisance when it resists motion we want, as in the other three cases."},{question:"What is the one sure test that an object is itself a magnet?",options:["It is attracted to a magnet","It is made of metal","It repels one pole of a known magnet","It feels heavy for its size"],correctIndex:2,explanation:"Plain iron or steel is attracted to either pole of a magnet, so attraction proves nothing. Only a magnet can repel — like poles push apart — so repulsion is the definitive test."},{question:"A huge steel ship floats while a small steel bolt sinks. Why?",options:["The ship's engines constantly push it upward","Salt water only holds up large objects","The ship is made of a special floating steel","The ship's hull encloses so much air that it is light for its overall size, so the water's upthrust can win"],correctIndex:3,explanation:"Floating is a duel between gravity (down) and the water's upthrust (up). What matters is weight for its size: the hollow hull makes the ship-as-a-whole light for the huge space it occupies, so upthrust wins. The solid bolt is heavy for its small size, so gravity wins."}]},{id:"light-and-shadow",title:"Light & Shadow",subtitle:"Where light comes from, how it travels, and what happens when something blocks it",sections:[{id:"light-sources-and-seeing",title:"Light Sources & How We See",content:'\n<p>Some things make their own light: the Sun, a candle flame, a light bulb, a firefly, a phone screen. These are <strong>light sources</strong>. Everything else — the Moon, this page, your own face in a mirror — is visible only because it <strong>bounces light from a source</strong> into your eyes. The Moon is the classic surprise: it produces no light of its own and shines purely by reflecting sunlight, like a dusty grey mirror hanging in space.</p>\n<p>That leads to the central rule of seeing: <strong>you see an object when light from it enters your eye</strong>. For a lamp, the light comes directly. For a book, light from the lamp bounces off the page and then enters your eye. Two steps, but the last step is always the same — no light into the eye, no seeing.</p>\n<p>The proof is <strong>darkness</strong>. In a room with truly no light — a windowless cellar at night — you see nothing at all, no matter how long you wait. Your eyes never "adjust to total darkness" because there is nothing to adjust to; the adjusting we experience at night is our eyes becoming more sensitive to the small amounts of light that are still present (moonlight, starlight, a distant streetlamp under the door).</p>\n<p>The ancient Greeks had it backwards: several believed the eye sent out invisible rays that felt objects, like a torch beam in reverse. The cellar test defeats that idea in one move — if eyes emitted their own rays, we could see in a coal mine.</p>\n<div class="key-concept">\n  <h3>Key Concept: Source → Object → Eye</h3>\n  <p>Every act of seeing is a delivery of light along a path: from a source, possibly bouncing off objects, and finally into your eye. Trace that path and you can explain every shadow, mirror, and reflection in this chapter.</p>\n</div>\n<div class="did-you-know">\n  <h4>Did You Know?</h4>\n  <p>Light is the fastest thing in the universe — about 300,000 km every second. Sunlight still needs over 8 minutes to reach Earth, so you always see the Sun as it was 8 minutes ago.</p>\n</div>'},{id:"straight-lines-and-shadows",title:"Straight Lines & Shadows",content:"\n<p>Light travels in <strong>straight lines</strong>. You have seen the evidence often: sunbeams slicing through gaps in clouds, a torch beam cutting through mist, laser pointers, the crisp edge of the light patch a window throws on the floor. Light never bends around a corner on its own — which is why you cannot see around corners without a mirror.</p>\n<p>Straight-line travel explains <strong>shadows</strong> completely. Put an object in light's path and the light cannot swerve around it; behind the object lies a region the light simply cannot reach. That region of blocked light is the shadow. Three consequences follow, each one checkable:</p>\n<ul>\n  <li><strong>A shadow takes the outline of the object that casts it</strong> — the straight rays project the object's silhouette onto whatever is behind.</li>\n  <li><strong>Shadows fall on the opposite side from the source.</strong> Walk away from a low evening sun and your shadow stretches ahead of you.</li>\n  <li><strong>The geometry sets the size.</strong> Move an object close to a lamp and its shadow on the wall grows huge; move it near the wall and the shadow shrinks toward the object's true size. Shadow puppetry is nothing but this rule performed with skill.</li>\n</ul>\n<p>The same logic runs on the grandest scale. Your shadow at noon is short because the Sun stands high; in the evening it stretches long because the Sun sits low. And a solar eclipse is simply the Moon's shadow falling on the Earth — the everyday physics of a hand blocking a lamp, enlarged to the size of worlds.</p>\n<div class=\"did-you-know\">\n  <h4>Try it yourself</h4>\n  <p>In a dark room, shine a phone torch at a wall and hold your hand halfway between. Now move your hand slowly toward the torch: the shadow grows enormous and its edges soften. Move your hand toward the wall: the shadow shrinks and sharpens. You are watching straight-line rays being blocked, and you can predict every change before it happens.</p>\n</div>"},{id:"reflection-and-mirrors",title:"Reflection & Mirrors",content:'\n<p>When light strikes a surface, some of it bounces off — that is <strong>reflection</strong>. Every surface you can see is reflecting light; the difference between a page and a mirror is <em>how</em> they reflect it.</p>\n<ul>\n  <li>A rough surface, like paper — microscopically full of bumps — scatters incoming light in all directions. That scattered light is what lets everyone in the room see the page from wherever they sit.</li>\n  <li>A mirror is so smooth that light bounces off cleanly and in an orderly way, like a ball rebounding from a flat wall. The ordered bounce preserves the pattern of the incoming light — and a preserved pattern is exactly what an <strong>image</strong> is.</li>\n</ul>\n<p>The bounce itself follows one tidy rule: light leaves a mirror at the same angle it arrived, just as a snooker ball rebounds off the cushion at the angle it came in. From this one rule comes everything mirrors do — including letting you see around corners: light from a hidden object strikes the angled mirror and rebounds toward your eye. Periscopes, car wing mirrors, and shop security mirrors are all corner-seeing machines.</p>\n<p>Your reflection holds two famous puzzles. First, the person in the mirror appears to stand <em>behind</em> the glass, exactly as far behind as you stand in front — step back and your image steps back too. Second, mirrors appear to swap left and right (your raised right hand looks like the image\'s left) yet never swap up and down. Wave and watch; being puzzled by this is a centuries-old tradition.</p>\n<div class="analogy">\n  <h3>Analogy: The Bouncing Ball</h3>\n  <p>Throw a ball straight down at a smooth floor and it returns straight up; throw it at a slant and it bounces away at the matching slant. Light off a mirror behaves exactly like that ball. Now imagine throwing the ball at a cobblestone street — it could rebound anywhere. That is paper: same bounce, messy surface.</p>\n</div>'},{id:"transparency",title:"Transparent, Translucent, Opaque",content:'\n<p>Hold different materials up to a window and they sort themselves into three families by what they do to light:</p>\n<table>\n  <thead>\n    <tr><th>Family</th><th>What light does</th><th>What you see through it</th><th>Examples</th></tr>\n  </thead>\n  <tbody>\n    <tr><td><strong>Transparent</strong></td><td>Passes almost straight through</td><td>A clear view</td><td>Window glass, still water, cling film</td></tr>\n    <tr><td><strong>Translucent</strong></td><td>Gets through, but scrambled and scattered</td><td>Light and blurry shapes, no detail</td><td>Frosted glass, baking paper, a thin curtain</td></tr>\n    <tr><td><strong>Opaque</strong></td><td>Blocked — absorbed or reflected</td><td>Nothing</td><td>Wood, brick, metal, your hand</td></tr>\n  </tbody>\n</table>\n<p>The shadow test tells the families apart instantly: opaque objects cast dark, crisp shadows; translucent ones cast pale, fuzzy shadows; transparent ones cast almost none. And notice the design decisions all around you — bathroom windows are frosted (translucent) precisely because they should deliver light but not images, while windscreens must be flawlessly transparent because a driver needs the detail, not just the brightness.</p>\n<p>Transparency has one more surprise. Light passing from air into water or glass gets slightly <strong>bent</strong> at the boundary — which is why a straw in a glass of water appears broken at the waterline and why a swimming pool always looks shallower than it really is. The bending of light by shaped transparent material is the whole working principle of lenses: spectacles, magnifying glasses, cameras, telescopes, and the living lens inside your own eye.</p>\n<div class="did-you-know">\n  <h4>Try it yourself</h4>\n  <p>Place a coin in the bottom of an empty mug and step back until the rim just hides the coin from view. Hold your head still while you (or a helper) slowly pour in water: the coin comes back into view, apparently lifted into sight. Light from the coin is being bent at the water\'s surface on its way to your eye — bending you can summon on demand at the kitchen sink.</p>\n</div>'}],quiz:[{question:"Why can we see the Moon at night?",options:["The Moon produces its own light like a star","The Moon reflects light from the Sun toward our eyes","Moonlight is starlight collected by the Moon","Our eyes emit rays that reach the Moon"],correctIndex:1,explanation:"The Moon is not a light source — it shines only by bouncing sunlight toward us. We see any non-source object the same way: light from a source reflects off it and enters our eyes. And eyes emit nothing, which is why total darkness means total blindness."},{question:"You hold your hand between a torch and a wall, then move the hand closer to the torch. What happens to its shadow on the wall?",options:["It gets bigger","It gets smaller","It stays the same size","It disappears"],correctIndex:0,explanation:"Light spreads out from the torch in straight lines. The closer the hand is to the torch, the larger the cone of light it blocks by the time those straight rays reach the wall — so the shadow grows. This straight-line geometry is the whole physics of shadow puppets."},{question:"Both a sheet of paper and a mirror reflect light. Why does only the mirror show your image?",options:["Paper absorbs all the light that hits it","Mirrors add their own light to the reflection","Paper only reflects white light","The mirror is smooth, so light bounces off in an orderly way that preserves the pattern; rough paper scatters it"],correctIndex:3,explanation:"Both surfaces reflect. Paper's microscopic roughness scatters light in all directions, destroying any pattern — which is why you can read a page from any angle but see no reflection in it. A mirror's smoothness keeps the reflected rays organized, and an organized pattern of light is exactly what an image is."},{question:"Which material would cast the palest, fuzziest shadow?",options:["A brick (opaque)","A pane of clear glass (transparent)","A sheet of baking paper (translucent)","A steel plate (opaque)"],correctIndex:2,explanation:"Translucent materials let light through but scatter it on the way, so they cast weak, blurred shadows. Opaque materials block light fully (dark, sharp shadows), and transparent ones let it pass almost undisturbed (almost no shadow)."}]},{id:"sound-and-vibration",title:"Sound & Vibration",subtitle:"Every sound is something shaking — pitch, loudness, travel, and hearing",sections:[{id:"sound-from-vibration",title:"Sound Comes from Vibration",content:'\n<p>Every sound you have ever heard — a guitar chord, a slammed door, your own name — began with something <strong>vibrating</strong>: moving back and forth very fast. This is the one law of sound, and it has no exceptions.</p>\n<p>Sometimes the vibration is visible. Pluck a guitar string hard and you can see it as a blur; strike a cymbal and watch its edge shimmer. A struck drum skin visibly trembles, and grains of rice placed on it will dance. Sometimes the vibration is too small or too fast to see — a struck wine glass looks perfectly still while it rings — but it is always there, and there is a lovely way to prove it: touch the ringing glass and the sound stops instantly. Your finger killed the vibration, and the sound died with it. Silencing-by-touching is exactly how cymbal players end a crash.</p>\n<p>You can also <em>feel</em> vibrations you cannot see. Rest your fingertips lightly on your throat and hum: the buzzing you feel is your <strong>vocal cords</strong> vibrating — that buzz is your voice. Place a hand on a speaker playing music and the cabinet trembles against your palm, strongest during the bass notes.</p>\n<p>What reaches your ear is the vibration passed along by the air. The shaking object pushes on the air next to it, that air pushes on the air beyond, and the disturbance races outward in all directions — like ripples spreading from a pebble dropped in a pond, but in three dimensions and invisible. When those ripples of trembling air arrive at your ear, you hear.</p>\n<div class="key-concept">\n  <h3>Key Concept: No Vibration, No Sound</h3>\n  <p>Stop the vibration and the sound stops with it — instantly, every time. Sound is not a thing objects contain; it is the motion they perform.</p>\n</div>\n<div class="did-you-know">\n  <h4>Try it yourself</h4>\n  <p>Hold a ruler flat on a table with half sticking over the edge. Twang the free end: you can simultaneously <em>see</em> the blur of vibration and <em>hear</em> the note. Now slide the ruler inward and twang again — a shorter free end vibrates visibly faster and the note jumps higher. In ten seconds you have discovered the next section\'s law for yourself.</p>\n</div>'},{id:"pitch-and-loudness",title:"Pitch & Loudness",content:"\n<p>Sounds differ from each other in two independent ways, and each traces back to a property of the vibration.</p>\n<p><strong>Pitch</strong> is how high or low a note sounds — a flute versus a tuba, a child's voice versus a bass singer. Pitch is set by how <strong>fast</strong> the vibration is: fast vibrations make high notes, slow vibrations make low ones. Watch it on any string instrument. The thick, long, heavy strings vibrate lazily and give the low notes; the thin, short strings whip back and forth quickly and give the high notes. A guitarist's fingers are pitch engineers: pressing a fret shortens the vibrating length, the vibration speeds up, the note rises. Small things generally vibrate faster than big ones — which is why the piccolo is tiny, the double bass is huge, and a mosquito's whine is higher than a bumblebee's drone (its little wings beat faster).</p>\n<p><strong>Loudness</strong> is how strong a sound is, and it is set by how <strong>big</strong> the vibration is — how far the object swings on each back-and-forth. Pluck a string gently and it barely trembles: a quiet note. Pluck the same string hard and it swings in a wide blur: a loud note at exactly the same pitch. Gentle tap, wide whack — same drum, same pitch, different loudness.</p>\n<p>The two are fully independent: a sound can be high and quiet (a distant whistle), high and loud (a smoke alarm), low and quiet (distant thunder), low and loud (that same thunder overhead).</p>\n<table>\n  <thead>\n    <tr><th>You change…</th><th>By changing…</th><th>Example</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>Pitch</td><td>Speed of vibration</td><td>Shorter string → faster → higher note</td></tr>\n    <tr><td>Loudness</td><td>Size of vibration</td><td>Harder pluck → wider swing → louder note</td></tr>\n  </tbody>\n</table>\n<div class=\"did-you-know\">\n  <h4>Did You Know?</h4>\n  <p>Dogs hear vibrations far too fast for human ears — that is the trick of the \"silent\" dog whistle. Bats go further still, navigating in darkness by shouting ultra-high squeaks and listening for the echoes bouncing off obstacles and insects.</p>\n</div>"},{id:"how-sound-travels",title:"How Sound Travels",content:'\n<p>Sound needs a medium — some stuff to travel <em>through</em>. Air is the usual carrier, but it is far from the only one, and not even the best one.</p>\n<p>Sound travels through <strong>solids</strong>, and superbly. Put your ear flat on a wooden table and gently scratch the far end: the scratch arrives loud and crisp through the wood, though it is almost inaudible through the air. Children whispering through a taut string telephone, a wall transmitting the neighbour\'s bass, train robbers in old westerns listening to the rail for a distant train — all solid-borne sound. It travels through <strong>liquids</strong> too: swimmers hear pool sounds with their heads underwater, and whale song carries for hundreds of kilometres through the ocean.</p>\n<p>The particle picture explains the ranking. Sound is a shove passed from particle to particle. In a solid the particles are packed tightly against each other, so the shove passes on instantly, like a push travelling down a line of people standing shoulder to shoulder. In a gas the particles are far apart, so the relay is slower and weaker. Hence the rule of thumb: <strong>solids carry sound best, liquids next, gases last</strong> — the reverse of what most people guess.</p>\n<p>And where there are no particles at all, there is no sound. In the vacuum of space, an explosion is perfectly silent — there is nothing to pass the vibration along. (Films get this wrong for drama.) Light crosses empty space happily; sound cannot take one step into it.</p>\n<p>Sound is fast, but nowhere near light-fast: roughly 340 metres per second in air, about a kilometre every three seconds. That gap between light speed and sound speed is something you have already noticed — it is the pause between lightning and thunder.</p>\n<div class="did-you-know">\n  <h4>Try it yourself</h4>\n  <p>Count the storm. When you see a lightning flash, count the seconds until the thunder: the flash arrives essentially instantly, the rumble at about 1 km every 3 seconds. Nine seconds means the strike was about 3 km away. Count again for the next flash and you can tell whether the storm is approaching or leaving.</p>\n</div>'},{id:"hearing",title:"Hearing — and Protecting It",content:'\n<p>Your ear is a vibration detector of astonishing sensitivity, and its working principle is exactly the drum-skin physics of this chapter, miniaturized.</p>\n<p>The visible outer ear is a funnel. It gathers the ripples of trembling air and channels them down a short canal to the <strong>eardrum</strong> — a taut membrane, much like the skin of a tiny drum. Arriving vibrations make the eardrum tremble in sympathy: fast for high notes, slow for low, hard for loud, gently for soft. On the far side, a chain of the three tiniest bones in your body passes the trembling inward, where it becomes signals travelling along a nerve to the brain. Everything you have ever heard — every voice and every song — entered your life as the shaking of that little membrane.</p>\n<p>Why two ears? Direction. A sound from your left reaches the left ear a fraction sooner, and slightly louder, than the right. Your brain reads that tiny difference and instantly points your attention the right way. Close your eyes and you can still tell where a snap of the fingers came from.</p>\n<p>A detector this delicate can be damaged by what it detects. Violent vibrations — one explosive bang, or loud music poured in through earphones for hours — can overload the sensitive parts of the inner ear, and unlike a scraped knee, <strong>that damage does not heal</strong>. Hearing loss from noise is permanent, which is why workers on runways and building sites wear ear defenders by law. A useful personal warning sign: if your ears ring after a loud event, they were overdriven. The advice is simple and worth taking seriously: keep the volume moderate, give your ears quiet breaks, and treat ringing as the alarm bell it is.</p>\n<div class="analogy">\n  <h3>Analogy: The Drum in Your Head</h3>\n  <p>A drummer strikes a drum skin and it vibrates to make sound. Your eardrum runs the same event in reverse: arriving sound strikes the skin and makes it vibrate. One membrane turns motion into sound; the other turns sound back into motion.</p>\n</div>'}],quiz:[{question:"A wine glass rings after being struck. You touch it lightly and the sound stops immediately. Why?",options:["Your finger absorbs the sound that was stored in the glass","Touching it stops the vibration, and without vibration there is no sound","Your skin blocks sound from leaving the glass","The glass cools down when touched"],correctIndex:1,explanation:"Sound is not stored in objects — it is produced continuously by their vibration. The glass was still trembling (too finely to see), your finger damped that trembling, and the sound died with it. No vibration, no sound: the one law of sound."},{question:"What must change about a vibration to make its note higher in pitch?",options:["It must vibrate faster","It must swing through a bigger distance","It must vibrate more slowly","It must come from a bigger object"],correctIndex:0,explanation:"Pitch is set by vibration speed: faster back-and-forth means a higher note. That is why shortening a guitar string (making it vibrate faster) raises its pitch. The size of the swing controls loudness instead — the two properties are independent."},{question:"Why does a distant train become audible through the rail before it can be heard through the air?",options:["Metal amplifies all sounds","Sound cannot really travel through air at all","The train pushes sound down into the ground","The rail's tightly packed particles pass the vibration along faster and better than the spread-out particles of air"],correctIndex:3,explanation:"Sound is a shove relayed from particle to particle. In a solid like steel the particles press right against each other, so the relay is fast and efficient; in a gas they are far apart, so it is slower and weaker. Solids carry sound best, liquids next, gases last — and a vacuum, with no particles, carries none."},{question:"You see lightning and hear the thunder 6 seconds later. Roughly how far away was the strike?",options:["About 6 km","About 20 km","About 2 km","Right overhead — the delay means nothing"],correctIndex:2,explanation:"Light arrives essentially instantly, while sound crawls along at roughly 1 km every 3 seconds. Six seconds of delay therefore means about 2 km. The flash-to-rumble count is a genuine distance measurement you can make with no instrument but patience."}]},{id:"heat-and-cold",title:"Heat & Cold",subtitle:"Temperature, heat flow, expansion, and the three ways warmth gets around",sections:[{id:"temperature-vs-heat",title:"Temperature vs Heat",content:'\n<p>Everyday speech uses "hot" and "heat" loosely, but physics keeps two ideas carefully apart — and once you feel the difference, a lot of kitchen mysteries dissolve.</p>\n<p><strong>Temperature</strong> is how hot something is — a level, measured in degrees. In the particle picture, temperature tells you how vigorously the particles of a substance are jiggling: fast jiggling means high temperature, sluggish jiggling means low. A thermometer reads that level: 37 \xb0C for your body, 0 \xb0C for freezing water, 100 \xb0C for boiling water, around 20 \xb0C for a comfortable room.</p>\n<p><strong>Heat</strong> is warmth <em>on the move</em> — energy flowing from a hotter thing to a colder one. And it flows in only that direction, always. Put a warm hand on a cold window: heat flows from hand to glass, never the reverse. Leave hot tea on the table and heat leaks from tea to room until both match. Everything left alone drifts toward the temperature of its surroundings — the fate of every forgotten cup of tea and every softening tub of ice cream.</p>\n<p>The two ideas really are different, and here is the classic pair to prove it: a burning matchhead has a far <strong>higher temperature</strong> than a bathtub of warm water, yet the bathtub holds vastly <strong>more heat to give</strong> — the match could not warm a cold bathroom, but the tubful of water can. Level and amount are different things.</p>\n<p>One more correction from the particle picture: <strong>there is no such substance as "cold"</strong>. Cold is not a thing that flows into you; it is merely the absence of heat, as darkness is the absence of light. A draught from the fridge does not deliver coldness to your skin — your skin loses its heat to the cool air.</p>\n<div class="analogy">\n  <h3>Analogy: Water Level and Water Amount</h3>\n  <p>Temperature is like water <em>level</em>; heat flow is like water <em>current</em>. Connect a full high tank to a low one and water flows downhill until the levels equalize — regardless of which tank holds more water. Heat likewise flows from higher temperature to lower until the temperatures level out, no matter which object is bigger.</p>\n</div>'},{id:"expansion-and-contraction",title:"Expansion & Contraction",content:'\n<p>Here is a quiet fact with loud consequences: <strong>almost everything swells slightly when heated and shrinks slightly when cooled</strong>. The particle picture says why — hotter particles jiggle more vigorously and elbow themselves a little more room; cooled particles calm down and settle closer together. The substance itself doesn\'t change, and nothing is added or removed: the same particles simply take up a bit more or less space.</p>\n<p>The changes are small, but the world is full of their fingerprints:</p>\n<ul>\n  <li><strong>Railways and bridges</strong> are built with small expansion gaps so summer heat can lengthen the metal without buckling it. Long bridges sit on rollers; the roadway includes comb-toothed joints that clack under your car wheels — that clack is expansion engineering.</li>\n  <li><strong>Power lines</strong> sag noticeably more on hot days: kilometres of warmed metal add up to real extra length.</li>\n  <li><strong>The stuck jam-jar lid</strong> surrenders under hot water because the heated metal lid expands faster than the glass beneath it, loosening its grip — grandmother\'s trick, particle physics underneath.</li>\n  <li><strong>Creaking houses</strong> at night are the sounds of roofs and pipes contracting as they cool after a warm day.</li>\n</ul>\n<p>Liquids expand too, and one instrument depends on it: the classic <strong>thermometer</strong> is just a bulb of liquid and a hair-thin tube. Warmth makes the liquid expand, and the only place the extra volume can go is up the tube. The scale printed alongside converts "how far it crept up" into degrees. Gases expand most eagerly of all — a sealed balloon swells in a warm room, and a dented ping-pong ball can be re-rounded in hot water as the air inside it pushes outward.</p>\n<div class="did-you-know">\n  <h4>Try it yourself</h4>\n  <p>Stretch a balloon over the neck of an empty glass bottle. Stand the bottle in a bowl of hot tap water: the balloon slowly inflates as the air inside warms and expands. Move the bottle to a bowl of iced water and the balloon deflates and may even get sucked inward as the cooling air contracts. Same air throughout — only its temperature, and therefore its spread, has changed.</p>\n</div>'},{id:"how-heat-travels",title:"Conduction, Convection & Radiation",content:"\n<p>Heat gets from hot places to cold places in exactly three ways. Every warming and cooling you have ever experienced is one of the three, or a combination.</p>\n<p><strong>Conduction</strong> is heat passed through a material by touch, particle to jiggling particle. Heat the tip of a metal spoon and soon the handle burns your fingers: each vigorously jiggling particle jostles its neighbour, and the agitation travels along like a rumour down a packed row of seats. Metals are superb conductors; wood, plastic, wool, and air are poor ones — which is why the pan is metal but its handle is plastic.</p>\n<p><strong>Convection</strong> is heat carried by a moving liquid or gas. Air warmed by a radiator expands, becomes lighter for its size, and floats upward; cooler air slides in beneath, gets warmed, and follows. The result is a slow merry-go-round of air that carries warmth around the whole room. Convection is why the air near the ceiling is warmest, why a radiator heats a whole room rather than just the air touching it, and — in the pan — why soup heated only from below ends up hot throughout.</p>\n<p><strong>Radiation</strong> is heat that travels as invisible rays, needing no material at all. It is how the Sun's warmth crosses 150 million kilometres of empty space, how a bonfire toasts your face from metres away (the air between you stays cool — step behind a person and their body blocks the rays like a shadow), and why a parked car's dashboard bakes behind closed windows.</p>\n<table>\n  <thead>\n    <tr><th>Route</th><th>Carrier</th><th>Everyday example</th></tr>\n  </thead>\n  <tbody>\n    <tr><td><strong>Conduction</strong></td><td>Particles jostling neighbours in place</td><td>Spoon handle heating up in soup</td></tr>\n    <tr><td><strong>Convection</strong></td><td>Warm liquid or gas physically rising and circulating</td><td>Radiator warming a whole room</td></tr>\n    <tr><td><strong>Radiation</strong></td><td>Invisible rays, no material needed</td><td>Sunshine; a bonfire's glow on your face</td></tr>\n  </tbody>\n</table>\n<div class=\"key-concept\">\n  <h3>Key Concept: One Campfire, All Three Routes</h3>\n  <p>Sit by a campfire holding a metal marshmallow skewer. Your face is toasted by <strong>radiation</strong>, the smoke and hot air rise by <strong>convection</strong>, and the skewer's handle slowly heats by <strong>conduction</strong>. Any real heating situation is usually all three at once.</p>\n</div>"},{id:"insulation",title:"Insulation: The Art of Slowing Heat",content:'\n<p>Heat cannot be stopped, but it can be magnificently <strong>delayed</strong> — and that delay is a technology as old as clothing. A material that conducts heat poorly is an <strong>insulator</strong>, and the champion insulator is one you cannot even see: <strong>trapped, still air</strong>.</p>\n<p>Air conducts heat very badly, provided it cannot move (moving air would carry heat away by convection). So the great insulators are all, secretly, devices for holding air still: wool traps air among its fibres, duvets and puffer jackets trap it in fluffy filling, double-glazed windows trap a layer between glass panes, foam is riddled with air bubbles. When a bird fluffs up on a cold day, it is thickening its own trapped-air jacket.</p>\n<p>Two corrections to everyday intuition follow:</p>\n<ul>\n  <li><strong>A jumper does not produce warmth.</strong> Your body is the heater; the wool merely slows the escape of the heat you constantly generate. That is why a sweater on a snowman does not melt him — with no heat inside to keep in, the wool has nothing to do (in fact it slows the day\'s warmth from reaching him).</li>\n  <li><strong>Insulation works both ways.</strong> The same cool-box that keeps soup hot keeps ice cream frozen; the same duvet that warms you in winter can keep a cold drink cold. An insulator does not choose a direction — it simply slows heat flow across itself, whichever way heat is trying to go.</li>\n</ul>\n<p>The vacuum flask is the masterpiece of the art: its double wall encloses not even air but a near-vacuum, which conduction and convection simply cannot cross (no particles!), plus a silvered lining to reflect radiation back. All three heat routes blocked at once — hot coffee at noon or iced tea, the flask neither knows nor cares.</p>\n<div class="did-you-know">\n  <h4>Try it yourself</h4>\n  <p>Take three ice cubes. Leave one on a plate, wrap one loosely in a tea towel, and wrap one snugly in a woolly hat or scarf. Guess which survives longest — most people pick the naked one, expecting wool to "warm" the ice. Check every 20 minutes: the wrapped cubes outlast the bare one by far, because the wool\'s trapped air slows the room\'s heat from getting <em>in</em>. Insulation slows heat flow in both directions.</p>\n</div>'}],quiz:[{question:"A lit match has a much higher temperature than a bathtub of warm water. Which statement is correct?",options:["The bathtub holds far more heat to give, despite its lower temperature","The match also holds more heat to give than the bathtub","Temperature and heat are two words for the same thing","The bathtub must be hotter, because it is bigger"],correctIndex:0,explanation:"Temperature is a level (how vigorously particles jiggle); heat is an amount of energy that can flow. The tiny match sits at a high level but has little to give; the huge tubful sits at a modest level but can warm a whole cold room. Level and amount are different ideas — that is the heart of this chapter."},{question:"Why does running hot water over a stuck metal jam-jar lid loosen it?",options:["The heat melts the jam sealing the lid","Hot water lubricates the thread","The metal lid expands more and faster than the glass jar, loosening its grip","The glass jar expands and pushes the lid off"],correctIndex:2,explanation:"Nearly all materials expand when heated, but not equally: the thin metal lid warms quickly and expands more than the glass beneath it, so its grip slackens. Grandmother's kitchen trick is applied expansion physics."},{question:"Standing two metres from a bonfire, your face feels hot even though the air between you and the fire is cool. How is the heat reaching you?",options:["Conduction through the air's particles","Convection currents blowing toward you","Radiation — invisible rays that need no material to travel","Sound waves carrying the heat"],correctIndex:2,explanation:"Conduction through air is feeble, and convection carries the fire's hot air upward, not sideways at your face. What toasts you is radiation — heat travelling as invisible rays, the same route by which the Sun's warmth crosses the empty space to Earth. Step behind someone and their body blocks the rays like a shadow."},{question:"What does wrapping a woolly scarf around an ice cube do?",options:["Melts it faster, because wool is warm","Has no effect either way","Freezes it harder","Makes it last longer, because the wool's trapped air slows the room's heat from reaching the ice"],correctIndex:3,explanation:"Wool produces no warmth of its own — it is an insulator, full of trapped still air, and it simply slows heat flow across itself in either direction. On you, it keeps body heat in; on the ice cube, it keeps room heat out. The wrapped cube outlasts a bare one by a wide margin — try it."}]},{id:"electricity-and-circuits",title:"Electricity & Circuits",subtitle:"Batteries, bulbs, switches, and the loop that must never be broken",sections:[{id:"battery-and-bulb",title:"The Battery, the Bulb & the Loop",content:'\n<p>The foundation of all electrical understanding fits on a kitchen table: one battery, one small bulb, two wires. Connect them so that a path runs from one end of the battery, through the bulb, and back to the other end of the battery — and the bulb lights. Break the path anywhere, and it goes dark. That closed path is a <strong>circuit</strong>, from the same root as "circle", and the circle is the whole secret.</p>\n<p>What is happening? The battery acts as a pump, pushing a flow of electricity — a <strong>current</strong> — around the loop. The current is not used up on its journey: it flows <em>through</em> the bulb (working as it passes, which is what makes the thin wire inside glow) and returns to the battery. What the battery slowly uses up is its own stored push; when that runs out, the battery is "dead".</p>\n<p>Everything follows from the loop rule:</p>\n<ul>\n  <li><strong>Both battery ends must be used.</strong> A wire from just one end can never light a bulb — there is no circle.</li>\n  <li><strong>One break anywhere kills the whole circuit.</strong> A loose wire, a blown bulb, a gap: the current stops everywhere at once, not just at the break.</li>\n  <li><strong>The loop explains the plug.</strong> Every appliance cable hides at least two wires — electricity needs a way in <em>and</em> a way back. There are no one-way trips in a circuit.</li>\n</ul>\n<div class="analogy">\n  <h3>Analogy: The Bicycle Chain</h3>\n  <p>A bicycle chain is a loop that transmits work from pedals to wheel. The chain itself is not consumed — links are not eaten as you ride — yet it delivers effort continuously. Snap the chain at any single point and everything stops instantly, everywhere. A circuit\'s current behaves exactly like the chain: an unbroken loop that carries the push, not a fuel that gets used up.</p>\n</div>\n<div class="key-concept">\n  <h3>Key Concept: No Loop, No Light</h3>\n  <p>Every electrical fault you will ever diagnose — dead torch, silent doorbell, dark fairy-light string — comes down to one question: where is the loop broken?</p>\n</div>'},{id:"conductors-insulators-switches",title:"Conductors, Insulators & Switches",content:"\n<p>Build the battery-and-bulb loop but leave a small gap, and you have made a materials tester: bridge the gap with an object, and the bulb reports whether current can flow through it.</p>\n<ul>\n  <li>Bridge it with a <strong>metal</strong> — a paper clip, a coin, kitchen foil, a key — and the bulb lights. Metals let current flow: they are <strong>conductors</strong>.</li>\n  <li>Bridge it with <strong>plastic, rubber, glass, dry wood, paper, or fabric</strong> — and the bulb stays dark. These block current: they are <strong>insulators</strong>.</li>\n</ul>\n<p>Every electrical device is built from this pairing, and you can see it in any cable: a copper core to carry the current, wrapped in plastic so the current stays on its path and off your fingers. The wall socket's holes are metal inside, plastic outside; the electrician's screwdriver has a steel shaft and an insulating handle. Conductor for the current's path, insulator everywhere the current must not go.</p>\n<p>A <strong>switch</strong> is the loop rule turned into a convenience: a deliberate, reopenable break in the circuit. Flip it one way and a metal bridge closes the gap — current flows, light on. Flip it back and the bridge lifts — gap, no loop, light off. Nothing is \"sent\" from the switch to the lamp; the switch simply completes or breaks the one shared loop, which is why it acts instantly and why a switch can sit far away from the bulb it controls, anywhere along the loop.</p>\n<p>This on/off simplicity scales astonishingly far: a fridge-door light is switched by a button the door presses; a keyboard is a hundred switches; and at the very bottom, a computer chip is billions of microscopic switches flicking on and off billions of times each second.</p>\n<div class=\"did-you-know\">\n  <h4>Try it yourself</h4>\n  <p>With a 4.5 V flat battery or an AA holder, a torch bulb (or an LED with a battery pack from a broken toy), and kitchen-foil strips as wires, build the loop and leave a gap. Test what bridges it: spoon, coin, eraser, pencil case, key, dry paper. Metals light the bulb; plastics never do. Then try a sharpened pencil's graphite core — a famous in-between surprise. This is exactly the experiment every Japanese and Singaporean primary schooler performs, and it is worth an adult's ten minutes.</p>\n</div>"},{id:"series-vs-parallel",title:"Series vs Parallel",content:"\n<p>Add a second bulb to your circuit and you face a genuine design decision — the same decision electricians face wiring a house. There are two ways to connect it, and they behave completely differently.</p>\n<p><strong>In series</strong>, the bulbs sit one after another on a single loop, like beads on one necklace. The consequences:</p>\n<ul>\n  <li>Both bulbs glow <strong>dimmer</strong> than one alone — one battery's push now drives current through two obstacles in a row.</li>\n  <li>If either bulb fails or is removed, the single loop is broken and <strong>both go dark</strong>. Old-fashioned fairy-light strings were wired this way, and one blown bulb blacked out the whole tree — the source of a classic family Christmas ordeal, hunting the dead bulb.</li>\n</ul>\n<p><strong>In parallel</strong>, each bulb gets its <strong>own loop</strong> to the battery — two side-by-side circles sharing one pump. The consequences flip:</p>\n<ul>\n  <li>Each bulb glows at <strong>full, normal brightness</strong>, exactly as if it were alone.</li>\n  <li>If one bulb fails, the other's private loop is untouched: <strong>it keeps shining</strong>.</li>\n  <li>The price: the battery feeds two full loops at once and drains faster.</li>\n</ul>\n<p>Your home is wired in parallel, and now you can say why: every lamp and socket gets full strength, each has its own switch, and a bulb blowing in the bathroom does not darken the kitchen. Series wiring survives where its all-or-nothing behaviour is exactly the point — a fridge-door switch in series with the fridge light, a safety interlock that cuts a microwave the instant the door opens.</p>\n<table>\n  <thead>\n    <tr><th></th><th>Series (one shared loop)</th><th>Parallel (own loop each)</th></tr>\n  </thead>\n  <tbody>\n    <tr><td><strong>Brightness</strong></td><td>Dimmer with each added bulb</td><td>Full brightness each</td></tr>\n    <tr><td><strong>One bulb fails</strong></td><td>All go out</td><td>Others unaffected</td></tr>\n    <tr><td><strong>Used for</strong></td><td>Switches, safety interlocks</td><td>House wiring, car lights</td></tr>\n  </tbody>\n</table>"},{id:"electromagnets-and-safety",title:"Electromagnets & Electrical Safety",content:'\n<p>Here is one of the loveliest surprises in physics, discovered by accident in 1820 when a Danish lecturer noticed a compass needle twitch beside a current-carrying wire: <strong>an electric current creates magnetism</strong>. Coil a wire many times around an iron nail, connect the coil to a battery, and the nail becomes a magnet — it picks up paper clips exactly as a bar magnet does. Disconnect the battery and the paper clips drop instantly.</p>\n<p>That is an <strong>electromagnet</strong>, and its two superpowers put it far beyond any bar magnet. It can be <strong>switched</strong> — magnetism on demand, obedient to an ordinary switch. And it can be made <strong>stronger at will</strong>: more turns of wire, or a stronger current, give a stronger pull. Scrapyard cranes use room-sized electromagnets to lift whole cars and — the part no permanent magnet could do — release them on command. Electric doorbells, door latches that buzz open, loudspeakers, and electric motors all have an electromagnet at their heart. Whenever electricity makes something <em>move</em>, an electromagnet is usually the muscle.</p>\n<p>Respect must accompany the wonder. Battery experiments like those in this chapter are safe — a small battery\'s push is gentle. <strong>Mains electricity is a different animal entirely</strong>: its push is powerful enough to drive a dangerous current through a human body, and it must never be experimented with. The household rules all follow from physics you now understand:</p>\n<ul>\n  <li><strong>Water and mains do not mix</strong> — water on skin makes your body a much better conductor. Never touch switches or appliances with wet hands; keep hairdryers away from baths.</li>\n  <li><strong>Never poke anything into a socket</strong> — the metal contacts inside are live, and a metal object bridges them to you.</li>\n  <li><strong>Damaged insulation is an alarm</strong> — a frayed cable is a conductor with its safety jacket torn off. Stop using it.</li>\n  <li>Outdoors, kites and fishing rods stay far from overhead power lines.</li>\n</ul>\n<div class="did-you-know">\n  <h4>Try it yourself</h4>\n  <p>Wind about a metre of thin insulated wire in tight turns around a large iron nail or screw, leaving two free ends. Connect the ends to a single 1.5 V battery (briefly — the wire warms) and try picking up paper clips or pins. Then test the two superpowers: disconnect and watch the clips drop, reconnect with extra turns of wire and feel the stronger grip. You have built the working heart of every doorbell and scrapyard crane.</p>\n</div>'}],quiz:[{question:"A torch stops working. In circuit language, what has almost certainly happened?",options:["The current inside has all been eaten by the bulb","The loop is broken somewhere — dead battery, blown bulb, or a bad contact","The metal parts have become insulators","The torch has run out of stored light"],correctIndex:1,explanation:"Electricity flows only around a complete loop, and current is not consumed on the way — the battery's push is what runs down. Every dead torch is a loop question: either the pump has no push left (flat battery) or the circle is physically broken (blown bulb filament, loose contact). Find the break, fix the loop."},{question:"Which set of objects would all light the bulb when used to bridge a gap in a circuit?",options:["Coin, key, paper clip","Eraser, coin, glass marble","Plastic ruler, dry paper, spoon","Rubber band, key, cork"],correctIndex:0,explanation:"Metals conduct electricity, so the all-metal set — coin, key, paper clip — completes the circuit every time. Each other set hides at least one insulator (rubber, glass, plastic, paper, cork), and a single insulator in the path breaks the loop."},{question:"In an old-fashioned string of fairy lights, one bulb blows and the entire string goes dark. How were the bulbs wired?",options:["In parallel — each bulb on its own loop","Half in series, half in parallel","Without a battery or power source","In series — all bulbs on one shared loop"],correctIndex:3,explanation:"In a series circuit all bulbs share one single loop, so one failure breaks the path for everyone — hence the whole dark string, and the family ritual of hunting the dead bulb. House wiring is parallel for exactly this reason: every device has its own loop, so one failure strands no one else."},{question:"What can an electromagnet do that a permanent bar magnet cannot?",options:["Attract iron and steel","Have a north and a south pole","Be switched off on command, releasing whatever it holds","Work under water"],correctIndex:2,explanation:"Both magnets attract iron and both have two poles. The electromagnet's unique power is control: its magnetism exists only while current flows, so a switch turns it on and off — which is why a scrapyard crane can lift a car and then drop it on command, and why doorbells and motors are built around electromagnets rather than bar magnets."}]},{id:"energy-everywhere",title:"Energy Everywhere",subtitle:"Forms, conversions, storage, generation — and the one great rule of the universe",sections:[{id:"forms-of-energy",title:"The Many Costumes of Energy",content:'\n<p><strong>Energy</strong> is one of those words physics borrowed from everyday speech and sharpened. The working idea is simple: energy is <strong>the ability to make things happen</strong> — to move something, heat something, light something, change something. Nothing happens anywhere, ever, without energy being involved.</p>\n<p>Energy shows up wearing different costumes. Learning to spot them by name is the skill of this chapter:</p>\n<ul>\n  <li><strong>Movement energy</strong> — anything moving carries it: a rolling ball, wind (moving air), a river, a runner. The faster and heavier, the more it carries.</li>\n  <li><strong>Height energy</strong> — a stored form held by anything lifted up: water behind a high dam, a raised hammer, you at the top of a slide. Lower the object and the stored energy is released as motion.</li>\n  <li><strong>Elastic energy</strong> — stored in stretched or squashed things: a drawn bow, a wound clockwork spring, a stretched catapult band.</li>\n  <li><strong>Chemical energy</strong> — stored in substances, released when they react: food, petrol, wood, candle wax, and batteries. Your breakfast is literally your body\'s fuel tank.</li>\n  <li><strong>Heat</strong> — hot things can make other things happen (steam drives turbines); in the particle picture, heat is the jiggling of particles.</li>\n  <li><strong>Light</strong> — energy on the move as rays; sunlight powers essentially everything alive.</li>\n  <li><strong>Sound</strong> — vibration energy travelling outward.</li>\n  <li><strong>Electrical energy</strong> — energy delivered by current around a circuit; the most convenient form of all, because wires can carry it anywhere and it converts so easily into everything else.</li>\n</ul>\n<div class="key-concept">\n  <h3>Key Concept: Stored vs On-the-Move</h3>\n  <p>Notice the two families. Some forms are energy <em>in action</em> — movement, light, sound, heat flowing. Others are energy <em>waiting</em> — height, elastic, chemical. A stretched bowstring and a chocolate bar are both loaded springs, patient until called upon.</p>\n</div>\n<div class="analogy">\n  <h3>Analogy: Money in Many Currencies</h3>\n  <p>Energy is like money that exists in many currencies — cash, bank balance, gift cards. Different in form, exchangeable at every turn, and always countable as one total. Physics is the accounting.</p>\n</div>'},{id:"conversions-and-storage",title:"Conversions & Storage",content:"\n<p>Energy's forms would be mere vocabulary but for the crucial fact: <strong>energy constantly changes from one form into another</strong>, and every event — from a heartbeat to a thunderstorm — is an energy conversion. Once you see conversions, you cannot stop seeing them:</p>\n<ul>\n  <li><strong>A falling apple:</strong> height energy → movement energy.</li>\n  <li><strong>A toaster:</strong> electrical energy → heat (and a little light from the glowing elements).</li>\n  <li><strong>A candle:</strong> chemical energy in wax → light + heat.</li>\n  <li><strong>You climbing stairs:</strong> chemical energy from food → movement + height energy (plus body heat — you warm up).</li>\n  <li><strong>An archer:</strong> muscle chemistry → elastic energy in the bent bow → movement energy of the arrow.</li>\n  <li><strong>A phone:</strong> chemical energy in the battery → light (screen) + sound (speaker) + a little heat.</li>\n</ul>\n<p>Longer chains are everywhere. Follow a swing ride: food-chemistry in your legs pumps you upward (→ height), you sweep down (→ movement), up the far side (→ height again), back and forth — and friction with the air skims a little into heat on every pass, which is why an unpumped swing gradually settles to rest.</p>\n<p><strong>Storage</strong> is the art of parking energy in a patient form until needed. Humanity's storehouses: batteries (chemical), fuel tanks and woodpiles (chemical), reservoirs behind dams (height), wound springs in clockwork (elastic), and your own body fat (chemical — the tank that keeps you alive between meals). A hydroelectric country like Norway effectively banks its wealth as water held high in the mountains.</p>\n<div class=\"did-you-know\">\n  <h4>Try it yourself</h4>\n  <p>Rub your palms together hard for ten seconds — movement becomes heat you can feel immediately. Then repeatedly bend a metal paper clip back and forth about twenty times and touch the bend point to your lip (lips sense temperature finely): distinctly warm. In both cases you can feel exactly where the energy of motion went. Nothing vanished — it changed costume.</p>\n</div>"},{id:"generating-electricity",title:"Where Electricity Comes From",content:'\n<p>Electricity is the most convenient energy form — but wall sockets are not sources, only delivery points. Somewhere, right now, a machine is <strong>converting</strong> some other form of energy into the electrical energy in your walls. Nearly always, the machine is a <strong>generator</strong>: a device that produces current when spun. (It is the electromagnet story of the last chapter run backwards — there, current made magnetism and motion; here, motion and magnetism make current. A bicycle dynamo pressed against a spinning wheel is a generator you may have pedalled yourself: your legs literally light the lamp.)</p>\n<p>So the entire question of powering civilization reduces to: <strong>what shall we use to spin the generators?</strong></p>\n<ul>\n  <li><strong>Fuel-burning power stations</strong> (coal, gas): burn fuel → heat → boil water into high-pressure steam → steam blasts through a turbine, spinning it → generator. Chemical → heat → movement → electrical.</li>\n  <li><strong>Hydroelectric dams:</strong> water stored high falls through turbines. Height → movement → electrical.</li>\n  <li><strong>Wind turbines:</strong> moving air spins the blades directly. Movement → electrical.</li>\n  <li><strong>Nuclear stations:</strong> the same steam-and-turbine chain, with the water boiled by heat from atomic nuclei instead of flames.</li>\n  <li><strong>Solar panels</strong> — the one great exception: no spinning at all. The panel converts light to electrical energy directly, silently, with no moving parts.</li>\n</ul>\n<p>Trace any of these chains backwards and almost every one ends at the <strong>Sun</strong>. Sunlight lifts the water that fills the dams (evaporation → rain), drives the winds by heating the Earth unevenly, and grew the ancient plants that became coal. Flip a light switch and you are, at several removes, spending sunshine — much of it banked millions of years ago.</p>\n<div class="did-you-know">\n  <h4>Did You Know?</h4>\n  <p>A hand-cranked torch or wind-up radio contains a small generator: your arm\'s movement energy becomes electrical energy on the spot. Crank one for a minute and your arm will report, accurately, that electricity is work.</p>\n</div>'},{id:"conservation-idea",title:"The Great Rule: Energy Is Conserved",content:'\n<p>Everything in this chapter now gathers into a single law — the deepest and most reliable rule in all of physics: <strong>energy is never created and never destroyed; it only changes form</strong>. Total up the energy before any event and after it, in all its costumes, and the totals match. Always. No exception to this law has ever been observed, anywhere, in centuries of looking.</p>\n<p>The law faces an obvious everyday objection, and answering it is the true capstone. Objection: energy certainly <em>seems</em> to disappear. The swing settles to rest. The rolling ball stops. Your phone battery empties. Where did it all go?</p>\n<p><strong>Answer: into heat — gently, invisibly, and every single time.</strong> Friction with the air and the pivot skimmed the swing\'s energy into slight warmth of the surroundings. The rolling ball warmed the floor along its path, a trace too small to feel but real. The phone\'s stored chemistry left as light from the screen, sound from the speaker, and warmth you can feel on its back. Energy that "disappears" has merely converted into its most easily overlooked and hardest-to-reuse costume and spread thinly into the surroundings. The accounting always closes; you just have to remember to count the heat.</p>\n<p>The law also explains a famous impossibility. For centuries, inventors sought the <strong>perpetual-motion machine</strong> — a device that would run forever, giving out more energy than it takes in. Patent offices eventually refused to examine such applications without a working model. None ever ran, and now you know the reason: a machine cannot pay out energy it never received. Conservation is the universe\'s unbreakable bookkeeping.</p>\n<div class="key-concept">\n  <h3>Key Concept: Nothing Comes from Nowhere</h3>\n  <p>Every bit of energy that makes anything happen came from somewhere, and goes somewhere. "Where did this energy come from, and where is it going?" — carry that one question with you and you can interrogate any machine, meal, storm, or star.</p>\n</div>\n<div class="analogy">\n  <h3>Analogy: The Unbreakable Bank</h3>\n  <p>Energy is money in a bank that permits transfers but never printing or shredding. Balances move between accounts — height, motion, chemistry, heat — and the "lost" energy of a stopped swing is simply the account labelled <em>warmth of the surroundings</em>: real money, but scattered as pennies too widely to gather back up.</p>\n</div>'}],quiz:[{question:"You climb a flight of stairs. What is the main energy conversion?",options:["Electrical energy → movement energy","Chemical energy from food → height energy (plus body heat)","Height energy → chemical energy","Heat from the room → movement energy"],correctIndex:1,explanation:"Your muscles run on chemical energy stored from food. Climbing converts some of it into height energy (which you could reclaim as motion by sliding back down) — and, as always, some becomes heat, which is why exercise warms you. Food is fuel in a precise, physical sense."},{question:"In a coal-fired power station, what is the correct order of the energy chain?",options:["Chemical → heat → movement → electrical","Heat → chemical → electrical → movement","Electrical → heat → movement → chemical","Chemical → electrical → heat → movement"],correctIndex:0,explanation:"Burning coal releases stored chemical energy as heat; the heat boils water into steam; the steam spins a turbine (movement); the turbine drives the generator (electrical). Gas and nuclear stations share the same chain — only the source of the heat differs. Solar panels are the notable exception: light to electricity directly, nothing spinning."},{question:"A child stops pumping a swing and it gradually comes to rest. What happened to the swing's energy?",options:["It was destroyed — motion simply runs out","It flowed back into the child's muscles","It converted into heat, warming the air and the pivot slightly, and spread into the surroundings","It is stored in the swing, ready to restart it"],correctIndex:2,explanation:"Energy is never destroyed. Friction — against the air and in the pivot — skimmed the swing's energy into slight, unnoticeable warmth on every pass. Apparent disappearances of energy are always conversions into thinly spread heat; the conservation accounting closes once you remember to count it."},{question:"Why is a perpetual-motion machine — one that runs forever while giving out extra energy — impossible?",options:["No one has yet found a frictionless bearing","Such machines would overheat and melt","They are only impossible on Earth, not in space","Energy cannot be created, so a machine cannot pay out more than it receives"],correctIndex:3,explanation:"The obstacle is not engineering but bookkeeping: conservation of energy means output can never exceed input, because the extra would have to come from nowhere. Better bearings reduce losses but can never create a surplus — which is why patent offices stopped examining such designs, and why none has ever run."}]},{id:"earth-and-sky",title:"Earth & Sky",subtitle:"Day, night, seasons, the Moon's changing face, and our address in the universe",sections:[{id:"day-and-night",title:"Day & Night: A Spinning Earth",content:'\n<p>The Sun "rises" in the east, "crosses" the sky, and "sets" in the west — the oldest observation in human experience, and one of the most misleading. The Sun is not going anywhere. <strong>It is the Earth that moves: our planet spins on its axis, one full turn every 24 hours</strong>, and day and night are nothing more than being carried around into the sunshine and out of it.</p>\n<p>The Sun lights half the globe at any moment — the half facing it. As the Earth turns, your home town is carried across the lit half (your daytime), around into the shadowed half (your night), and back into the light (sunrise). Nothing switches on or off; you are on a slowly rotating ball beside a steady lamp.</p>\n<p>The spin explains the everyday details, too. The Earth turns from west to east, so the Sun first appears in the east and slips away in the west — and the Moon and stars appear to make exactly the same east-to-west journey each night, because the same spin sweeps your viewpoint past them all. It also makes sense of time zones: "noon" means the Sun at its highest, and the spinning Earth serves noon to Tokyo, then Delhi, then Paris, then New York in turn. When it is breakfast time in London it is already evening in Sydney — different positions on the turning ball, facing different ways relative to the Sun.</p>\n<p>Why do we feel none of this motion? For the same reason you feel nothing in a smoothly cruising aeroplane: steady motion is imperceptible — only <em>changes</em> in motion (jolts, swerves) can be felt. The ride is perfectly smooth, so people believed for millennia that the Earth stood still. It was an entirely reasonable mistake.</p>\n<div class="did-you-know">\n  <h4>Try it yourself</h4>\n  <p>In a dark room, walk slowly around a single lamp while spinning yourself gently counter-clockwise. The lamp repeatedly "rises" past your left shoulder, crosses your view, and "sets" past your right — a complete sunrise and sunset with every turn you make, while the lamp never moves at all. You have just replaced two thousand years of Sun-goes-round-the-Earth intuition with thirty seconds of physics.</p>\n</div>'},{id:"seasons",title:"The Seasons: A Tilted Planet",content:'\n<p>While spinning daily, the Earth also travels a huge, nearly circular path around the Sun, completing one lap per <strong>year</strong>. But the lap alone does not cause the seasons — the real cause is a beautiful accident: <strong>the Earth\'s spin axis is tilted</strong> (by about 23\xb0) and holds that tilt, pointing the same way in space, all the way around the orbit.</p>\n<p>So for half of each lap, the northern half of the planet leans <em>toward</em> the Sun; half a lap later it leans <em>away</em>. Leaning toward the Sun means: the Sun climbs higher in your sky, its light strikes your ground more directly (concentrated rather than spread at a slant), and your days are long. That is <strong>summer</strong>. Leaning away brings a low Sun, slanting spread-out light, and short days: <strong>winter</strong>. Spring and autumn are the in-between positions. This also explains a fact every traveller knows: the hemispheres are opposite — Australians celebrate Christmas on the beach precisely because when the north leans away, the south leans toward.</p>\n<p>First, a myth to bury: the seasons are <strong>not</strong> caused by distance from the Sun. The Earth\'s orbit is so nearly circular that distance barely varies — and in fact the Earth is slightly <em>closest</em> to the Sun in early January, deep in the northern winter. It is angle and day-length, not distance.</p>\n<p>You can feel the angle effect with a torch: shine it straight down at a table and it makes a small, intense pool of light; tilt the beam and the same light smears across a wide, weak oval. Winter sunlight is the tilted beam — the same delivery, spread thin.</p>\n<div class="key-concept">\n  <h3>Key Concept: Height of the Sun = Strength of the Season</h3>\n  <p>Summer is when your part of the world leans sunward: high Sun, direct concentrated light, long days. Winter is the lean away: low Sun, slanted diluted light, short days. One steady tilt, carried around one yearly lap, produces the whole calendar of seasons — opposite in the two hemispheres.</p>\n</div>\n<div class="did-you-know">\n  <h4>Did You Know?</h4>\n  <p>At midsummer, places north of the Arctic Circle lean so far sunward that the Sun never sets — the midnight Sun. At midwinter it never rises. Norway sells this physics to tourists twice a year, in opposite forms.</p>\n</div>'},{id:"moon-phases",title:"The Moon & Its Phases",content:"\n<p>The Moon is our companion in space — a ball of grey rock about a quarter of the Earth's width, circling us roughly once a month. It makes no light of its own; we see it purely by reflected sunlight. And in that sentence hides the explanation of its famous changing shape.</p>\n<p><strong>At every moment, half the Moon is sunlit</strong> — the half facing the Sun, just as half the Earth is. The Moon does not change; what changes, as it circles us, is <strong>how much of that lit half faces the Earth</strong>:</p>\n<ul>\n  <li>When the Moon lies roughly between Earth and Sun, its lit side faces away from us: we see nothing — <strong>new moon</strong>.</li>\n  <li>A week later, we view it side-on: half its lit face visible — a <strong>half moon</strong>.</li>\n  <li>Another week and the Moon is on the far side of Earth from the Sun, its lit face fully toward us: <strong>full moon</strong>.</li>\n  <li>The following weeks replay the show in reverse — waning half, thinning crescent, and back to new. The whole cycle takes about 29 and a half days, and gave humanity its <strong>month</strong>.</li>\n</ul>\n<p>Two clarifications complete the picture. The phases are <strong>not the Earth's shadow</strong> on the Moon — the geometry above needs no shadow at all. (The Earth's shadow does occasionally sweep across the full Moon, and that rarer, redder event is a <strong>lunar eclipse</strong>.) And the Moon is no night-only object: it is often visible in broad daylight, pale in the blue sky — a surprise to most adults, hiding in plain sight.</p>\n<div class=\"did-you-know\">\n  <h4>Try it yourself</h4>\n  <p>Become the Earth. In a dark room, hold a ball (the Moon) at arm's length and stand a lamp (the Sun) across the room. Turn slowly on the spot, carrying the ball around you, and watch its lit shape run through new → crescent → half → full → and back, exactly matching the sky's calendar. Every phase of the Moon, generated on demand with a lamp and an orange.</p>\n</div>"},{id:"solar-system-and-stars",title:"The Solar System, the Stars & the Scale of Everything",content:"\n<p>Step back for the widest view. Our <strong>Solar System</strong> is one star — the Sun — holding a family in its gravitational grip: eight planets on nested near-circular orbits, plus moons, and countless leftovers (asteroids, and the comets whose tails occasionally grace our sky). Nearest the Sun come the four small rocky worlds — Mercury, Venus, <strong>Earth</strong>, Mars — then the four giants: vast Jupiter, ringed Saturn, and the ice giants Uranus and Neptune.</p>\n<p>The Sun itself is no lamp but a <strong>star</strong> — a ball of glowing gas so large that a million Earths could fit inside, holding the whole family in orbit and supplying, as the energy chapter showed, nearly every joule that moves our world.</p>\n<p>Now the idea that separates a list of names from real understanding: <strong>scale</strong>. Shrink the Sun to a football sitting on the centre spot of a stadium, and the Earth becomes a peppercorn about 25 metres away; Neptune, another peppercorn, sits some 800 metres distant. Space is almost entirely empty space.</p>\n<p>And the stars? <strong>Every star in the night sky is another sun</strong> — many larger and brighter than ours — reduced to a dot by unimaginable distance. On the football model, the football's nearest neighbouring star-football lies thousands of kilometres away: from a stadium in London, roughly in Beijing. Light itself, the universe's fastest traveller, needs over four years to make that crossing — so we see every star as it <em>was</em>, years or centuries ago. The night sky is a photograph album of the past. Our Sun and its neighbours are a few of the hundreds of billions of stars swirling in our galaxy, the <strong>Milky Way</strong> — visible on truly dark nights as a misty band arching overhead, our own city of stars seen from inside — and the observable universe holds more galaxies than there are stars in ours.</p>\n<div class=\"analogy\">\n  <h3>Analogy: The Cosmic Address</h3>\n  <p>Written in full, your address reads: your street, your town, planet Earth, third orbit of the Sun, Solar System, Milky Way galaxy, the universe. This chapter's achievement is that every line of that address now means something to you.</p>\n</div>"}],quiz:[{question:"What actually causes day and night?",options:["The Sun orbits the Earth once every 24 hours","The Earth spins on its axis, carrying each place into and out of the Sun's light","The Sun switches from bright to dim on a daily cycle","Clouds cover the Sun at night"],correctIndex:1,explanation:"The Sun holds still while the Earth turns, one rotation per 24 hours. The half facing the Sun has day; the half facing away has night; the spin carries you from one to the other. The Sun's apparent journey across the sky is your own motion, felt as smooth stillness — like scenery sliding past a cruising aeroplane."},{question:"Why is it summer in Australia when it is winter in Europe?",options:["Australia is much closer to the Sun in December","The Sun burns hotter over the southern hemisphere","Australia's deserts store extra summer heat","The Earth's axis is tilted: when the northern hemisphere leans away from the Sun, the southern hemisphere leans toward it"],correctIndex:3,explanation:"Seasons come from the Earth's steady 23\xb0 tilt carried around its yearly orbit — not from distance (Earth is actually slightly closest to the Sun in January). Whichever hemisphere leans sunward gets a high Sun, direct concentrated light, and long days; the other hemisphere simultaneously gets the opposite. The two hemispheres' seasons are therefore always reversed."},{question:"What causes the phases of the Moon?",options:["The Earth's shadow covering different amounts of the Moon","Clouds on the Moon hiding parts of its surface","As the Moon orbits us, we see different amounts of its permanently sunlit half","The Moon's own light slowly brightening and dimming each month"],correctIndex:2,explanation:"Half the Moon is always sunlit — the half facing the Sun. As the Moon circles the Earth each month, our viewpoint changes: lit side away from us (new), side-on (half), lit side toward us (full). No shadow is involved — the Earth's shadow touching the Moon is the much rarer event called a lunar eclipse."},{question:"What is a star, such as those we see at night?",options:["A distant sun, reduced to a point of light by enormous distance","Sunlight reflecting off small rocky bodies","A hole in the darkness letting light through","A nearby object about the size of the Moon"],correctIndex:0,explanation:"Every star is another sun — a vast ball of glowing gas, many bigger than ours — shrunk to a dot by distances so great that its light takes years or centuries to reach us. We therefore see each star as it was when the light left it: the night sky is a view into the past, and our Sun is simply the star we happen to orbit."}]}]},{id:"thinking-like-a-physicist",number:3,title:"Thinking Like a Physicist",description:"The scientific method, fair tests, graphs, and estimation — the experimental-skill progression every top school system builds, compressed for adults.",phase:1,chapters:[{id:"scientific-method",title:"The Scientific Method",subtitle:"Observation → hypothesis → experiment — and what models, theories, and physics itself really are",sections:[{id:"from-noticing-to-asking",title:"From Noticing to Asking",content:'\n<p>Every piece of physics you will ever learn began with someone <strong>noticing something and refusing to shrug it off</strong>. Ice floats, but almost every other solid sinks in its own liquid. A spinning top stays up; a stationary one falls over. Your phone loses charge faster in the cold. These are all invitations to ask a question — and the quality of the question determines everything that follows.</p>\n<p>Scientists sharpen vague curiosity into questions with three properties:</p>\n<ul>\n  <li><strong>Specific:</strong> not "why is the sky weird at sunset?" but "why does the sky turn red near the horizon when the Sun is low?"</li>\n  <li><strong>About measurable things:</strong> the question points at something you could observe, count, or measure — angle, colour, time, temperature.</li>\n  <li><strong>Answerable by evidence:</strong> some possible observation could settle it, at least partially.</li>\n</ul>\n<p>From a good question comes a <strong>hypothesis</strong>: a proposed answer stated clearly enough to be tested. "Cold weather affects batteries" is too mushy. "My phone battery drains at least twice as fast at 0 \xb0C as at 20 \xb0C" is a real hypothesis — it sticks its neck out.</p>\n<div class="key-concept">\n  <h3>Key Concept: Falsifiability</h3>\n  <p>A scientific hypothesis must be <strong>falsifiable</strong> — there must be some conceivable observation that would prove it wrong. "Invisible undetectable gremlins drain my battery" can never be refuted by any measurement, so it is not a scientific claim. Sticking your neck out is the price of admission.</p>\n</div>\n<p>Notice what a hypothesis is <em>not</em>: it is not a guess you are emotionally attached to. Physicists deliberately hold hypotheses loosely. The point of the next step — the experiment — is to give nature every opportunity to say "no." A hypothesis that survives serious attempts to kill it earns your confidence; one that is merely defended earns nothing. That mental posture, more than any lab equipment, is what this whole subject is about.</p>'},{id:"predictions-experiments-evidence",title:"Predictions, Experiments & Evidence",content:'\n<p>A hypothesis becomes useful the moment you squeeze a <strong>prediction</strong> out of it: a concrete "if… then…" statement about something you have not yet observed. If cold really drains batteries faster, <em>then</em> a phone left in the fridge should lose more charge in an hour than an identical phone on the table. Now you have something to check.</p>\n<p>The experiment is simply the check. The classic loop looks like this:</p>\n<ol>\n  <li><strong>Observe</strong> something interesting.</li>\n  <li><strong>Hypothesize</strong> an explanation.</li>\n  <li><strong>Predict</strong> what should happen in a situation you can arrange.</li>\n  <li><strong>Test</strong> — run the experiment and record what actually happens.</li>\n  <li><strong>Compare</strong> prediction with outcome, then revise or retest.</li>\n</ol>\n<p>Two subtleties separate real science from wishful thinking. First, <strong>evidence never "proves" a hypothesis</strong> — it supports it or contradicts it. A thousand successful predictions can be undone by one clean failure; that is exactly what happened to Newtonian gravity when Mercury\'s orbit misbehaved. Second, the loop is a <em>loop</em>: a failed prediction is not a defeat but the most informative result you can get, because it tells you your picture of the world needs repair.</p>\n<div class="did-you-know">\n  <h4>Try it yourself</h4>\n  <p>Hypothesis: a lid dramatically slows how fast a hot drink cools. Prediction: of two identical mugs of hot water filled at the same time, the covered one will still be noticeably hotter after 15 minutes. Fill both mugs from the same kettle, cover one with a saucer, wait 15 minutes, then compare with a kitchen thermometer (or carefully by sip). You have just run the full loop: observation → hypothesis → prediction → test → conclusion. Bonus: was your test <em>fair</em>? Same mug shape? Same starting temperature? Chapter 2 is about exactly that.</p>\n</div>\n<p>Keep a written record of predictions <em>before</em> testing. Human memory happily rewrites "I expected that" after the fact — paper does not.</p>'},{id:"models-and-theories",title:"Models & Theories",content:'\n<p>Between a single hypothesis and the grand laws of physics sit two workhorses of scientific thinking: <strong>models</strong> and <strong>theories</strong>.</p>\n<p>A <strong>model</strong> is a deliberately simplified stand-in for reality — simple enough to reason with, faithful enough to be useful. The "particle model" pictures matter as tiny balls in motion; it ignores almost everything about atoms, yet it beautifully explains melting, evaporation, and gas pressure. Physicists treat "all models are wrong, but some are useful" not as a confession but as a strategy: you <em>choose</em> what to ignore.</p>\n<div class="analogy">\n  <h3>Analogy: The Subway Map</h3>\n  <p>A subway map is geographically false — distances are distorted, curves straightened, streets erased. Yet it is far more useful for riding the subway than a satellite photo, precisely <em>because</em> of what it leaves out. A physics model is a subway map of nature: judged not by completeness but by whether it gets you where you need to go.</p>\n</div>\n<p>A <strong>theory</strong>, in scientific usage, is the opposite of "just a guess." It is a broad, coherent explanatory framework that has survived extensive testing and ties many observations together: the particle theory of matter, the theory of electromagnetism, the theory of relativity. In everyday English "theory" means speculation; in science it is the highest status an explanation can earn.</p>\n<table>\n  <thead>\n    <tr><th>Term</th><th>What it is</th><th>Example</th></tr>\n  </thead>\n  <tbody>\n    <tr><td><strong>Hypothesis</strong></td><td>A testable proposed answer to one question</td><td>"Period of a pendulum depends only on its length"</td></tr>\n    <tr><td><strong>Model</strong></td><td>A simplified, workable picture of a system</td><td>Matter as tiny moving particles</td></tr>\n    <tr><td><strong>Theory</strong></td><td>A well-tested framework explaining many phenomena</td><td>Newton\'s theory of gravitation</td></tr>\n    <tr><td><strong>Law</strong></td><td>A compact rule (often a formula) describing a pattern</td><td>Ohm\'s law, V = IR</td></tr>\n  </tbody>\n</table>\n<p>Note that a law <em>describes</em> a pattern while a theory <em>explains</em> it — and laws do not "graduate" into theories or vice versa. They are different kinds of tools.</p>'},{id:"what-physics-is-and-isnt",title:"What Physics Is (and Isn't)",content:'\n<p>Physics is the search for the <strong>simplest, most general rules</strong> that describe how the universe behaves — rules that apply equally to a falling apple, a falling raindrop, and a falling satellite. Where biology and chemistry study particular systems, physics hunts for the patterns underneath all of them: motion, energy, forces, fields, matter, and how they interconnect.</p>\n<p>Three habits define the physicist\'s approach:</p>\n<ul>\n  <li><strong>Quantify:</strong> turn "heavy," "fast," and "hot" into numbers with units, because numbers can be compared, predicted, and checked.</li>\n  <li><strong>Idealize:</strong> strip a problem to its essentials first (frictionless slope, spherical cow), then add complications one at a time.</li>\n  <li><strong>Universalize:</strong> distrust any rule that works only here, only today, or only for you.</li>\n</ul>\n<p>Just as important is what physics is <em>not</em>. Physics does not answer questions of value ("what should I do?"), taste, or ultimate purpose — not because those questions are unimportant, but because no measurement can settle them. And a field is not scientific just because it uses scientific-sounding language. The test is behavioural: does it make risky, falsifiable predictions, and does it change its mind when they fail?</p>\n<div class="did-you-know">\n  <h3>Did You Know: Horoscopes Under Test</h3>\n  <p>Astrology makes an excellent contrast case. When astrologers\' specific predictions have been tested — matching birth charts to personality profiles under controlled conditions, as in Shawn Carlson\'s famous 1985 double-blind test published in <em>Nature</em> — they perform at chance level. The revealing part is what happened next: nothing. The claims did not change. A field that never updates in response to failed predictions is not doing science, whatever vocabulary it borrows.</p>\n</div>\n<p>None of this makes physics cold. It is, at heart, an act of optimism: the wager that the universe is comprehensible, that honest questions get honest answers, and that anyone — including an adult restarting from scratch — can check the answers for themselves. That last part is the point of this whole course: you are not asked to believe anything you cannot, in principle, test.</p>'}],quiz:[{question:"What makes a hypothesis scientific rather than just an opinion?",options:["It is stated by a qualified expert","It is falsifiable — some possible observation could prove it wrong","It has already been proven true","It uses mathematical language"],correctIndex:1,explanation:"A scientific hypothesis must stick its neck out: there must be some conceivable measurement or observation that would refute it. Claims that no evidence could ever contradict are not scientific, whoever states them."},{question:"In everyday speech, 'theory' means a guess. What does it mean in science?",options:["A broad explanatory framework that has survived extensive testing","An idea that has not yet been tested","A hypothesis proposed by a famous scientist","A mathematical formula describing one experiment"],correctIndex:0,explanation:"In science, 'theory' is the highest status an explanation can earn — a coherent framework (like electromagnetism or relativity) that ties many observations together and has withstood serious attempts to refute it."},{question:"Why do physicists say experiments can support a hypothesis but never prove it?",options:["Because experiments always contain errors","Because proof is only possible in biology and chemistry","Because a single future failed prediction could still overturn it, however many past tests it passed","Because hypotheses are opinions and opinions cannot be proven"],correctIndex:2,explanation:"Evidence accumulates support but can never guarantee future success. Newtonian gravity passed tests for two centuries before Mercury's orbit exposed its limits — one clean, well-verified failure outweighs a thousand successes."},{question:"The particle model treats atoms as tiny featureless balls, which is known to be false in detail. Why do physicists still use it?",options:["Out of respect for tradition","Because no better model of the atom exists","Because using a false model is acceptable if the conclusions are checked twice","Because a deliberately simplified model can capture exactly the behaviour that matters, like a subway map"],correctIndex:3,explanation:"Models are judged by usefulness, not completeness. Like a subway map that distorts geography to make routes clear, the particle model ignores atomic detail yet correctly explains melting, evaporation, and gas pressure."},{question:"Which of these is a genuinely testable prediction, in the 'if… then…' sense?",options:["Cold weather is bad for electronics","If I leave one of two identical charged phones at 0 \xb0C and one at 20 \xb0C for an hour, the cold one will have lost more charge","Batteries contain energy that can be affected by many factors","Everyone knows phones die faster in winter"],correctIndex:1,explanation:"A useful prediction specifies a concrete arrangement and a measurable outcome that could fail to occur. The other statements are too vague for any observation to contradict them cleanly."}]},{id:"fair-tests-and-variables",title:"Fair Tests & Variables",subtitle:"Comparing, relating, and controlling variables — mastered through the classic pendulum investigation",sections:[{id:"from-comparing-to-relating",title:"From Comparing to Relating",content:'\n<p>The world\'s strongest school science systems teach experimental skill as a ladder, one rung per year, and it is worth climbing the same ladder deliberately as an adult — it takes minutes, not years, but skipping rungs leaves gaps.</p>\n<p><strong>Rung 1 — Comparing.</strong> The simplest experiment answers "which one?" Which paper towel absorbs more water? Which pan heats up faster? A comparison needs only two things: a common task and an honest judge. Even here, fairness sneaks in — comparing towels is meaningless if one towel is twice the size of the other.</p>\n<p><strong>Rung 2 — Relating.</strong> The next question is "how does one thing change with another?" Not "which ball bounces higher?" but "how does bounce height change as I drop the ball from higher up?" You are now relating two quantities — drop height and bounce height — and the answer is not a winner but a <em>pattern</em>: more of this gives more of that, or less, or no change at all.</p>\n<p><strong>Rung 3 — Controlling.</strong> The hardest and most important rung: when many things <em>could</em> matter, how do you find out which ones actually do? The answer — change one thing at a time while holding everything else fixed — is the subject of the rest of this chapter.</p>\n<div class="analogy">\n  <h3>Analogy: Debugging a Recipe</h3>\n  <p>Your bread came out dense. Was it the new flour, the colder kitchen, or the shorter kneading time? If you change all three next bake and it improves, you have learned almost nothing. Any cook who changes one thing per bake is already doing controlled experimentation — physicists just do it on purpose, every time.</p>\n</div>\n<p>Notice that each rung asks a sharper question of nature than the last. "Which?" becomes "how much?" becomes "what actually causes what?" That final question — causation, untangled from coincidence — is the one the fair test is built to answer, and it is the single most transferable skill in this entire course: it works on bread, medicine, marketing claims, and pendulums alike.</p>'},{id:"naming-the-variables",title:"Naming the Variables",content:'\n<p>A <strong>variable</strong> is anything in an experiment that can change or be changed. Fair-test design starts by listing them and assigning each one a role:</p>\n<ul>\n  <li><strong>Independent variable</strong> — the one thing <em>you deliberately change</em>. (Also called the input.)</li>\n  <li><strong>Dependent variable</strong> — the thing <em>you measure</em> to see the effect. (The output.)</li>\n  <li><strong>Controlled variables</strong> — everything else that could plausibly matter, which you <em>hold fixed</em>.</li>\n</ul>\n<p>A test is "fair" precisely when only the independent variable differs between trials. Then, and only then, can a change in the outcome be pinned on the thing you changed.</p>\n<table>\n  <thead>\n    <tr><th>Question</th><th>Independent</th><th>Dependent</th><th>Must control</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>Does sugar dissolve faster in hotter water?</td><td>Water temperature</td><td>Time to dissolve</td><td>Amount of water, amount of sugar, stirring, sugar grain size</td></tr>\n    <tr><td>Does a heavier car roll further down a ramp?</td><td>Mass of toy car</td><td>Distance rolled</td><td>Ramp angle, release height, same car body, same floor</td></tr>\n    <tr><td>Does bounce height depend on drop height?</td><td>Drop height</td><td>Bounce height</td><td>Same ball, same surface, no throw (just release)</td></tr>\n  </tbody>\n</table>\n<div class="key-concept">\n  <h3>Key Concept: One Variable at a Time</h3>\n  <p>If two things change between trials and the result differs, you cannot tell which one was responsible — the experiment is <strong>confounded</strong>, and no amount of clever analysis afterwards can fully rescue it. Change one variable; measure one variable; freeze the rest.</p>\n</div>\n<p>Two practical habits complete the setup. First, <strong>decide in advance</strong> what you will change, what you will measure, and what you will hold fixed — writing it down keeps you honest. Second, <strong>repeat each trial</strong> at least three times. No two runs ever come out identical; repeats reveal how much natural scatter your setup has, so you can tell a real effect from ordinary wobble. We will quantify that wobble in Chapter 3.</p>'},{id:"the-pendulum-investigation",title:"The Pendulum Investigation",content:"\n<p>Here is the most celebrated fair-test exercise in the world. In Japan, every grade-5 student spends weeks on it; it appears in curricula from Singapore to Finland because it is the perfect controlled-variables workout. The question: a pendulum swings back and forth with some <strong>period</strong> (the time for one complete swing). What does the period depend on?</p>\n<p>Three candidates suggest themselves, and intuition argues loudly for all of them:</p>\n<ul>\n  <li><strong>Length</strong> of the string — surely a longer pendulum swings more slowly?</li>\n  <li><strong>Mass</strong> of the bob — surely a heavier bob is harder to move, so slower?</li>\n  <li><strong>Amplitude</strong> — surely a wider swing takes longer, since the bob travels further?</li>\n</ul>\n<p>The investigation is three fair tests, one per candidate. To test mass, you swing pendulums of the same length and same amplitude with different bobs. To test amplitude, same length and same bob, different release angles. To test length, same bob and same amplitude, different string lengths. One independent variable per test; everything else frozen.</p>\n<p>The result surprises almost everyone: <strong>only length matters</strong>. Double the mass — no change. Swing wider (within modest angles) — no change. But lengthen the string and the period grows: four times the length gives twice the period. Intuition loses two out of three, which is exactly why we run experiments. (The full law, coming in later subjects, is T = 2π√(L/g) — notice mass and amplitude simply do not appear.)</p>\n<div class=\"did-you-know\">\n  <h4>Try it yourself</h4>\n  <p>Tie a small weight (a few metal washers, or keys) to a string and hang it from a door frame or table edge. Time <strong>10 complete swings</strong> with your phone's stopwatch and divide by 10 — timing one swing is too error-prone. Now run the three fair tests: double the washers (same length, small swing); double the release angle (same length, same washers); then quadruple the length, say 25 cm → 1 m (same washers, small swing). You should find the first two periods unchanged and the third roughly doubled, from about 1.0 s to about 2.0 s.</p>\n</div>\n<p>Galileo reportedly began this line of thought watching a lamp swing in Pisa's cathedral, timing it against his own pulse. Your phone is a better stopwatch; the reasoning is identical.</p>"},{id:"designing-good-experiments",title:"Designing Good Experiments",content:'\n<p>You now have all the pieces. Here is the checklist a physicist runs through — consciously at first, automatically forever after — before trusting any experiment, their own included:</p>\n<ol>\n  <li><strong>One question, stated up front.</strong> What exactly are you asking, and what would each possible answer look like in the data?</li>\n  <li><strong>One independent variable.</strong> Everything else that could plausibly matter is listed and pinned down.</li>\n  <li><strong>A measurable dependent variable.</strong> "Better," "faster-ish," and "seems stronger" are not measurements. Choose a number and a unit.</li>\n  <li><strong>Repeats.</strong> At least three trials per setting, so scatter is visible.</li>\n  <li><strong>A range, not two points.</strong> Test five lengths, not two — patterns (and surprises) live in the range.</li>\n  <li><strong>Records made in the moment.</strong> Data written down as it happens, including the runs that "went wrong."</li>\n</ol>\n<p>Equally valuable is knowing the classic failure modes, because you will see them everywhere once named:</p>\n<ul>\n  <li><strong>Confounding:</strong> two variables changed at once — the bread-recipe mistake. The fix is structural, not statistical: redesign the test.</li>\n  <li><strong>Cherry-picking:</strong> keeping the trials that fit your hunch and quietly discarding the rest. Anomalies may be excluded, but only for a documented physical reason ("bumped the table"), never for disagreeing with you.</li>\n  <li><strong>Tiny samples:</strong> one lucky trial proves nothing. Coincidence is astonishingly good at impersonating causation over small numbers.</li>\n  <li><strong>Moving goalposts:</strong> deciding what counts as success <em>after</em> seeing the results.</li>\n</ul>\n<div class="key-concept">\n  <h3>Key Concept: Fair Testing Is a Life Skill</h3>\n  <p>"This supplement worked for my cousin," "sales rose after the redesign," "it rained right after they seeded the clouds" — each is an uncontrolled, unrepeated, one-variable-among-many observation. You do not need a laboratory to ask the physicist\'s question: <em>compared to what, with what else held fixed, how many times?</em></p>\n</div>\n<p>Design is nine-tenths of experimental skill. A fair test with kitchen equipment beats a sloppy test with precision instruments, every single time.</p>'}],quiz:[{question:"In an experiment to see whether water temperature affects how fast sugar dissolves, what is the dependent variable?",options:["The water temperature","The amount of sugar","The time the sugar takes to dissolve","The size of the cup"],correctIndex:2,explanation:"The dependent variable is the outcome you measure — here, dissolving time. Temperature is the independent variable (deliberately changed), while sugar amount, water amount, and stirring must be controlled."},{question:"In the classic pendulum investigation, which factor actually changes the pendulum's period?",options:["The length of the string only","The mass of the bob only","Both the mass and the amplitude","Length, mass, and amplitude all matter equally"],correctIndex:0,explanation:"Fair tests show that (for modest swing angles) neither mass nor amplitude changes the period — only length does. Quadrupling the length doubles the period, reflected in the law T = 2π√(L/g), where mass and amplitude never appear."},{question:"To test fairly whether the mass of the bob affects a pendulum's period, you should change the mass while keeping…",options:["the mass constant and varying the length","the string length and release amplitude the same in every trial","everything different, to explore more possibilities at once","the period the same in every trial"],correctIndex:1,explanation:"A fair test changes only the variable under investigation. Testing mass means every trial uses the same length and same amplitude; only the bob changes. Otherwise you cannot attribute any difference to mass alone."},{question:"You changed both the ramp angle and the car's mass, and the car rolled further. What can you conclude?",options:["Mass makes cars roll further","Ramp angle makes cars roll further","Both factors contributed equally","Nothing definite — the experiment is confounded because two variables changed at once"],correctIndex:3,explanation:"When two variables change together, the effect cannot be attributed to either one — the experiment is confounded. The fix is to redesign: vary the angle with mass fixed, then vary the mass with angle fixed."},{question:"Why time 10 pendulum swings and divide by 10, rather than timing a single swing?",options:["The pendulum needs 10 swings to reach full speed","Your reaction-time error gets spread across 10 swings, shrinking its effect on the result tenfold","The period only stabilizes after several swings","Stopwatches cannot measure times shorter than 10 seconds"],correctIndex:1,explanation:"Your start/stop reaction error (a few tenths of a second) is roughly the same whether you time 1 swing or 10. Dividing a 10-swing measurement by 10 also divides that error by 10 — a classic trick for improving precision with no new equipment."}]},{id:"data-and-graphs",title:"Data & Graphs",subtitle:"Tables, bar and line graphs, patterns and averages — and a first honest look at uncertainty",sections:[{id:"tables-that-work",title:"Tables That Work",content:'\n<p>Raw experience is fleeting; <strong>data is experience written down in a form you can reason about later</strong>. The humble table is where that starts, and a few conventions — the same ones used in every professional lab — make the difference between a table you can trust and a pile of numbers.</p>\n<ul>\n  <li><strong>Units live in the header, once.</strong> Write "Length (cm)" at the top, then plain numbers below. A column mixing "25 cm" and "0.3 m" is an accident waiting to happen.</li>\n  <li><strong>Independent variable in the left column</strong>, in a sensible order (usually increasing). Dependent variable(s) to the right.</li>\n  <li><strong>One column per repeat, plus a mean.</strong> Three trials means three columns and an average — never just the average, because the spread of the repeats is information you will want later.</li>\n  <li><strong>Record immediately, and record everything.</strong> Data written from memory an hour later is fiction with confidence. Failed runs get recorded too, with a note.</li>\n</ul>\n<p>Here is what pendulum data looks like done properly:</p>\n<table>\n  <thead>\n    <tr><th>Length (cm)</th><th>Trial 1 — time for 10 swings (s)</th><th>Trial 2 (s)</th><th>Trial 3 (s)</th><th>Mean (s)</th><th>Period (s)</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>25</td><td>10.1</td><td>9.9</td><td>10.2</td><td>10.1</td><td>1.01</td></tr>\n    <tr><td>50</td><td>14.3</td><td>14.1</td><td>14.4</td><td>14.3</td><td>1.43</td></tr>\n    <tr><td>100</td><td>20.0</td><td>20.3</td><td>19.9</td><td>20.1</td><td>2.01</td></tr>\n  </tbody>\n</table>\n<div class="key-concept">\n  <h3>Key Concept: The Mean Tames the Wobble</h3>\n  <p>Repeated measurements never agree exactly — hand timing, air currents, and release wobble all inject scatter. The <strong>mean</strong> (add the trials, divide by how many) smooths out this random scatter, and the trials\' spread tells you how much to trust it. One reading is an anecdote; three readings and a mean are a measurement.</p>\n</div>\n<p>Notice something satisfying in that table: quadrupling the length from 25 cm to 100 cm did double the period, 1.01 s → 2.01 s. The pattern was in the data — but it takes a graph to make patterns leap out, which is where we go next.</p>'},{id:"bar-or-line",title:"Bar or Line? Choosing and Building Graphs",content:'\n<p>A graph is a machine for turning columns of numbers into a shape your visual system can read instantly. Choosing the right kind is the first decision, and it hinges on the independent variable:</p>\n<ul>\n  <li><strong>Bar graph — for categories.</strong> When the things compared are separate kinds with no in-between (materials, brands, days of the week), draw bars. There is no such thing as "halfway between wood and steel," so connecting them with a line would be nonsense.</li>\n  <li><strong>Line graph (or scatter plot) — for continuous quantities.</strong> When the independent variable can take any value in a range (length, temperature, time), plot points and look for the trend. In-between values exist, so the trend between points is meaningful.</li>\n</ul>\n<p>Quick test: could the x-axis value be 37.4? If yes, it is continuous — points and a trend line. If the question is absurd, bars.</p>\n<p>A graph worth drawing is worth drawing properly. The professional checklist:</p>\n<ol>\n  <li><strong>Independent variable on the horizontal axis</strong>, dependent on the vertical — "y against x" means y is measured, x is chosen.</li>\n  <li><strong>Both axes labelled with quantity and unit:</strong> "Length (cm)", "Period (s)".</li>\n  <li><strong>Scales chosen so the data fills the plot</strong>, with evenly spaced, round-numbered gridlines. A graph squashed into one corner hides its own story.</li>\n  <li><strong>Points marked clearly</strong>, and for continuous data, a single <strong>smooth trend</strong> — a straight line or gentle curve capturing the overall pattern, not a jittery connect-the-dots through every point.</li>\n</ol>\n<div class="analogy">\n  <h3>Analogy: The Trend Line as a Voting Booth</h3>\n  <p>Each data point casts a vote about where the true relationship lies, but every voter is slightly unreliable — scatter is guaranteed. Drawing a smooth best-fit line through the middle of the points is letting the votes average out. Zigzagging through every single point treats each unreliable voter as infallible, faithfully reproducing the noise instead of the signal.</p>\n</div>\n<p>That last habit — trusting the trend over the individual point — marks the biggest single step from school plotting to scientific plotting.</p>'},{id:"reading-stories-from-graphs",title:"Reading Stories from Graphs",content:'\n<p>Making graphs is half the skill; <strong>reading</strong> them is the half that pays off daily, since the world communicates in graphs — news charts, fitness apps, energy bills. A line graph tells its story through shape, and physicists read shape with three questions.</p>\n<p><strong>1. Which way does it go?</strong> Rising: the quantities increase together. Falling: one grows as the other shrinks. Flat: the dependent variable simply does not care — remember pendulum period against mass: a perfectly flat line is a strong, useful result, not a failed experiment.</p>\n<p><strong>2. How steep, and is the steepness changing?</strong> The <strong>slope</strong> is the rate of change — how much the y-quantity changes per unit of x. On a distance–time graph, slope literally <em>is</em> speed: steeper means faster, flat means stopped, and a slope that steepens over time means acceleration. Learning to see slope as "how fast y responds to x" is one of the highest-value reading skills in all of physics.</p>\n<p><strong>3. Is it a straight line through the origin?</strong> That special shape means <strong>direct proportionality</strong>: double x, and y doubles. Straight but missing the origin means "linear but with a head start" — related, but not proportional. Curves tell subtler stories: period versus length curves like a square root (flattening as it rises), which is a genuine clue about the underlying law.</p>\n<div class="key-concept">\n  <h3>Key Concept: Interpolate Freely, Extrapolate Carefully</h3>\n  <p><strong>Interpolation</strong> — reading between your measured points — is usually safe: you have data on both sides. <strong>Extrapolation</strong> — extending the trend beyond your data — is a bet that the pattern continues where you never looked. Sometimes it must be done, but every extrapolation deserves suspicion: a spring stretches proportionally right up until it doesn\'t.</p>\n</div>\n<p>Finally, read graphs defensively. A vertical axis that starts at 90 instead of 0 makes a 2% difference look like a cliff; a cherry-picked time window can turn any wiggle into a trend. The same conventions that make graphs powerful make them easy to abuse — and now you know exactly where to look.</p>'},{id:"first-look-at-uncertainty",title:"A First Look at Uncertainty",content:'\n<p>Here is a truth that separates physics from arithmetic: <strong>no measurement is exact</strong>. Every number you will ever measure comes with a fuzz of doubt, and mature science does not hide the fuzz — it measures it, reports it, and reasons with it.</p>\n<p>Where does the fuzz come from? Your ruler has finite markings; your reaction time varies; the room\'s drafts nudge the pendulum. These effects come in two flavours:</p>\n<ul>\n  <li><strong>Random scatter</strong> — trial-to-trial wobble in both directions. Repeats and averaging beat it down.</li>\n  <li><strong>Systematic error</strong> — a consistent push one way: a stopwatch that runs slow, a ruler measured from its worn end, a scale that reads 0.2 kg with nothing on it. Averaging is helpless here; only checking the instrument catches it.</li>\n</ul>\n<p>The simplest honest report of a repeated measurement is <strong>mean \xb1 half the spread</strong>. Timing swings gave 10.1, 9.9, and 10.2 s: the mean is 10.1 s and the spread is 0.3 s, so report 10.1 \xb1 0.15 s — "our best value is 10.1, and we would not be shocked by anything within about 0.15 of it." That little \xb1 converts a bare claim into a testable one: two results agree when their \xb1 ranges overlap.</p>\n<div class="did-you-know">\n  <h4>Try it yourself</h4>\n  <p>Measure your own reaction time with a ruler and a friend. They hold a 30 cm ruler vertically by the top; you position your open finger and thumb at the 0 cm mark, and catch it the instant they drop it (no warning). Record the catch distance, repeat 10 times, and tabulate. Convert with t = √(2d \xf7 980) (d in cm, t in seconds): catching at 20 cm means about 0.20 s. Now look at your table like a scientist: how big is your scatter? Is your mean improving over the 10 trials (a practice effect — a systematic drift!)? You have just done a complete uncertainty analysis with a ruler.</p>\n</div>\n<p>An <strong>anomaly</strong> — one reading far outside the pack — deserves investigation, not silent deletion: find the cause ("I flinched early"), note it, and repeat the trial. Uncertainty handled this honestly is not weakness. It is precisely what makes measurements comparable, claims checkable, and science self-correcting.</p>'}],quiz:[{question:"You measured how far a toy car rolls on four different floor surfaces: tile, carpet, wood, and rug. Which graph suits this data?",options:["A line graph, because distance is continuous","A pie chart, to show each surface's share","A bar graph, because the surfaces are separate categories with no in-between values","No graph is possible with only four data points"],correctIndex:2,explanation:"The independent variable (surface type) is categorical — there is no value 'between tile and carpet' — so bars are correct. Line graphs are reserved for continuous independent variables like length, time, or temperature."},{question:"On a distance–time graph, what does the slope of the line represent?",options:["The total distance travelled","The speed of motion","The time elapsed","The mass of the moving object"],correctIndex:1,explanation:"Slope is the rate of change of the vertical quantity per unit of the horizontal one — here, distance per time, which is speed. Steeper means faster; a flat section means stationary."},{question:"Three timing trials give 14.3 s, 14.1 s, and 14.4 s. What is the best value to report?",options:["14.4 s, since the largest reading is the most complete","14.1 s, since the smallest reading has the least error","42.8 s, the total of all three","About 14.3 s — the mean of the trials, with roughly \xb1 0.15 s of uncertainty"],correctIndex:3,explanation:"The mean (14.27 ≈ 14.3 s) is the best single estimate because random scatter partially cancels when you average. The spread of 0.3 s suggests an uncertainty of about \xb1 0.15 s — the honest way to report the result."},{question:"A kitchen scale reads 0.2 kg with nothing on it, so every measurement comes out 0.2 kg too high. This is an example of…",options:["a systematic error, which averaging repeated readings cannot remove","random scatter, which averaging removes","an anomaly that should be deleted from the data","acceptable uncertainty that needs no correction"],correctIndex:0,explanation:"A consistent push in one direction is a systematic error. Unlike random scatter, it never averages away — every reading is shifted the same way. The cure is checking and correcting the instrument (here, taring the scale)."},{question:"Your data on spring stretch versus load is beautifully linear from 0 to 500 g. A friend uses your trend line to predict the stretch at 5 kg. Why should you both be cautious?",options:["Trend lines can only be used at the exact points measured","Predictions require at least 100 data points","This is extrapolation far beyond the measured range — the linear pattern may break down (springs eventually deform)","The prediction is invalid because grams must first be converted to newtons"],correctIndex:2,explanation:"Reading within your measured range (interpolation) is well-supported; extending the pattern to ten times the maximum load (extrapolation) assumes the spring stays linear where you have no evidence — and real springs stop obeying Hooke's law and permanently deform."}]},{id:"estimation-and-sanity-checks",title:"Estimation & Sanity Checks",subtitle:"Order-of-magnitude reasoning, Fermi problems, and letting units catch your mistakes",sections:[{id:"the-power-of-ten",title:"Thinking in Powers of Ten",content:'\n<p>Ask a physicist how many people live in your city and you may get the answer "about 10⁶." Not evasion — a different, deliberately chosen precision called an <strong>order of magnitude</strong>: the nearest power of ten. It sounds crude, but thinking in powers of ten is one of the sharpest tools in physics, for two reasons.</p>\n<p>First, <strong>most real questions only need the exponent</strong>. Will the file fit on the drive? Can this battery run that heater? Is this news statistic even possible? For all of these, knowing whether the answer is closer to 10\xb3 or 10⁶ settles the matter; the third significant figure never gets consulted.</p>\n<p>Second, <strong>orders of magnitude are hard to get wrong by much</strong>. Your guess for a city\'s population might be off by a factor of two, but rarely by a factor of a hundred. Working in powers of ten deliberately plays to the strength of rough knowledge.</p>\n<p>To find an order of magnitude, write the number in scientific notation and round: 3,200 = 3.2 \xd7 10\xb3 ≈ 10\xb3, while 82,000 = 8.2 \xd7 10⁴ rounds up to 10⁵. A feel for the scale of things is worth building deliberately:</p>\n<table>\n  <thead>\n    <tr><th>Length</th><th>Order of magnitude</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>Thickness of paper</td><td>10⁻⁴ m</td></tr>\n    <tr><td>An ant</td><td>10⁻\xb3 m</td></tr>\n    <tr><td>A human</td><td>10⁰ m (≈ 2 m)</td></tr>\n    <tr><td>Height of Everest</td><td>10⁴ m</td></tr>\n    <tr><td>Diameter of Earth</td><td>10⁷ m</td></tr>\n    <tr><td>Earth to Sun</td><td>10\xb9\xb9 m</td></tr>\n  </tbody>\n</table>\n<div class="key-concept">\n  <h3>Key Concept: Each Step Is a Factor of Ten</h3>\n  <p>The gap between 10⁴ and 10⁶ is not "2 more" — it is <strong>100 times</strong>. Order-of-magnitude thinking is multiplicative: a billion (10⁹) is not "a bit past" a million (10⁶), it is a thousand millions. A million seconds is 12 days; a billion seconds is 32 <em>years</em>. Most bad intuitions about big numbers are failures to feel this difference.</p>\n</div>\n<p>From here on, before computing anything precisely, we will ask: <em>roughly what size should the answer be?</em> That one habit catches more errors than any calculator.</p>'},{id:"fermi-problems",title:"Fermi Problems",content:'\n<p>Enrico Fermi, one of the great physicists of the twentieth century, was famous for estimating seemingly unknowable quantities — legend says he estimated the strength of the first atomic-bomb test by dropping scraps of paper and watching how far the blast wave carried them, landing within a factor of two of the instrumented value. A <strong>Fermi problem</strong> honours that spirit: estimate something outrageous using only common knowledge and courage.</p>\n<p>The classic: <em>how many piano tuners work in Chicago?</em> The method is always the same — <strong>break the impossible number into a chain of guessable ones</strong>:</p>\n<ol>\n  <li>Chicago has roughly 3 \xd7 10⁶ people — about 10⁶ households.</li>\n  <li>Maybe 1 household in 20 has a piano → ~5 \xd7 10⁴ pianos.</li>\n  <li>A piano gets tuned about once a year → 5 \xd7 10⁴ tunings/year.</li>\n  <li>A tuner does ~4 tunings a day, ~250 days a year → ~10\xb3 tunings per tuner per year.</li>\n  <li>So Chicago supports about 5 \xd7 10⁴ \xf7 10\xb3 ≈ <strong>50 tuners</strong>.</li>\n</ol>\n<p>Directory listings historically said: a few dozen. The magic is that individual errors tend to <strong>cancel</strong>: guess pianos too high and tunings-per-year too low, and the product barely moves. A chain of five guesses, each within a factor of 2–3, usually lands the final answer within a factor of 10 — which is exactly what you need to call nonsense on a claim, size a plan, or decide whether a precise calculation is worth doing.</p>\n<div class="did-you-know">\n  <h4>Try it yourself</h4>\n  <p>Estimate how many litres of water your household uses per day. Chain it: showers (minutes \xd7 ~10 L/min) + toilet flushes (count \xd7 ~6 L) + dishes, laundry, cooking, drinking. Write down your total — then check yourself against your water bill or meter, which reports actual usage (often in m\xb3: 1 m\xb3 = 1,000 L). Landing within a factor of 2 on your first try is genuinely good Fermi form. Where was your worst single guess?</p>\n</div>\n<p>Estimate first, look up later. The estimate builds the intuition; the lookup then calibrates it — and every future estimate gets sharper.</p>'},{id:"let-the-units-do-the-work",title:"Let the Units Do the Work",content:'\n<p>Units are not decorations after a number — they are <strong>algebra that checks your reasoning for free</strong>. Treat every unit as a symbol that multiplies, divides, and cancels exactly like x and y, and two superpowers follow.</p>\n<p><strong>Superpower 1: conversions become unmissable.</strong> To convert, multiply by fractions equal to 1. Converting 90 km/h to m/s:</p>\n<p style="text-align:center">90 km/h \xd7 (1,000 m / 1 km) \xd7 (1 h / 3,600 s) = 25 m/s</p>\n<p>The km cancels, the h cancels, and only m/s survives. If you had flipped a fraction, the units would refuse to cancel — the mistake announces itself before the arithmetic even happens.</p>\n<p><strong>Superpower 2: formulas can be sanity-checked without knowing physics.</strong> An equation is only meaningful if both sides carry the same units — you cannot equate metres to seconds any more than you can pay a bill in kilograms. Suppose you half-remember distance fallen as d = \xbdgt, with g ≈ 9.8 m/s\xb2 and t in seconds. Check: (m/s\xb2) \xd7 s = m/s. That is a <em>speed</em>, not a distance — the formula must be wrong. The correct d = \xbdgt\xb2 gives (m/s\xb2) \xd7 s\xb2 = m. ✓ You just debugged a physics formula with no physics at all, only unit bookkeeping. This habit, called <strong>dimensional analysis</strong>, scales all the way to research: professionals run it on every result, reflexively.</p>\n<div class="did-you-know">\n  <h3>Did You Know: The $327 Million Unit Error</h3>\n  <p>In 1999 NASA\'s Mars Climate Orbiter burned up in the Martian atmosphere because one team\'s software output thruster impulse in pound-force seconds while another\'s expected newton-seconds — a factor of 4.45 slipped through every review. The spacecraft arrived 170 km lower than planned. The most expensive unit-conversion mistake in history is now the standard cautionary tale: <em>always carry the units</em>.</p>\n</div>\n<p>Make it mechanical: write units beside every number, cancel them like fractions, and refuse to box any answer whose units are wrong. Wrong units mean a wrong answer, with certainty; right units do not guarantee a right answer, but they eliminate the entire family of errors that carelessness produces most often.</p>'},{id:"the-sanity-check-toolkit",title:"The Sanity-Check Toolkit",content:'\n<p>A calculator will happily tell you that a bathtub holds 4,000,000 litres or that a cyclist rides at 900 km/h. The final skill of this subject — the one that quietly guards all the others — is the reflex of interrogating every answer before accepting it. Four checks, run in seconds:</p>\n<ol>\n  <li><strong>The size check.</strong> Compare against benchmarks you carry in your head. Build this shelf deliberately: a human is ~70 kg; brisk walking is ~1.5 m/s and highway driving ~30 m/s; a car is ~1,500 kg; a flight of stairs is ~3 m; a bathtub is ~150 L; a phone battery stores ~10 Wh; room temperature is ~20 \xb0C. Any result wildly off-shelf is guilty until proven innocent.</li>\n  <li><strong>The unit check.</strong> From the previous section — wrong units, wrong answer, no appeal.</li>\n  <li><strong>The direction check.</strong> Should the answer grow or shrink as inputs change? More friction should mean stopping sooner; if your formula says otherwise, the formula (or your algebra) is broken.</li>\n  <li><strong>The extreme-case check.</strong> Push inputs to limits where the answer is obvious. A formula for pendulum period should give a huge period for an absurdly long string and zero for zero length. Extreme cases are where wrong formulas fail most loudly.</li>\n</ol>\n<div class="analogy">\n  <h3>Analogy: The Restaurant Bill</h3>\n  <p>Six people dine, and the bill says $4,700. You do not re-add every line — you instantly know it is wrong, because six dinners is a few hundred dollars, and you demand a recount. Sanity-checking physics answers is the same reflex pointed at nature: rough expected size first, precision second. The goal of this chapter is that a 900 km/h cyclist feels exactly as absurd to you as that bill.</p>\n</div>\n<div class="did-you-know">\n  <h4>Try it yourself</h4>\n  <p>Estimate the total mass of air in your bedroom — most people are shocked. Pace out the room\'s dimensions (say 4 m \xd7 3 m \xd7 2.5 m = 30 m\xb3) and use the benchmark that air\'s density is about 1.2 kg/m\xb3: roughly <strong>36 kg of air</strong> — about the mass of a ten-year-old child, floating invisibly around you. Then run the toolkit on it: units (m\xb3 \xd7 kg/m\xb3 = kg ✓), direction (bigger room → more air ✓), extreme case (an empty room of zero volume → zero air ✓). It survives every check — which is exactly why physicists believe surprising numbers when they earn it.</p>\n</div>\n<p>Estimation, units, and sanity checks form one habit: <strong>never let a number pass unexamined</strong>. Carry that habit forward and every formula in the phases ahead becomes something you can verify — not something you must take on faith.</p>'}],quiz:[{question:"What is the order of magnitude of 82,000?",options:["10⁴, because 82,000 starts with an 8","10⁵, because 8.2 \xd7 10⁴ rounds to 10⁵","10⁸, because there are 8 in the number","10\xb3, the nearest round unit"],correctIndex:1,explanation:"82,000 = 8.2 \xd7 10⁴. Since 8.2 is closer to 10 than to 1, it rounds up, giving an order of magnitude of 10⁵. (A common convention: mantissas above about 3.16, i.e. √10, round up.)"},{question:"Why do Fermi estimates built from a chain of rough guesses often land surprisingly close to the truth?",options:["Because each individual guess is usually exact","Because the method only works for questions about pianos","Because overestimates and underestimates in the chain tend to cancel each other out","Because multiplying numbers always reduces error"],correctIndex:2,explanation:"Each factor is only good to within perhaps 2–3\xd7, but errors are as likely high as low, so in a product they partially cancel. A five-step chain typically lands within a factor of 10 — exactly the precision an order-of-magnitude question needs."},{question:"You half-remember a formula for distance fallen: d = \xbdgt, with g in m/s\xb2 and t in seconds. What does a unit check reveal?",options:["The right side gives m/s — a speed, not a distance — so the formula must be wrong","The units work out, so the formula is correct","Units cannot be used to check formulas, only conversions","The formula is wrong because g should be in kilograms"],correctIndex:0,explanation:"(m/s\xb2) \xd7 s = m/s, a speed. Since a distance must come out in metres, the formula fails the dimensional check. The correct d = \xbdgt\xb2 gives (m/s\xb2) \xd7 s\xb2 = m. Units debug formulas even when you have forgotten the physics."},{question:"What destroyed NASA's Mars Climate Orbiter in 1999?",options:["A collision with space debris","A software team supplied thruster data in pound-force seconds while another expected newton-seconds","An error in Newton's law of gravitation","A failure of the launch rocket"],correctIndex:1,explanation:"One team's software reported impulse in imperial units (pound-force seconds) while the trajectory software expected metric (newton-seconds). The unnoticed factor of 4.45 sent the $327 million spacecraft 170 km too deep into Mars's atmosphere — history's most expensive unit error."},{question:"A calculation tells you a cyclist's speed is 900 km/h. Which sanity check most immediately flags the problem?",options:["The unit check — km/h is not a valid unit of speed","The extreme-case check — cyclists cannot ride uphill","No check flags it; the calculation should simply be redone from scratch","The size check — benchmark speeds (brisk walk ≈ 5 km/h, highway car ≈ 100 km/h, airliner ≈ 900 km/h) show a cyclist cannot plausibly match an airliner"],correctIndex:3,explanation:"The units (km/h) are fine — it is the size that is absurd. Comparing against mental benchmarks instantly shows 900 km/h is airliner speed, roughly 30 times a strong cyclist's pace, so an error (likely a unit slip or misplaced power of ten) must be hiding in the calculation."}]}]},{id:"algebra-geometry-for-physics",number:4,title:"Algebra & Geometry for Physics",description:"The math toolkit that powers the entire Phase 2 tour of physics: rearrange any formula on demand, read physics straight off a graph, and solve triangles with confidence.",phase:2,chapters:[{id:"the-language-of-algebra",title:"The Language of Algebra",subtitle:"Variables, expressions, and the symbol-manipulation moves behind every physics formula",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Every physics formula — from v = d/t to E = mc\xb2 — is a sentence written in the language of algebra, and this chapter teaches you to read and write it fluently. You\'ll learn what a variable really is, how to simplify and reshape expressions, and how expanding and factoring let you see the same quantity in different, useful forms. This is the entry point to the whole Phase 2 tour: once symbols stop being scary, every one-formula chapter that follows becomes a matter of substitution and care.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Variables &amp; expressions</li>\n  <li>Simplifying</li>\n  <li>Expanding &amp; factoring basics</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"equations-and-formula-fluency",title:"Equations & Formula Fluency",subtitle:"Solve linear equations and rearrange any formula to automaticity — the single most-used skill in physics",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The curriculum flags formula fluency as a skill you must never skip: physics constantly hands you a formula solved for the wrong variable, and you need to make any symbol the subject without hesitation. This chapter drills linear equations, rearrangement to automaticity, inequalities, systems of two equations, and the crucial craft of turning word problems into equations. Master it here and the density, pressure, and Ohm\'s-law chapters ahead become routine instead of roadblocks.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Linear equations</li>\n  <li>Rearranging any formula (make x the subject — to automaticity)</li>\n  <li>Inequalities</li>\n  <li>Systems of two equations</li>\n  <li>Word problems → equations</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"graphs-and-linear-models",title:"Graphs & Linear Models",subtitle:"The coordinate plane, y = mx + c, and reading physics directly from slopes and areas",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>A straight-line graph is the physicist's favorite measuring instrument: its slope and intercept each carry physical meaning, and proportionality shows up as a line through the origin. In this chapter you'll master the coordinate plane and y = mx + c, then learn the signature Phase 2 move — reading physics from graphs, where slope = speed and area = distance. This is exactly the skill the motion chapters of Subject 5 will lean on with distance–time and velocity–time graphs.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Coordinate plane</li>\n  <li>Slope &amp; intercept</li>\n  <li>y = mx + c</li>\n  <li>Proportionality as a line through the origin</li>\n  <li>Reading physics from graphs (slope = speed, area = distance)</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]},{id:"quadratics",title:"Quadratics",subtitle:"Factoring, completing the square, the quadratic formula, and the parabola",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Nature loves the parabola: thrown balls trace one, and the equations of accelerated motion are quadratic in time. This chapter gives you the complete solving toolkit — factoring, completing the square, and the quadratic formula — plus the geometric picture of the parabola that ties them together. It\'s the algebra behind projectile motion in Phase 3 and every "when does it land?" problem you\'ll ever meet.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Factoring</li>\n  <li>Completing the square</li>\n  <li>The quadratic formula</li>\n  <li>Parabolas</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"geometry-essentials",title:"Geometry Essentials",subtitle:"Triangles, Pythagoras, circles, areas and volumes — spatial fluency without proof drills",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Physics lives in space, so you need working command of angles, triangles, circles, areas, and volumes — the results and the spatial fluency, not two years of proof drills. Pythagoras alone earns its keep hundreds of times over: it's how you'll combine perpendicular quantities from displacement components to resultant forces. Similarity and scaling arguments also return here, powering everything from map problems to why density explains floating.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Angles &amp; triangles</li>\n  <li>Congruence &amp; similarity</li>\n  <li>Pythagoras</li>\n  <li>Circles</li>\n  <li>Areas &amp; volumes (results and spatial fluency, not proof drills)</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]},{id:"first-trigonometry",title:"First Trigonometry",subtitle:"SOH-CAH-TOA and solving right triangles — the first step toward vectors and projectiles",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Trigonometry is how physics splits the world into components, and it starts here with SOH-CAH-TOA and the art of solving right triangles. You'll handle angles of elevation and get a first look at the sine and cosine rules for triangles that aren't right-angled. This is the seed of the full trig mastery in Subject 10 that unlocks force decomposition, projectiles, and the sinusoids of waves and oscillations.</p>\n<h3>Topics</h3>\n<ul>\n  <li>SOH-CAH-TOA</li>\n  <li>Solving right triangles</li>\n  <li>Angles of elevation</li>\n  <li>Sine &amp; cosine rules intro</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]}]},{id:"motion-and-forces",number:5,title:"Motion & Forces",description:"Your first complete, quantitative tour of mechanics at one-formula depth — motion, forces, pressure, buoyancy, and energy, in the classic Russian/Chinese grade 8–9 tradition.",phase:2,chapters:[{id:"describing-motion",title:"Describing Motion",subtitle:"Speed, acceleration, and the motion graphs that turn movement into mathematics",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Before physics can explain motion it has to describe it, and this chapter builds that vocabulary: distance versus displacement, speed as the ratio v = d/t, and acceleration as the rate speed changes. The real power move is graphical — distance–time and velocity–time graphs, where the slope-and-area reading skills from Subject 4 pay off immediately. Everything in mechanics, all the way to the calculus-based courses of Phase 4, starts from the ideas laid down here.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Distance &amp; displacement</li>\n  <li>Speed v = d/t</li>\n  <li>Distance–time graphs</li>\n  <li>Acceleration</li>\n  <li>Velocity–time graphs</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"mass-density-and-measurement",title:"Mass, Density & Measurement",subtitle:"Mass vs weight, ρ = m/V, and the measuring instruments of the physics lab",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Mass and weight are different things — one measures how much matter you have, the other the pull of gravity on it — and keeping them straight is a rite of passage. This chapter introduces density ρ = m/V as your first great ratio formula and shows how it explains why steel sinks while ships float, setting up the buoyancy chapter ahead. You\'ll also meet the measuring instruments and habits of care that make quantitative physics trustworthy.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Mass vs weight</li>\n  <li>Density ρ = m/V</li>\n  <li>Measuring instruments</li>\n  <li>Why density explains floating</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"forces-and-inertia",title:"Forces & Inertia",subtitle:"Newton's first law, friction, Hooke's law, and the art of the force diagram",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Here you meet force as an interaction between objects and Newton's first law — the deeply counterintuitive claim that motion needs no force to continue, only to change. You'll work with friction, the elastic force and Hooke's law, and learn to draw force diagrams that reveal whether forces are balanced or produce a resultant. This qualitative-plus-one-formula treatment is the foundation the full vector treatment of Newton's laws in Subject 11 will build on.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Force as interaction</li>\n  <li>Newton's first law &amp; inertia</li>\n  <li>Friction</li>\n  <li>Elastic force &amp; Hooke's law</li>\n  <li>Force diagrams</li>\n  <li>Balanced vs unbalanced forces</li>\n  <li>Resultants</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]},{id:"pressure-and-buoyancy",title:"Pressure & Buoyancy",subtitle:"P = F/A, Pascal, and Archimedes — the celebrated grade-8 block on fluids at rest",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Why do snowshoes work, why does pressure crush at the bottom of the ocean, and why does a massive steel ship float? This chapter — the great pressure-and-buoyancy block of the Russian and Chinese grade-8 tradition — answers all three with P = F/A, the behavior of pressure in liquids and the atmosphere, Pascal's principle, and Archimedes' principle. It's some of the most satisfying physics in the whole first tour, and it previews the fluids chapter of Subject 11.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Pressure P = F/A</li>\n  <li>Pressure in liquids</li>\n  <li>Atmospheric pressure</li>\n  <li>Pascal's principle</li>\n  <li>Archimedes' principle &amp; floating (the great Russian/Chinese grade-8 block)</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]},{id:"work-energy-power-and-machines",title:"Work, Energy, Power & Machines",subtitle:"W = Fd, energy conservation, and why no machine can cheat the golden rule of mechanics",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Energy is the unifying spine of this entire curriculum, and here it becomes quantitative for the first time: work W = Fd, kinetic and potential energy, power, and the conservation idea that no process ever creates or destroys energy. Levers, pulleys, and moments then reveal the "golden rule" of mechanics — what a machine gains in force it pays back in distance — along with the honest bookkeeping of efficiency. The conservation reasoning you start here escalates continuously through every later phase.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Work W = Fd</li>\n  <li>Kinetic &amp; potential energy</li>\n  <li>Conservation intro</li>\n  <li>Power</li>\n  <li>Levers &amp; moments</li>\n  <li>Pulleys</li>\n  <li>Efficiency</li>\n  <li>The "golden rule" of mechanics</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]}]},{id:"heat-and-particle-model",number:6,title:"Heat & the Particle Model",description:"See heat through the eyes of jostling molecules: the particle model, temperature and internal energy, heat transfer, and the engines that turned thermal physics into the industrial revolution.",phase:2,chapters:[{id:"the-particle-model-of-matter",title:"The Particle Model of Matter",subtitle:"Molecules, diffusion, and Brownian motion — the evidence that matter is made of moving particles",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The single most powerful idea in this subject is that everything is made of tiny particles in ceaseless motion — and this chapter shows you the evidence, from diffusion to the jittery dance of Brownian motion that convinced the world atoms are real. With that picture you can explain solids, liquids, gases, and why a gas pushes on its container: countless particle collisions per second. This model is the seed of the full kinetic theory you\'ll derive in Subject 12 and the statistical mechanics of Phase 5.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Molecules</li>\n  <li>Diffusion</li>\n  <li>Brownian motion</li>\n  <li>States explained</li>\n  <li>Gas pressure from particle collisions</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"temperature-and-internal-energy",title:"Temperature & Internal Energy",subtitle:"What thermometers actually measure, and the energy hidden inside every object",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Temperature and heat are not the same thing — a spark can be white-hot yet carry less energy than a warm bathtub — and this chapter makes the distinction precise. You\'ll see how thermometers and temperature scales work, meet internal energy as the total energy of all those jostling particles, and explain thermal expansion from the particle picture. These definitions are the groundwork for the first law of thermodynamics in Subject 12.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Thermometers &amp; scales</li>\n  <li>Internal energy</li>\n  <li>Thermal expansion</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"heat-transfer",title:"Heat Transfer",subtitle:"Conduction, convection, and radiation — how thermal energy moves and how we stop it",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Heat always finds a way to move, and it has exactly three: conduction through touching particles, convection in flowing fluids, and radiation that crosses even empty space. This chapter shows each mechanism at work — in cooking pans, sea breezes, and sunlight — and then flips the question to insulation: how houses, thermos flasks, and spacecraft slow the flow. It's the everyday physics you'll use most, and it returns quantitatively in the thermal chapters ahead.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Conduction</li>\n  <li>Convection</li>\n  <li>Radiation</li>\n  <li>Applications &amp; insulation</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]},{id:"specific-and-latent-heat",title:"Specific & Latent Heat",subtitle:"Heating curves, Q = mcΔT, and the hidden energy of melting and boiling",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Why does a heating curve flatten out while ice melts, even though the burner keeps burning? This chapter answers with the two central formulas of school thermal physics: Q = mcΔT for warming a substance, and latent heat for the energy that goes into changing its state instead of its temperature. Reading heating curves and doing this energy bookkeeping is exactly the calorimetry skill that Subject 12 will sharpen and extend.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Heating curves</li>\n  <li>Q = mcΔT</li>\n  <li>Phase changes &amp; latent heat</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"heat-engines-and-energy-use",title:"Heat Engines & Energy Use",subtitle:"From steam turbines to car engines — turning heat into work, and the price of efficiency",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>The machines that built the modern world — steam turbines and internal-combustion engines — all do the same trick: turn disordered heat into ordered work. This chapter tours how they operate, why no engine converts all its heat (efficiency has a fundamental price tag), and how that shapes society's energy resources. It plants the question — why can't efficiency reach 100%? — that the second law of thermodynamics answers in Subject 12.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Internal combustion</li>\n  <li>Steam turbines</li>\n  <li>Efficiency</li>\n  <li>Energy resources</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]}]},{id:"sound-light-optics",number:7,title:"Sound, Light & Optics",description:"From vibrating strings to rainbows: your first pass through waves, sound, mirrors, lenses, and the electromagnetic spectrum — the physics of everything you see and hear.",phase:2,chapters:[{id:"sound",title:"Sound",subtitle:"Vibrations traveling through air — pitch, loudness, echoes, and ultrasound",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Every sound you\'ve ever heard began as a vibration, and this chapter follows that vibration from source to ear: how fast sound travels, why frequency sets pitch and amplitude sets loudness, and how echoes and ultrasound put reflections to work in sonar and medical imaging. Sound is the friendliest wave to start with because you can feel it, making it the perfect on-ramp to the wave concepts that follow. The Doppler effect and decibel mathematics wait for the second pass in Subject 13.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Vibrations &amp; waves</li>\n  <li>Speed of sound</li>\n  <li>Pitch/frequency</li>\n  <li>Loudness/amplitude</li>\n  <li>Echoes &amp; ultrasound</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"wave-basics",title:"Wave Basics",subtitle:"Transverse and longitudinal waves, and the master formula v = fλ",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Waves are the hinge of all physics — MIT makes them the gateway to both quantum and statistical physics — and this chapter is your first formal introduction. You\'ll distinguish transverse from longitudinal waves, learn the vocabulary of wavelength, frequency, and amplitude, and wield the one formula that governs every wave in the universe: v = fλ. Sound, light, radio, and eventually matter itself all obey it.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Transverse &amp; longitudinal waves</li>\n  <li>Wavelength, frequency, amplitude</li>\n  <li>v = fλ</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"reflection-and-mirrors",title:"Reflection & Mirrors",subtitle:"The law of reflection and the images formed by plane and curved mirrors",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Light travels in straight lines and bounces by one beautifully simple rule — the angle of incidence equals the angle of reflection — and from that single law this chapter builds the whole optics of mirrors. You\'ll explain why your bathroom-mirror image appears behind the glass and stands left-right reversed, then move to curved mirrors that focus light for telescopes, headlights, and security mirrors. Ray diagrams learned here are the core technique for all of geometric optics.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Law of reflection</li>\n  <li>Plane-mirror images</li>\n  <li>Curved mirrors</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"refraction-and-lenses",title:"Refraction & Lenses",subtitle:"Bending light: total internal reflection, optical fibres, and ray diagrams for lenses",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>When light crosses from air into water or glass it bends — and that one fact gives us lenses, optical fibres, and the strange sight of a straw "broken" in a glass of water. This chapter covers refraction, total internal reflection (the trick that pipes the internet around the planet), and converging and diverging lenses with the ray diagrams and magnification rules to predict their images. Every optical instrument in the next chapter is built from these pieces, and Subject 13 makes them fully quantitative.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Refraction</li>\n  <li>Total internal reflection &amp; optical fibres</li>\n  <li>Converging/diverging lenses</li>\n  <li>Ray diagrams</li>\n  <li>Magnification</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"the-eye-cameras-and-instruments",title:"The Eye, Cameras & Instruments",subtitle:"Optics applied: vision and its correction, cameras, microscopes, and telescopes",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Your own eye is a living camera — a lens focusing images onto a light-sensitive screen — and this chapter uses everything you've learned about lenses to explain how it works and how glasses correct near- and far-sightedness. From there you'll see how the same principles scale up: cameras that record, microscopes that magnify the invisibly small, and telescopes that gather light from the edge of the universe. It's the payoff chapter where optics meets daily life and scientific discovery.</p>\n<h3>Topics</h3>\n<ul>\n  <li>The eye &amp; vision correction</li>\n  <li>Cameras</li>\n  <li>Microscope</li>\n  <li>Telescope</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]},{id:"colour-and-the-em-spectrum",title:"Colour & the EM Spectrum",subtitle:"Dispersion, rainbows, and light's vast invisible family from radio waves to gamma rays",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>A prism reveals that white light is a mixture — dispersion fans it into the spectrum, and raindrops do the same to paint rainbows across the sky. This chapter explains colour, then widens the view dramatically: visible light is one narrow band in an electromagnetic family running from radio waves through microwaves, infrared, ultraviolet, and X-rays to gamma rays. This spectrum tour becomes a recurring landmark — you'll revisit it with Maxwell's equations and again when quantum physics asks what light really is.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Dispersion &amp; rainbows</li>\n  <li>Colour</li>\n  <li>The electromagnetic-spectrum family tour (radio → gamma)</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]}]},{id:"electricity-and-magnetism",number:8,title:"Electricity & Magnetism",description:"From static sparks to the power grid: charge, circuits, Ohm's law, magnetism, and the motors and generators that electrified the world — all at first-pass, one-formula depth.",phase:2,chapters:[{id:"static-electricity",title:"Static Electricity",subtitle:"Charge, attraction and repulsion, lightning, and a first feel for the electric field",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Electricity begins with charge — the property that makes rubbed balloons stick to walls and lightning leap from clouds. This chapter covers electrization, the rules of attraction and repulsion, and the remarkable fact that all charge comes in multiples of one elementary unit carried by the electron. You'll also get your first qualitative feel for the electric field, the concept Subject 14 will make fully quantitative with Coulomb's law.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Charge</li>\n  <li>Electrization</li>\n  <li>Attraction &amp; repulsion</li>\n  <li>The elementary charge</li>\n  <li>Lightning</li>\n  <li>Electric field qualitatively</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]},{id:"current-and-circuits",title:"Current & Circuits",subtitle:"Current, voltage, and resistance — and how to read and build series and parallel circuits",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Set charge flowing and you have current — the lifeblood of every device you own. This chapter builds the three-way vocabulary of current, voltage, and resistance, teaches you to read and draw circuit diagrams, and explores the two fundamental ways to connect components: series and parallel. These circuit-tracing skills are pure prerequisite gold: Ohm's law is one chapter away, and Kirchhoff's laws in Subject 14 assume them completely.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Current</li>\n  <li>Voltage</li>\n  <li>Resistance</li>\n  <li>Circuit diagrams</li>\n  <li>Series &amp; parallel circuits</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]},{id:"ohms-law-and-resistance",title:"Ohm's Law & Resistance",subtitle:"V = IR — the one formula that governs every circuit — and what resistance depends on",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>V = IR is the archetypal one-formula chapter: a single ratio statement that lets you predict any of current, voltage, or resistance from the other two — a direct payoff of the proportional reasoning and formula fluency you've been building since Subject 1. You'll then look inside resistance itself: how a wire's length, thickness, and material set its opposition to current, with a first taste of resistivity. This is the workhorse law of all circuit analysis to come.</p>\n<h3>Topics</h3>\n<ul>\n  <li>V = IR</li>\n  <li>What resistance depends on</li>\n  <li>Resistivity intro</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]},{id:"electrical-power-and-home-electricity",title:"Electrical Power & Home Electricity",subtitle:"P = VI, Joule heating, your electricity bill, and the safety systems in your walls",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>This chapter connects circuit physics to your monthly bill: P = VI gives the power any appliance draws, Joule heating explains why wires warm up (toasters on purpose, overloaded cords dangerously), and the kilowatt-hour turns out to be simply a unit of energy you buy. You\'ll finish with the safety engineering hidden in every home — fuses, earthing, and the design choices that keep mains electricity from being lethal. Few chapters pay off faster in everyday practical understanding.</p>\n<h3>Topics</h3>\n<ul>\n  <li>P = VI</li>\n  <li>Joule heating</li>\n  <li>kWh &amp; electricity bills</li>\n  <li>Fuses, earthing, safety</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"magnetism",title:"Magnetism",subtitle:"Magnets, fields, Earth's compass, and the discovery that currents are magnetic too",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Magnetism starts with poles and field patterns you can map with iron filings, and with Earth's own magnetic field that has guided navigators for a thousand years. The turning point of the chapter — and historically, of physics — is Oersted's discovery that an electric current creates a magnetic field, uniting two seemingly separate phenomena and giving us the electromagnet. That link between electricity and magnetism sets up the motors and generators of the next chapter and, ultimately, all of electromagnetism.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Magnets &amp; fields</li>\n  <li>Earth's magnetic field</li>\n  <li>Magnetic field of a current</li>\n  <li>Electromagnets</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]},{id:"motors-generators-and-induction",title:"Motors, Generators & Induction",subtitle:"The physics that electrified civilization: motors, Faraday's induction, and the grid",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Put a current-carrying wire in a magnetic field and it feels a force — spin that idea and you have the DC motor. Run it in reverse and you get Faraday's electromagnetic induction: moving a magnet near a coil generates current, which is how essentially all of the world's electricity is made. This capstone chapter follows the chain from generator through transformer to the grid that reaches your home, and it's the first-pass preview of the full induction treatment in Subject 14.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Force on a current-carrying wire</li>\n  <li>The DC motor</li>\n  <li>Electromagnetic induction</li>\n  <li>Generators</li>\n  <li>Transformers &amp; the grid</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]}]},{id:"atoms-nuclei-energy",number:9,title:"Atoms, Nuclei & Energy",description:"The first-pass finale: journey inside the atom, meet radioactivity and nuclear power, and step back to ask how humanity should power its future.",phase:2,chapters:[{id:"inside-the-atom",title:"Inside the Atom",subtitle:"From Thomson's plum pudding to Bohr's orbits — how we discovered what atoms are made of",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>How do you discover the structure of something too small to see? This chapter retraces the detective story — Thomson finding the electron, Rutherford's gold-foil shock revealing the tiny dense nucleus, Bohr's quantized orbits — as a masterclass in how physics actually progresses by breaking its own models. You'll come away knowing electrons, protons, neutrons, and isotopes, the cast of characters for radioactivity next chapter and for the full quantum story in Subject 15.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Atomic models in history (Thomson → Rutherford → Bohr)</li>\n  <li>Electrons, protons, neutrons</li>\n  <li>Isotopes</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]},{id:"radioactivity",title:"Radioactivity",subtitle:"Alpha, beta, gamma, and half-life — unstable nuclei and what their radiation can do",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Some nuclei are unstable, and when they decay they emit three distinct kinds of radiation — alpha, beta, and gamma — each with its own character, penetrating power, and dangers. This chapter introduces half-life, the beautifully predictable statistics of unpredictable decays, along with how we detect radiation and use it safely in medicine, dating, and industry. The exponential decay law N = N₀e^(−λt) gets its quantitative treatment in Subject 15; here you build the physical intuition.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Alpha, beta, gamma</li>\n  <li>Half-life</li>\n  <li>Detection</li>\n  <li>Safety &amp; uses</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"nuclear-energy",title:"Nuclear Energy",subtitle:"Fission, fusion, and reactors — the enormous energy locked inside the nucleus",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Split a heavy nucleus (fission) or fuse two light ones (fusion) and a tiny amount of mass converts into a staggering amount of energy — the process that powers reactors, bombs, and every star in the sky. This chapter explains both reactions, how a reactor tames a chain reaction, and gives your first look at the mass–energy idea behind E = mc\xb2. Subject 15 will return to compute binding energies; here you grasp why nuclear energy is a million times denser than chemical.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Fission</li>\n  <li>Fusion</li>\n  <li>Reactors</li>\n  <li>Mass-energy intro</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"energy-and-society",title:"Energy & Society",subtitle:"Energy resources, renewables, and the physics behind humanity's biggest decisions",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>The capstone of the first full tour steps back to the biggest question physics informs: how should civilization power itself? Armed with the energy-conservation spine that has run through every subject since Phase 1, you'll compare energy resources — fossil, nuclear, solar, wind, hydro — on physical merit: density, reliability, and sustainability. It's practice at what this whole curriculum is for — using quantitative reasoning on questions that actually matter.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Energy resources</li>\n  <li>Renewables</li>\n  <li>Sustainability</li>\n  <li>The energy future</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]}]},{id:"precalculus-and-vectors",number:10,title:"Precalculus & Vectors",description:"The complete math upgrade for quantitative physics: functions, logs, deep trigonometry, vectors, complex numbers, and the first taste of calculus — everything Phase 3 needs, exactly one step ahead.",phase:3,chapters:[{id:"functions",title:"Functions",subtitle:"The function concept, transformations, and reasoning about how quantities depend on each other",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Physics is the study of how one quantity depends on another, and the function is the mathematical machine that captures dependence. This chapter builds the concept properly — composition, inverses, transformations that shift and stretch graphs — and teaches the qualitative and asymptotic reasoning physicists use constantly: what happens as x grows huge or shrinks to zero? These habits of thinking about behavior, not just computing values, mark the shift from school math to physics-ready math.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Function concept</li>\n  <li>Composition</li>\n  <li>Inverses</li>\n  <li>Transformations</li>\n  <li>Rational functions</li>\n  <li>Qualitative/asymptotic reasoning</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"exponentials-and-logarithms",title:"Exponentials & Logarithms",subtitle:"Growth, decay, e, and the log scales — dB, pH, Richter — that tame huge ranges",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Radioactive decay, capacitor discharge, sound intensity, earthquake magnitude — an astonishing amount of physics is exponential, and logarithms are how you read it. This chapter covers exponential growth and decay, the special number e, log rules drilled to automaticity, and the log scales (decibels, pH, Richter) plus semilog plots that turn exponential curves into readable straight lines. You\'ll use these tools directly in the decay law of Subject 15 and the decibel work of Subject 13.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Exponential growth &amp; decay</li>\n  <li>e</li>\n  <li>Log rules (to automaticity)</li>\n  <li>Log scales (dB, pH, Richter)</li>\n  <li>Semilog plots</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"trigonometry-mastery",title:"Trigonometry Mastery",subtitle:"The unit circle from memory, radians, identities — the never-skip chapter of the math ladder",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The curriculum lists the unit circle among the skills you must never skip, because trigonometry is the language of everything that rotates, oscillates, or waves. This chapter takes you well past SOH-CAH-TOA: the unit circle from memory, radians as the natural angle measure, the graphs of sin, cos, and tan with amplitude, period, and phase, plus the identity toolkit and trig equations. Simple harmonic motion, wave equations like y = A sin(kx − ωt), and AC circuits all read like applied trigonometry afterward.</p>\n<h3>Topics</h3>\n<ul>\n  <li>The unit circle (from memory)</li>\n  <li>Radians</li>\n  <li>Graphs of sin/cos/tan</li>\n  <li>Amplitude, period, phase</li>\n  <li>Pythagorean/sum/double-angle identities</li>\n  <li>Trig equations</li>\n  <li>Inverse trig</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"vectors",title:"Vectors",subtitle:"Components, dot and cross products — the mathematical objects forces actually are",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Force, velocity, acceleration, and field are all vectors — quantities with direction — and this never-skip chapter teaches you to compute with them: components, addition, and the two products (dot and cross) with their geometric meanings. The entire second pass through mechanics in Subject 11 is titled "with vectors" because this is the upgrade that makes inclined planes, projectiles, and torque tractable. Work as a dot product and magnetic force as a cross product will feel natural once this chapter is behind you.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Components</li>\n  <li>Addition</li>\n  <li>Dot product</li>\n  <li>Cross product</li>\n  <li>Geometric meaning</li>\n  <li>Vectors in physics</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"complex-numbers",title:"Complex Numbers",subtitle:"The Argand plane, polar form, and a preview of Euler's formula — quantum's native language",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Complex numbers begin as a curiosity — a number whose square is negative — and end up as physics's secret weapon: AC circuit analysis, wave superposition, and the whole of quantum mechanics run on them. This chapter covers complex arithmetic, the Argand-plane picture that makes multiplication a rotation, polar form, and a preview of Euler's formula e^(iθ) = cos θ + i sin θ, often called the most beautiful equation in mathematics. Investing here pays compound interest through Phases 4 and 5.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Arithmetic</li>\n  <li>The Argand plane</li>\n  <li>Polar form</li>\n  <li>Euler's formula preview</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]},{id:"sequences-series-and-approximation",title:"Sequences, Series & Approximation",subtitle:"Geometric series, the binomial theorem, and small-x expansions — physics's favorite move",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The curriculum calls small-x expansion "the most-used move in physics" — and lists Taylor-expansion thinking among the skills never to skip — because real physics problems are rarely solved exactly; they\'re approximated intelligently. This chapter builds up from arithmetic and geometric series through the binomial theorem to that art of approximation: replacing complicated expressions with simple ones valid when a quantity is small. It\'s how the pendulum becomes simple harmonic and how relativity reduces to Newton at everyday speeds.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Arithmetic &amp; geometric series</li>\n  <li>Binomial theorem</li>\n  <li>The art of approximation (small-x expansions — the most-used move in physics)</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"limits-and-the-idea-of-calculus",title:"Limits & the Idea of Calculus",subtitle:"The derivative as rate, the integral as area, and first calculus applied to motion",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Here you meet the two greatest ideas in applied mathematics: the derivative as an instantaneous rate (the exact slope your motion graphs have been hinting at) and the integral as accumulated area. Following the Singapore Additional-Math model, you\'ll immediately apply basic calculus to kinematics — velocity as the derivative of position, distance as the integral of velocity — so the concepts land on physics you already know. This preview makes the full calculus sequence of Subject 16, and F = ma as a differential equation, far less of a cliff.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Limits &amp; continuity</li>\n  <li>The derivative as slope/rate</li>\n  <li>The integral as area</li>\n  <li>Kinematics with basic calculus (the Singapore Additional-Math move)</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"probability-and-statistics-foundations",title:"Probability & Statistics Foundations",subtitle:"Counting, distributions, mean and variance, and the ubiquitous normal curve",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Modern physics is statistical to its core — quantum mechanics predicts probabilities, and thermodynamics is the statistics of 10\xb2\xb3 particles — so probabilistic thinking belongs in your foundation. This chapter covers counting, the probability rules, an introduction to distributions, mean and variance, and the normal curve that appears everywhere from measurement error to molecular speeds. It also underpins honest data analysis: every lab measurement you\'ll ever quote needs an uncertainty, and uncertainty is statistics.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Counting</li>\n  <li>Probability rules</li>\n  <li>Distributions intro</li>\n  <li>Mean &amp; variance</li>\n  <li>The normal curve</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]}]},{id:"mechanics-with-vectors",number:11,title:"Mechanics",description:"The second pass through mechanics, now armed with vectors and trigonometry: projectiles, Newton's laws in full, momentum, energy, orbits, rotation, oscillations, and fluids at A-level/NCERT depth.",phase:3,chapters:[{id:"measurement-and-uncertainty",title:"Measurement & Uncertainty",subtitle:"SI units, dimensional analysis, and honest error handling — the craft of quantitative science",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Quantitative physics begins with knowing exactly what your numbers mean, and this chapter professionalizes that: the SI system in full, dimensional analysis as a superpower for checking (and sometimes deriving) formulas, and the basics of error propagation with significant figures done properly. Dimensional thinking alone will save you from more wrong answers than any other single habit. Every multi-step problem in the rest of Phase 3 leans on the discipline you build here.</p>\n<h3>Topics</h3>\n<ul>\n  <li>SI system</li>\n  <li>Dimensional analysis</li>\n  <li>Error propagation basics</li>\n  <li>Significant figures properly</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"kinematics-in-1d-and-2d",title:"Kinematics in 1D & 2D",subtitle:"The suvat equations, free fall, and projectile motion — vectors earning their keep",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The suvat equations turn uniformly accelerated motion into pure algebra, and free fall becomes their most famous application. Then the vector toolkit from Subject 10 unlocks two dimensions: projectile motion splits into independent horizontal and vertical stories, and suddenly you can predict where the ball lands. Relative motion rounds out the chapter — the gateway idea to reference frames that special relativity will one day make profound.</p>\n<h3>Topics</h3>\n<ul>\n  <li>The suvat equations</li>\n  <li>Free fall</li>\n  <li>Projectile motion</li>\n  <li>Relative motion</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"newtons-laws-properly",title:"Newton's Laws Properly",subtitle:"Force decomposition, friction models, tension, and connected bodies — real problem-solving begins",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>This is where mechanics becomes a true problem-solving discipline: all three of Newton\'s laws deployed with vector decomposition on inclined planes, quantitative friction models, and the tension and normal forces that appear in every free-body diagram. Connected bodies — blocks and pulleys moving together — and apparent weight in accelerating elevators are the classic multi-step problems of the A-level/JEE tradition. The systematic method you learn here is the template for attacking any force problem for the rest of the curriculum.</p>\n<h3>Topics</h3>\n<ul>\n  <li>The three laws</li>\n  <li>Force decomposition on inclines</li>\n  <li>Friction models</li>\n  <li>Tension &amp; normal forces</li>\n  <li>Connected bodies</li>\n  <li>Apparent weight</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"momentum-and-collisions",title:"Momentum & Collisions",subtitle:"Impulse, conservation of momentum, and the physics of crashes, recoil, and rockets",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Momentum is the first of the great conservation laws you'll wield as a computational tool: in any collision or explosion, total momentum before equals total momentum after, no matter how messy the details. This chapter covers impulse (why airbags and crumple zones save lives), elastic versus inelastic collisions, and the recoil logic that makes rockets work by throwing mass backward. Conservation-law reasoning — solving problems while ignoring complicated intermediate forces — is a habit of mind you'll use through quantum mechanics and particle physics.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Impulse</li>\n  <li>Conservation of momentum</li>\n  <li>Elastic &amp; inelastic collisions</li>\n  <li>Recoil &amp; rockets</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]},{id:"work-energy-and-conservation",title:"Work, Energy & Conservation",subtitle:"Varying forces, conservative forces, and energy conservation as a problem-solving superpower",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The energy ideas from the first pass return with full quantitative teeth: work done by varying forces, kinetic and potential energy precisely defined, and the crucial concept of a conservative force — one whose work depends only on endpoints, letting you define potential energy at all. Energy conservation then becomes your most elegant solver: problems that would demand pages of force analysis fall in three lines. With power added, this chapter completes the energy toolkit that Phases 4 and 5 will deepen with calculus and reformulate as Lagrangians.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Work by a varying force</li>\n  <li>KE &amp; PE</li>\n  <li>Conservative forces</li>\n  <li>Energy conservation</li>\n  <li>Power</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"circular-motion-and-gravitation",title:"Circular Motion & Gravitation",subtitle:"Centripetal acceleration, Newton's gravity, Kepler's laws, and the physics of orbits",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Circular motion holds a beautiful surprise: an object moving at constant speed is still accelerating, because its direction changes — and that centripetal acceleration explains banked curves, spin cycles, and every orbit in the sky. Newton's law of gravitation then performs history's great unification, showing the fall of an apple and the orbit of the Moon are the same physics, with Kepler's laws emerging as consequences. Gravitational fields, potential energy, and satellite motion complete a chapter that runs from race tracks to the Solar System.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Centripetal acceleration</li>\n  <li>Banked curves</li>\n  <li>Newton's law of gravitation</li>\n  <li>Orbits &amp; Kepler's laws</li>\n  <li>Gravitational field &amp; potential energy</li>\n  <li>Satellites</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]},{id:"rotation-and-statics",title:"Rotation & Statics",subtitle:"Torque, moment of inertia, angular momentum, and why structures stand or fall",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Rotation gets its own complete dynamics, in perfect parallel with what you know: torque plays the role of force, moment of inertia the role of mass, and angular momentum the role of momentum — conserved, which is why spinning skaters speed up when they pull in their arms. Rolling motion combines translation and rotation, while statics applies the equilibrium conditions to explain why bridges, ladders, and cranes stand. This rotational toolkit returns with integrals in Phase 4 and with the inertia tensor in Phase 5.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Torque</li>\n  <li>Moment of inertia</li>\n  <li>Angular momentum</li>\n  <li>Rolling</li>\n  <li>Equilibrium &amp; stability</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"oscillations",title:"Oscillations",subtitle:"Simple harmonic motion, pendulums and springs, damping and resonance — the heartbeat of physics",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Simple harmonic motion may be the single most important model in physics: pendulums, springs, molecules, bridges, and quantum fields all oscillate, and the trigonometry you mastered in Subject 10 now describes them exactly. You\'ll analyze the pendulum and spring quantitatively, track how energy sloshes between kinetic and potential forms, and meet damping and resonance — the phenomenon that shatters wine glasses and topples bridges. SHM is also the direct on-ramp to waves in Subject 13 and the oscillator ODEs of Phase 4.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Simple harmonic motion</li>\n  <li>Pendulum &amp; spring</li>\n  <li>Energy in SHM</li>\n  <li>Damping &amp; resonance</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"fluids",title:"Fluids",subtitle:"Continuity, Bernoulli's principle, and a first look at viscosity — mechanics of flow",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>The pressure and buoyancy of the first pass return with mathematics, and then the fluid starts moving: the continuity equation says what flows in must flow out (why rivers speed up where they narrow), and Bernoulli's principle — energy conservation applied to flow — connects fast-moving fluid to low pressure. Together they illuminate airplane wings, chimney draft, and blood flow, with viscosity introduced as the fluid's internal friction. It's the mechanics finale that shows Newton's framework handles matter that flows.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Pressure revisited</li>\n  <li>Continuity equation</li>\n  <li>Bernoulli's principle</li>\n  <li>Viscosity intro</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]}]},{id:"thermal-physics",number:12,title:"Thermal Physics",description:"Heat becomes exact: the ideal gas from kinetic theory, the first law's energy bookkeeping, and the second law's deep truth about engines, entropy, and the arrow of time.",phase:3,chapters:[{id:"temperature-and-ideal-gases",title:"Temperature & Ideal Gases",subtitle:"The gas laws, PV = nRT, and deriving pressure from molecules in motion",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>This chapter delivers one of physics's great payoffs: starting from the particle model of Phase 2, you'll derive the pressure of a gas from nothing but molecules bouncing off walls — connecting the invisible microscopic world to a formula you can test with a pump. Along the way come thermal equilibrium and the zeroth law, the historical gas laws, and their unification in the ideal-gas equation, plus the distribution of molecular speeds. It's your first genuine taste of the statistical thinking that Phase 5's statistical mechanics builds into a full theory.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Thermal equilibrium &amp; the zeroth law</li>\n  <li>Gas laws</li>\n  <li>Ideal-gas equation</li>\n  <li>Kinetic-theory derivation of pressure</li>\n  <li>Molecular speeds</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]},{id:"the-first-law",title:"The First Law",subtitle:"Internal energy, heat, and work — energy bookkeeping on P–V diagrams",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>The first law of thermodynamics is energy conservation with the books finally balanced: a gas's internal energy changes only through heat flowing in or work being done. You'll learn why gases have two specific heats, follow isothermal and adiabatic processes, and master the P–V diagram — the graphical language where the area under a curve is work, and closed loops become engine cycles. This bookkeeping is the foundation for the engines and entropy of the next chapter and for all of thermodynamics beyond.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Internal energy</li>\n  <li>Heat &amp; work</li>\n  <li>Specific heats of gases</li>\n  <li>Isothermal &amp; adiabatic processes</li>\n  <li>P–V diagrams</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]},{id:"the-second-law-intro",title:"The Second Law (intro)",subtitle:"Heat engines, Carnot's limit, and a first meeting with entropy and time's arrow",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The second law is arguably the deepest statement in classical physics: heat flows one way, no engine can be perfect, and the universe keeps score with a quantity called entropy. This chapter analyzes heat engines and refrigerators, derives the Carnot efficiency — the fundamental ceiling no engineering cleverness can beat, answering the question planted back in Subject 6 — and gives you a first look at entropy. Subject 28 will rebuild it all from counting microstates; here you meet the law that gives time its direction.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Heat engines</li>\n  <li>Refrigerators</li>\n  <li>Carnot efficiency</li>\n  <li>Entropy first look</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"thermal-properties-of-matter",title:"Thermal Properties of Matter",subtitle:"Calorimetry with rigor, phase diagrams, humidity, and where the ideal gas breaks down",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Real matter is richer than the ideal gas, and this chapter maps that richness: calorimetry revisited with full quantitative rigor, and phase diagrams — the pressure–temperature maps showing where a substance is solid, liquid, or gas, complete with triple and critical points. Humidity brings the physics of water vapor into weather you experience daily, and real gases show where and why the ideal model bends. It closes the Phase 3 thermal story and sets up the deeper treatment of phase transitions in statistical mechanics.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Calorimetry revisited</li>\n  <li>Phase diagrams</li>\n  <li>Humidity</li>\n  <li>Real gases</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]}]},{id:"waves-and-optics",number:13,title:"Waves & Optics",description:"The quantitative second pass at waves — from y = A sin(kx − ωt) to superposition, the Doppler effect, double-slit interference, and the lens equation.",phase:3,chapters:[{id:"wave-motion",title:"Wave Motion",subtitle:"Travelling waves, the sinusoidal wave function, and what carries the energy",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Here the wave picture from Phase 2 becomes exact: a travelling wave is a moving sinusoid, y = A sin(kx − ωt), and every symbol in that expression earns its keep. You'll connect wave speed to the properties of the medium and learn how energy and intensity ride along — the mathematics that Phase 4's wave equation will later derive from first principles.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Travelling waves</li>\n  <li>y = A sin(kx − ωt)</li>\n  <li>Wave speed on strings</li>\n  <li>Energy &amp; intensity</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]},{id:"superposition",title:"Superposition",subtitle:"Interference, standing waves, harmonics, and beats",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Superposition is the single most consequential property of waves: two waves in the same place simply add. From that one rule comes interference, the standing waves that make guitar strings and organ pipes musical, and the beats piano tuners listen for. Quantum mechanics will reuse every idea in this chapter.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Interference</li>\n  <li>Standing waves</li>\n  <li>Harmonics &amp; music</li>\n  <li>Beats</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"sound-and-doppler",title:"Sound & Doppler",subtitle:"Sound made quantitative — decibels, moving sources, and shock waves",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Sound gets numbers: intensity and the logarithmic decibel scale (your log fluency from Subject 10 at work), then the Doppler effect that shifts a siren\'s pitch as it passes — the same physics astronomers use to measure the expanding universe — and the shock cones of supersonic flight.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Quantitative sound</li>\n  <li>Intensity &amp; decibels</li>\n  <li>The Doppler effect</li>\n  <li>Shock waves</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"wave-optics",title:"Wave Optics",subtitle:"Interference and diffraction — the experiments that prove light is a wave",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Young's double slit settled a century-long argument by making light interfere with itself. This chapter works through the geometry of interference fringes, diffraction from single slits and gratings, polarization, and the thin-film colors on soap bubbles — the evidence and mathematics behind light's wave nature.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Huygens' principle</li>\n  <li>Double-slit interference</li>\n  <li>Diffraction</li>\n  <li>Gratings</li>\n  <li>Polarization</li>\n  <li>Thin films</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]},{id:"ray-optics-quantitative",title:"Ray Optics Quantitative",subtitle:"Mirror and lens equations, instruments, and the limits of resolution",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The ray diagrams of Phase 2 become predictive formulas: the mirror and lens equations locate every image exactly, and combinations of lenses explain microscopes and telescopes. Diffraction returns at the end to set the ultimate resolution limit of any optical instrument — including your eye.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Mirror &amp; lens equations</li>\n  <li>Optical instruments</li>\n  <li>Resolution</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]}]},{id:"fields-circuits-electromagnetism",number:14,title:"Fields, Circuits & Electromagnetism",description:"The full A-level/H2-style treatment of electricity and magnetism: Coulomb's law and fields, capacitors, Kirchhoff's circuits, magnetic forces, Faraday's induction, and alternating current.",phase:3,chapters:[{id:"electric-fields",title:"Electric Fields",subtitle:"Coulomb's law, field strength, potential, and charges in motion",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>The field concept — physics's answer to action at a distance — takes center stage. Coulomb's law gives the force, field lines make it visible, and potential turns hard vector problems into easy energy bookkeeping. Charged-particle motion in uniform fields reruns projectile motion with electrons.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Coulomb's law</li>\n  <li>Field lines &amp; field strength</li>\n  <li>Potential &amp; potential difference</li>\n  <li>Equipotentials</li>\n  <li>Charged-particle motion in fields</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]},{id:"capacitance",title:"Capacitance",subtitle:"Storing energy in fields — capacitors, dielectrics, and RC charging",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Capacitors store energy in the electric field itself — the first hint that fields are physical things, not bookkeeping. You\'ll compute capacitance, follow the energy, see how dielectrics help, and meet the exponential charge/discharge curves that reappear everywhere from camera flashes to neuron membranes.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Capacitors</li>\n  <li>Energy storage</li>\n  <li>Dielectrics</li>\n  <li>RC charge/discharge</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"dc-circuits",title:"DC Circuits",subtitle:"EMF, Kirchhoff's laws, and the art of circuit analysis",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Ohm's law from Phase 2 grows into full circuit analysis: real batteries with internal resistance, Kirchhoff's two laws (which are just conservation of charge and energy in disguise), resistor networks, and the classic measuring instruments. This is the problem-solving heart of school electricity.</p>\n<h3>Topics</h3>\n<ul>\n  <li>EMF &amp; internal resistance</li>\n  <li>Kirchhoff's laws</li>\n  <li>Resistor networks</li>\n  <li>Meters</li>\n  <li>Potentiometer &amp; Wheatstone bridge</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]},{id:"magnetic-fields",title:"Magnetic Fields",subtitle:"Forces on moving charges — from F = qvB to the mass spectrometer",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Magnetism reveals its true identity: a force on moving charge. F = qvB and F = BIL unlock motors, the circular dance of charges in magnetic fields, the mass spectrometer that weighs atoms, and the Hall effect that lets your phone sense magnets.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Fields of currents</li>\n  <li>F = qvB and F = BIL</li>\n  <li>The Lorentz force</li>\n  <li>Mass spectrometer</li>\n  <li>Hall effect</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"electromagnetic-induction",title:"Electromagnetic Induction",subtitle:"Faraday's law — the principle behind nearly all electricity generation",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Faraday's discovery that changing magnetic flux drives current is arguably the most economically important physics ever done: it is how virtually every watt of grid electricity is generated. Flux, Faraday's and Lenz's laws, generators, eddy currents, and inductance — the complete induction toolkit.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Magnetic flux</li>\n  <li>Faraday's &amp; Lenz's laws</li>\n  <li>Generators</li>\n  <li>Eddy currents</li>\n  <li>Self &amp; mutual inductance</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]},{id:"alternating-current",title:"Alternating Current",subtitle:"RMS values, transformers, and why the grid is AC",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>AC won the war of currents because transformers make voltage conversion nearly lossless. You'll handle RMS values (why '230 V' is an average of sorts), reactance, transformer physics, and power transmission — then meet the electromagnetic waves that close out the classical story.</p>\n<h3>Topics</h3>\n<ul>\n  <li>RMS values</li>\n  <li>Reactance</li>\n  <li>Transformers</li>\n  <li>Power transmission</li>\n  <li>EM waves intro</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]}]},{id:"modern-physics",number:15,title:"Modern Physics",description:"The first quantitative pass at the twentieth century: special relativity, photons, wave-particle duality, the nucleus, semiconductors — and a tour of the frontier that motivates everything ahead.",phase:3,chapters:[{id:"special-relativity-intro",title:"Special Relativity Intro",subtitle:"Two postulates that rewrite space and time",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Einstein's two innocuous-sounding postulates — physics is the same in all inertial frames, and light's speed is invariant — force time dilation, length contraction, and the relativity of simultaneity. This first pass builds the intuition and the basic calculations; Phase 4's full course adds four-vectors and dynamics.</p>\n<h3>Topics</h3>\n<ul>\n  <li>The postulates</li>\n  <li>Time dilation</li>\n  <li>Length contraction</li>\n  <li>Simultaneity</li>\n  <li>E = mc\xb2 (first quantitative pass)</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]},{id:"quantization-of-light",title:"Quantization of Light",subtitle:"The photoelectric effect and the birth of the photon",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Classical physics predicted a blackbody catastrophe that never happens; Planck's fix and Einstein's photoelectric analysis revealed light comes in packets. The photoelectric effect, photon energy E = hf, Compton scattering, and X-rays — the experiments that started the quantum revolution.</p>\n<h3>Topics</h3>\n<ul>\n  <li>The blackbody problem</li>\n  <li>Photoelectric effect</li>\n  <li>Photons</li>\n  <li>Compton scattering</li>\n  <li>X-rays</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]},{id:"wave-particle-duality-atoms",title:"Wave–Particle Duality & Atoms",subtitle:"de Broglie's matter waves and the quantum atom",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>If light waves act like particles, do particles act like waves? de Broglie said yes, electron diffraction proved it, and Bohr used it to crack the hydrogen spectrum. Energy levels, spectral lines, and the uncertainty principle — the conceptual core that Quantum Mechanics I will make rigorous.</p>\n<h3>Topics</h3>\n<ul>\n  <li>de Broglie waves</li>\n  <li>Electron diffraction</li>\n  <li>Bohr model &amp; atomic spectra</li>\n  <li>Energy levels</li>\n  <li>Uncertainty principle intro</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"nucleus-quantitative",title:"The Nucleus, Quantitatively",subtitle:"Binding energy, the decay law, and nuclear energetics",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The nucleus gets numbers: mass defect and binding energy explain why iron is the most stable element and why both fission and fusion release energy. The exponential decay law N = N₀e^(−λt) puts your exponential/log fluency to work on half-lives and radiometric dating.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Binding energy &amp; mass defect</li>\n  <li>The decay law N = N₀e^(−λt)</li>\n  <li>Fission &amp; fusion energetics</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"semiconductors-electronics",title:"Semiconductors & Electronics",subtitle:"Bands, diodes, transistors — the physics inside every chip",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>A qualitative pass at the physics that powers civilization: energy bands, doping, the pn junction diode, LEDs, transistors as switches, and logic gates. If this hooks you, the LearnSemi sibling course and Phase 6\'s Solid State Physics go much deeper.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Energy bands qualitatively</li>\n  <li>Diodes &amp; LEDs</li>\n  <li>Transistors</li>\n  <li>Logic gates</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"particles-and-universe",title:"Particles & the Universe",subtitle:"A motivating tour of the Standard Model and the Big Bang",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>The 'physics is alive' chapter: a guided tour of quarks, leptons, and force carriers, the cosmic rays striking the atmosphere right now, and the three great lines of evidence for the Big Bang. No problem sets — just the map of where Phases 4–6 are headed.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Standard Model tour</li>\n  <li>Cosmic rays</li>\n  <li>Evidence for the Big Bang</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]}]},{id:"calculus-1-2",number:16,title:"Calculus I & II",description:"Single-variable calculus at MIT 18.01-level (Stewart/Thomas depth) — derivatives, integrals, series, and first differential equations, arriving exactly one step ahead of the calculus-based mechanics that needs them.",phase:4,chapters:[{id:"limits-derivatives",title:"Limits & Derivatives",subtitle:"Formal limits and the full differentiation toolkit, from the chain rule to related rates",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The derivative is the single most important idea in mathematical physics: it turns "how fast is this changing?" into something you can compute. This chapter makes limits precise and then builds the complete differentiation toolkit — the machinery you will use on day one of Classical Mechanics I, where velocity and acceleration become derivatives of position.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Formal limits</li>\n  <li>Differentiation rules</li>\n  <li>Chain rule</li>\n  <li>Implicit differentiation</li>\n  <li>Related rates</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"applications-of-derivatives",title:"Applications of Derivatives",subtitle:"Using derivatives to optimize, approximate, and analyze the shape of functions",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Once you can differentiate, you can answer real questions: where is a quantity largest, how does a function behave near a point, and what happens in tricky limiting cases. Linearization in particular is the physicist's reflex — replacing a complicated function by its tangent line is how half of physics gets solved. These skills return constantly, from finding stable equilibria in energy diagrams to small-angle approximations in oscillations.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Optimization</li>\n  <li>Linearization</li>\n  <li>L'H\xf4pital</li>\n  <li>Curve analysis</li>\n</ul>\n<div class=\"key-concept\">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>"}],quiz:[]},{id:"integration",title:"Integration",subtitle:"The fundamental theorem and the full toolkit of integration techniques",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Integration is addition taken to its logical extreme — summing infinitely many infinitesimal pieces — and the fundamental theorem of calculus reveals it as the inverse of differentiation. This chapter builds fluency with the standard techniques, because in Electromagnetism I you will integrate charge distributions and in mechanics you will recover motion from acceleration. The ∫ symbol is about to become your most-used tool.</p>\n<h3>Topics</h3>\n<ul>\n  <li>The fundamental theorem</li>\n  <li>Substitution</li>\n  <li>Integration by parts</li>\n  <li>Partial fractions</li>\n  <li>Trig integrals</li>\n  <li>Improper integrals</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"applications-of-integration",title:"Applications of Integration",subtitle:"Areas, volumes, arc length, work, and centre of mass — integrals doing physics",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Here the integral stops being abstract and starts computing physical things: the volume of a solid, the work done by a varying force, the balance point of an extended body. The "slice, sum, take the limit" pattern you practice here is exactly how physicists set up integrals for the rest of the curriculum — from moments of inertia to field calculations.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Areas & volumes</li>\n  <li>Arc length</li>\n  <li>Work & centre of mass</li>\n  <li>Average value</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"infinite-series",title:"Infinite Series",subtitle:"Convergence, power series, and Taylor expansions — physics's favourite approximation tool",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Taylor series are arguably the most-used tool in all of theoretical physics: nearly every "approximately equals" you will ever see is a truncated series. This chapter teaches when infinite sums converge, how to expand any function into powers of x, and how to control the error you make by stopping early. Master this and moves like sin θ ≈ θ or the low-speed limit of relativity become second nature.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Convergence</li>\n  <li>Power series</li>\n  <li>Taylor & Maclaurin series</li>\n  <li>Error bounds</li>\n  <li>Series as physics\'s favourite tool</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"intro-differential-equations",title:"Intro Differential Equations",subtitle:"First-order ODEs, exponential models, and direction fields — your first taste of physics's native language",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Newton\'s second law is a differential equation, so learning to solve simple ODEs is learning to read the laws of nature in their native language. This chapter covers separable and first-order linear equations and the exponential growth/decay models that describe everything from radioactive decay to RC circuits. It is the direct warm-up for terminal velocity — your first real ODE — in Classical Mechanics I.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Separable & first-order linear ODEs</li>\n  <li>Exponential models</li>\n  <li>Direction fields</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"parametric-polar",title:"Parametric & Polar",subtitle:"Curves as functions of time, polar coordinates, and vector-valued motion",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Physical trajectories are naturally parametric — position as a function of time — and many problems (orbits especially) are far simpler in polar coordinates than Cartesian ones. This chapter connects calculus to geometry in motion, ending with vector-valued functions: the exact mathematical form kinematics takes in the very next subject.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Parametric curves</li>\n  <li>Polar coordinates</li>\n  <li>Vector-valued functions & motion</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]}]},{id:"classical-mechanics-1",number:17,title:"Classical Mechanics I",description:"Newtonian mechanics done properly with calculus, in the MIT 8.01 spirit with Kleppner & Kolenkow / Morin depth — F = ma becomes a differential equation, and energy, momentum, rotation, and orbits follow from it.",phase:4,chapters:[{id:"kinematics-via-calculus",title:"Kinematics via Calculus",subtitle:"Position, velocity, and acceleration as derivatives — and your first real ODE",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Everything you learned about motion gets rebuilt on calculus: velocity is the derivative of position, acceleration the derivative of velocity, and motion is recovered from acceleration by integration. The payoff comes immediately — air drag gives you your first genuine differential equation, and terminal velocity falls out of it. This is the moment the physics you know becomes the physics universities teach.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Position, velocity, acceleration as derivatives</li>\n  <li>Motion from integrals</li>\n  <li>Drag & terminal velocity (your first real ODE)</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"newtons-laws-as-differential-equations",title:"Newton's Laws as Differential Equations",subtitle:"Solving F = ma as an equation of motion, with a first look at oscillators and numerics",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>F = ma is not a formula to plug into — it is a differential equation whose solution is the entire future of a system. This chapter teaches you to set up and solve equations of motion, previews the harmonic oscillator (the most important system in physics), and introduces numerical solution, the technique that handles everything analytic methods cannot. This way of thinking carries you all the way to Lagrangian mechanics and beyond.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Solving F = ma</li>\n  <li>The oscillator preview</li>\n  <li>Numerical solutions intro</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"momentum-systems-of-particles",title:"Momentum & Systems of Particles",subtitle:"Centre of mass, rockets, and two-dimensional collisions",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Real objects are systems of many particles, and the centre-of-mass concept is what lets Newton\'s laws apply to them as if they were points. This chapter handles systems whose mass changes — the rocket equation is the classic — and extends collision analysis to two dimensions, where conservation of momentum becomes a genuinely vectorial statement.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Centre of mass</li>\n  <li>Variable-mass systems (rockets)</li>\n  <li>Collisions in 2D</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"energy-methods",title:"Energy Methods",subtitle:"Work–energy via integrals, F = −dU/dx, and reading physics from energy diagrams",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>With calculus, energy stops being a bookkeeping trick and becomes a predictive method: force is the negative slope of potential energy, so a single U(x) curve tells you where a system can go, where it sits in equilibrium, and whether that equilibrium is stable. Energy-diagram reasoning developed here is the same reasoning you will use for molecular bonds, planetary orbits, and quantum wells.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Work–energy via integrals</li>\n  <li>Potential energy & force (F = −dU/dx)</li>\n  <li>Potential wells & stability</li>\n  <li>Energy diagrams</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"angular-momentum-rigid-bodies",title:"Angular Momentum & Rigid Bodies",subtitle:"Rotational dynamics with real integrals, gyroscopes, and precession",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Rotation gets the full calculus treatment: moments of inertia computed by integration rather than looked up in tables, and angular momentum as a conserved vector quantity with sometimes startling consequences. The gyroscope — which seems to defy gravity by precessing instead of falling — is the showcase, and the rotational machinery built here returns in rigid-body motion, atomic physics, and quantum spin.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Rotational dynamics properly</li>\n  <li>Moment of inertia by integration</li>\n  <li>Gyroscopes & precession</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"oscillations-in-depth",title:"Oscillations in Depth",subtitle:"SHM as an ODE, damping, driving, resonance, and the first coupled oscillators",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The harmonic oscillator is the most important system in physics — almost everything, near equilibrium, is one. This chapter solves it properly as a differential equation, then adds damping and driving to get resonance quantitatively, and closes with coupled oscillators, the doorway to the waves course. The mathematics you build here reappears in AC circuits, quantum mechanics, and quantum field theory.</p>\n<h3>Topics</h3>\n<ul>\n  <li>SHM as an ODE</li>\n  <li>Damped & driven oscillations</li>\n  <li>Resonance quantitatively</li>\n  <li>Coupled oscillators intro</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"central-forces-orbits",title:"Central Forces & Orbits",subtitle:"Effective potential, the orbit equation, and Kepler's laws derived from first principles",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>This is one of the great triumphs of physics: starting from Newton's law of gravitation and conservation laws, you derive Kepler's laws — the actual shapes of planetary orbits — with pencil and paper. The effective-potential technique that makes it possible is a completely general tool, and orbital transfers connect the theory directly to how real spacecraft navigate the solar system.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Effective potential</li>\n  <li>The orbit equation</li>\n  <li>Kepler's laws derived</li>\n  <li>Orbital transfers</li>\n</ul>\n<div class=\"key-concept\">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>"}],quiz:[]},{id:"noninertial-frames",title:"Noninertial Frames",subtitle:"Pseudo-forces, rotating frames, the Coriolis force, and tides",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Newton\'s laws hold in inertial frames — but we live on a rotating planet, so pseudo-forces like the centrifugal and Coriolis forces are part of everyday physics, steering hurricanes and ocean currents. This chapter teaches you to work in accelerating and rotating frames confidently, explains the tides properly, and plants a seed: the idea that "fictitious" forces reflect your frame of reference is the very intuition Einstein pushed all the way to general relativity.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Pseudo-forces</li>\n  <li>Rotating frames</li>\n  <li>The Coriolis force</li>\n  <li>Tides</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]}]},{id:"multivariable-vector-calculus",number:18,title:"Multivariable & Vector Calculus",description:"Calculus in three dimensions at MIT 18.02-level, with the div-grad-curl intuition of Schey's classic — the exact toolkit you need in hand before electromagnetism, because Gauss and Stokes ARE Maxwell's equations.",phase:4,chapters:[{id:"functions-of-several-variables",title:"Functions of Several Variables",subtitle:"Partial derivatives, the gradient, and the multivariable chain rule",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Physical fields — temperature in a room, potential in space — depend on several variables at once, and this chapter extends calculus to handle them. The star is the gradient ∇f, the vector that points uphill and encodes how a field changes in every direction at once. You will meet it again almost immediately: the electric field is the (negative) gradient of the potential.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Partial derivatives</li>\n  <li>The gradient</li>\n  <li>Chain rule</li>\n  <li>Differentials</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"optimization-lagrange-multipliers",title:"Optimization & Lagrange Multipliers",subtitle:"Critical points and constrained optimization — a technique statistical mechanics will need again",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Finding extrema in several variables is a fundamental skill, and the method of Lagrange multipliers — optimizing under a constraint — is one of the most elegant tricks in mathematics. Learn it well now: it is exactly how statistical mechanics derives the Boltzmann distribution, by maximizing entropy subject to fixed energy.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Critical points</li>\n  <li>Constrained optimization (needed again in stat mech)</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"multiple-integrals",title:"Multiple Integrals",subtitle:"Double and triple integrals, Jacobians, and the coordinate systems physics lives in",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>To find the total charge in a volume or the mass of a solid body, you integrate over regions of space — and choosing the right coordinate system makes the difference between a nightmare and a three-line calculation. Cylindrical and spherical coordinates, with the Jacobian to convert between systems, are the working currency of every field calculation in electromagnetism and quantum mechanics.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Double & triple integrals</li>\n  <li>Jacobians</li>\n  <li>Cylindrical & spherical coordinates</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"vector-fields",title:"Vector Fields",subtitle:"Line integrals, conservative fields, and flux through surfaces",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Vector fields — an arrow at every point in space — are how physics describes forces, flows, and electromagnetic fields. This chapter teaches the two great ways to integrate them: along curves (work) and through surfaces (flux). The idea that some fields are conservative, with a potential function behind them, explains why potential energy exists at all — and flux is the concept at the heart of Gauss\'s law.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Line integrals</li>\n  <li>Conservative fields & potentials</li>\n  <li>Surface integrals & flux</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"the-big-theorems",title:"The Big Theorems",subtitle:"Green, Stokes, and divergence — the Maxwell-ready toolkit of div, grad, and curl",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>The three great theorems of vector calculus relate what happens inside a region to what happens on its boundary — and they are not merely tools for electromagnetism, they essentially <em>are</em> electromagnetism: Maxwell's equations in integral and differential form are connected by exactly these theorems. Build genuine intuition for divergence (sources) and curl (circulation) here, and Maxwell's equations in the next two subjects will read like sentences instead of hieroglyphics.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Green's, Stokes', and the divergence theorem</li>\n  <li>Div/grad/curl intuition — the Maxwell-ready toolkit</li>\n</ul>\n<div class=\"key-concept\">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>"}],quiz:[]}]},{id:"electromagnetism-1",number:19,title:"Electromagnetism I",description:"Calculus-based electricity and magnetism from MIT 8.02 up to Purcell & Morin level — from Gauss's law to the full set of Maxwell's equations and the stunning conclusion that light is an electromagnetic wave.",phase:4,chapters:[{id:"electrostatics-with-calculus",title:"Electrostatics with Calculus",subtitle:"From Coulomb's law to continuous charge distributions and the power of Gauss's law",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Armed with integrals, you can now compute the field of any charge distribution — rings, disks, planes, spheres — not just point charges. Then Gauss's law arrives and shows that symmetry can replace pages of integration with a single line: this is the first of Maxwell's equations, and your vector-calculus investment starts paying dividends immediately.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Coulomb → fields of continuous charge distributions</li>\n  <li>Gauss's law & its applications</li>\n</ul>\n<div class=\"key-concept\">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>"}],quiz:[]},{id:"potential-theory",title:"Potential Theory",subtitle:"Moving between field and potential, energy of charge configurations, and conductors",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The scalar potential V is often far easier to work with than the vector field E — and the gradient connects them in both directions. This chapter builds fluency in switching representations, computes the energy stored in arrangements of charge, and explains the special behaviour of conductors, where charge rearranges itself to make the interior field vanish.</p>\n<h3>Topics</h3>\n<ul>\n  <li>V from E and E from V</li>\n  <li>Energy of charge configurations</li>\n  <li>Conductors</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"capacitors-dielectrics",title:"Capacitors & Dielectrics",subtitle:"Computing capacitance, energy stored in fields, and what dielectrics do microscopically",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Capacitors are where field theory meets hardware — and the deeper lesson of this chapter is that the energy is stored not in the charges but in the field itself, an idea that becomes central to all of physics. You will calculate capacitance from geometry and understand microscopically how a dielectric\'s polarized molecules boost it.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Capacitance calculations</li>\n  <li>Energy stored in fields</li>\n  <li>Dielectrics microscopically</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"current-dc-circuits",title:"Current & DC Circuits",subtitle:"Current density, the microscopic view of Ohm's law, and RC circuits as differential equations",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Ohm's law gets its microscopic explanation — electrons drifting through a lattice under an applied field — turning V = IR from an empirical rule into derived physics. Then RC circuits become your differential equations in action: charging and discharging follow exponentials you can now predict, not just observe.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Current density</li>\n  <li>Microscopic Ohm's law</li>\n  <li>RC circuits as ODEs</li>\n</ul>\n<div class=\"key-concept\">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>"}],quiz:[]},{id:"magnetostatics",title:"Magnetostatics",subtitle:"Biot–Savart, Amp\xe8re's law, and the fields of steady currents",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Steady currents create magnetic fields, and this chapter gives you two ways to compute them: Biot–Savart for brute-force integration and Amp\xe8re's law for elegant symmetry arguments — the magnetic mirror image of Coulomb versus Gauss. Magnetic dipoles introduced here are the key to understanding magnetism in matter, from compass needles to MRI machines.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Biot–Savart</li>\n  <li>Amp\xe8re's law</li>\n  <li>Magnetic dipoles</li>\n  <li>Magnetism in matter intro</li>\n</ul>\n<div class=\"key-concept\">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>"}],quiz:[]},{id:"induction-inductance",title:"Induction & Inductance",subtitle:"Faraday's law properly, inductors, and LR/LC/RLC circuits as differential equations",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Faraday's law — changing magnetic flux creates electric fields — is the principle behind every generator and transformer on Earth, and here it gets its full integral-calculus treatment. LC and RLC circuits then reveal something beautiful: the equations are <em>identical</em> to the mechanical oscillators of Classical Mechanics I, with charge sloshing instead of mass — the same mathematics describing wholly different physics.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Faraday's law in integral form</li>\n  <li>Inductors</li>\n  <li>LR, LC, RLC circuits as ODEs</li>\n  <li>Energy in magnetic fields</li>\n</ul>\n<div class=\"key-concept\">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>"}],quiz:[]},{id:"maxwells-equations-light",title:"Maxwell's Equations & Light",subtitle:"The complete set of equations, the wave solution, and the discovery that light is electromagnetic",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Maxwell noticed that Amp\xe8re\'s law was incomplete, added the displacement current, and the closed set of four equations then predicted waves travelling at exactly the measured speed of light — the greatest unification in the history of physics. In this capstone chapter you follow that derivation yourself and meet the Poynting vector, which tracks where electromagnetic energy flows. Everything from radio to gamma rays falls out of four lines of vector calculus.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Displacement current</li>\n  <li>The complete set</li>\n  <li>The wave solution</li>\n  <li>The EM spectrum revisited</li>\n  <li>Energy flow & Poynting intro</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]}]},{id:"waves-vibrations-optics",number:20,title:"Waves, Vibrations & Optics",description:"The MIT 8.03-style hinge course (French's Vibrations and Waves) — normal modes, the wave equation, and Fourier thinking, the prerequisite that unlocks both quantum mechanics and statistical physics.",phase:4,chapters:[{id:"coupled-oscillators-normal-modes",title:"Coupled Oscillators & Normal Modes",subtitle:"Where matrices meet physics — beats, normal modes, and the road to the continuum",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Couple two pendulums with a spring and something remarkable happens: the motion decomposes into special collective patterns — normal modes — each oscillating at its own frequency. This is the moment matrices meet physics, and it is the conceptual template for everything from molecular vibrations to quantum states. Push the number of oscillators toward infinity and you arrive at waves, the subject of the rest of this course.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Matrices meet physics</li>\n  <li>Beats</li>\n  <li>The many-body limit</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"the-wave-equation",title:"The Wave Equation",subtitle:"Deriving the wave equation on a string, superposition, and standing waves done formally",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Apply F = ma to a tiny piece of stretched string and out comes the wave equation — one of the most important partial differential equations in physics, governing sound, light, and (in modified form) quantum wavefunctions. This chapter derives it honestly, then explores superposition and how boundary conditions select the discrete standing-wave patterns: your first real taste of how confinement leads to quantization.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Derivation on a string</li>\n  <li>Superposition</li>\n  <li>Boundary conditions</li>\n  <li>Standing waves formally</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"fourier-analysis-intro",title:"Fourier Analysis Intro",subtitle:"Fourier series, spectra, wave packets — and a classical preview of the uncertainty principle",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Fourier's insight — any wave can be built from sines and cosines — is one of the most powerful ideas in science, underpinning music, signal processing, and quantum theory alike. Here you learn to decompose signals into spectra and build wave packets, discovering along the way a purely classical fact: a short pulse needs many frequencies. That trade-off, ported to matter waves, <em>is</em> Heisenberg's uncertainty principle.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Fourier series</li>\n  <li>Spectra</li>\n  <li>Wave packets</li>\n  <li>The uncertainty relation previewed classically</li>\n</ul>\n<div class=\"key-concept\">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>"}],quiz:[]},{id:"em-waves-polarization",title:"EM Waves & Polarization",subtitle:"Plane waves, polarization states, and what happens when light meets a boundary",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The electromagnetic waves predicted at the end of Electromagnetism I now get explored as waves: plane-wave solutions, the polarization states that sunglasses and LCD screens exploit, and reflection at boundaries in the spirit of Fresnel. Polarization is also quietly profound — its two-state structure is the classical ancestor of the qubit.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Plane waves</li>\n  <li>Polarization states</li>\n  <li>Reflection at boundaries (Fresnel-lite)</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"interference-diffraction-quantitative",title:"Interference & Diffraction Quantitative",subtitle:"Phasors, gratings, single-slit patterns, and the fundamental limits of resolution",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Interference and diffraction get the full quantitative treatment using phasors — a graphical technique that turns messy sums of waves into simple geometry. You will predict exact fringe patterns for N slits and gratings, understand why every optical instrument has a fundamental resolution limit, and build the wave-superposition intuition that quantum mechanics will soon demand of you.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Phasors</li>\n  <li>N-slit & gratings</li>\n  <li>Single-slit</li>\n  <li>Resolution limits</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"geometrical-optics-from-waves",title:"Geometrical Optics from Waves",subtitle:"Why rays work at all — the eikonal idea, matrix optics, instruments, and lasers",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Ray optics is not a separate theory — it is the short-wavelength limit of wave optics, and the eikonal idea makes that connection precise. This chapter revisits lenses and instruments with that deeper understanding, introduces the elegant matrix method for tracing rays through optical systems, and ends with the laser: wave physics, atomic physics, and engineering meeting in one device.</p>\n<h3>Topics</h3>\n<ul>\n  <li>The eikonal idea</li>\n  <li>Matrix optics taste</li>\n  <li>Instruments revisited</li>\n  <li>Lasers intro</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]}]},{id:"special-relativity",number:21,title:"Special Relativity",description:"A full MIT 8.033-style course in the physics of spacetime (Morin; Taylor & Wheeler) — from the two postulates to four-vectors, relativistic collisions, and the revelation that magnetism is relativity in disguise.",phase:4,chapters:[{id:"postulates-the-lorentz-transformation",title:"Postulates & the Lorentz Transformation",subtitle:"Deriving the Lorentz transformation and learning to read spacetime diagrams",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Two innocent-sounding postulates — physics looks the same in every inertial frame, and light\'s speed is the same for everyone — force a complete rebuild of space and time. This chapter derives the Lorentz transformation from them and introduces spacetime diagrams and the invariant interval, the tools that make relativity visual and computable rather than paradoxical and mysterious.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Derivation</li>\n  <li>Spacetime diagrams</li>\n  <li>The invariant interval</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"relativistic-kinematics",title:"Relativistic Kinematics",subtitle:"Velocity addition, the relativistic Doppler effect, and the classic paradoxes laid to rest",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Velocities do not simply add near light speed, and the Doppler effect picks up a relativistic twist that astronomers use daily to read the expansion of the universe. The heart of this chapter is confronting the famous "paradoxes" — the twins, the pole in the barn — and resolving each one cleanly, which is the true test that you understand relativity rather than merely knowing its formulas.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Velocity addition</li>\n  <li>Relativistic Doppler</li>\n  <li>The classic paradoxes resolved</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"four-vectors-dynamics",title:"Four-Vectors & Dynamics",subtitle:"4-momentum, E\xb2 = (pc)\xb2 + (mc\xb2)\xb2, and the physics of particle collisions",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Four-vectors unify energy and momentum into a single spacetime object, and suddenly relativistic dynamics becomes as systematic as Newtonian mechanics ever was. The master relation E\xb2 = (pc)\xb2 + (mc\xb2)\xb2 governs everything from nuclear binding energies to collider physics, and the collision techniques you learn here are exactly the ones particle physicists use to discover new particles.</p>\n<h3>Topics</h3>\n<ul>\n  <li>4-momentum</li>\n  <li>E\xb2 = (pc)\xb2 + (mc\xb2)\xb2</li>\n  <li>Collisions & particle creation</li>\n  <li>Mass–energy</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"relativity-electromagnetism",title:"Relativity & Electromagnetism",subtitle:"How E and B mix between frames — magnetism unmasked as a relativistic effect",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Here is one of the most beautiful results in physics: electric and magnetic fields are not separate things but two faces of one entity, mixing into each other when you change reference frames. The magnetic force from a current-carrying wire can be derived as a purely electric effect seen from a moving frame — magnetism is relativity you can demonstrate with a battery and a compass. This insight sets up the covariant electrodynamics of Phase 5.</p>\n<h3>Topics</h3>\n<ul>\n  <li>How E and B mix between frames</li>\n  <li>Magnetism as a relativistic effect</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"toward-general-relativity",title:"Toward General Relativity",subtitle:"The equivalence principle, gravitational time dilation, and why GPS needs Einstein",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Einstein called it his happiest thought: a person in free fall feels no gravity, which means gravity and acceleration are locally indistinguishable. From that equivalence principle alone you can derive gravitational time dilation — clocks tick slower deeper in a gravity well — an effect GPS satellites must correct for every second to keep your position accurate. This chapter is the bridge to the full theory of curved spacetime waiting in Phase 6.</p>\n<h3>Topics</h3>\n<ul>\n  <li>The equivalence principle</li>\n  <li>Gravitational time dilation</li>\n  <li>GPS</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]}]},{id:"differential-equations-linear-algebra",number:22,title:"Differential Equations & Linear Algebra",description:"The MIT 18.03 + 18.06 (Strang) pair in one subject — second-order ODEs, eigenvalue problems, and inner-product spaces, timed so that linear algebra lands immediately before the quantum formalism that is built on it.",phase:4,chapters:[{id:"second-order-odes",title:"Second-Order ODEs",subtitle:"Constant-coefficient linear equations and the mathematics behind resonance",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Second-order linear ODEs are the equations of oscillation, and here you learn to solve them completely and systematically. Every damped, driven oscillator you met in mechanics and every RLC circuit from electromagnetism is a special case — and resonance, treated mathematically at last, explains precisely when and why a driven system\'s response blows up.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Linear ODEs with constant coefficients</li>\n  <li>Oscillator applications</li>\n  <li>Resonance, mathematically</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"systems-of-odes-phase-portraits",title:"Systems of ODEs & Phase Portraits",subtitle:"Coupled equations, eigen-analysis, and reading stability from phase portraits",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Real systems have many interacting variables, so their equations of motion couple together — and eigenvalues are what untangle them. This chapter teaches you to analyze systems of ODEs, draw phase portraits, and classify equilibria by stability at a glance. These are the exact tools behind normal modes, chaos theory in Classical Mechanics II, and dynamical systems everywhere from ecology to engineering.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Coupled systems</li>\n  <li>Eigen-analysis of systems</li>\n  <li>Stability</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"laplace-transforms-greens-function-idea",title:"Laplace Transforms & Green's-Function Idea",subtitle:"Transform methods and the impulse-response way of thinking",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Transform methods convert differential equations into algebra: solve, transform back, done. Beyond the technique, this chapter plants a deep idea — characterize a system by its response to a single sharp kick (the impulse response), and you can build its response to anything by superposition. That Green\'s-function way of thinking recurs in electrodynamics, quantum mechanics, and field theory.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Transform methods</li>\n  <li>Impulse response</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"linear-algebra-core",title:"Linear Algebra Core",subtitle:"Vector spaces, bases, and matrices as transformations",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Linear algebra is the language quantum mechanics is written in, and this chapter builds it properly: vector spaces as abstract structures, bases as coordinate choices, and matrices as transformations rather than grids of numbers. When quantum mechanics declares that "states are vectors," everything you learn here is what makes that sentence meaningful.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Vector spaces</li>\n  <li>Linear independence & bases</li>\n  <li>Matrices as transformations</li>\n  <li>Determinants</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"eigenvalues-diagonalization",title:"Eigenvalues & Diagonalization",subtitle:"Eigenproblems, Hermitian matrices, and normal modes seen through new eyes",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Eigenvectors are the directions a transformation merely stretches, and finding them — diagonalization — is the single most useful computation in applied mathematics. Symmetric and Hermitian matrices, with their real eigenvalues and orthogonal eigenvectors, are precisely the mathematical objects quantum mechanics will use to represent observables; the normal modes you found by physical intuition in the waves course reappear here as a clean eigenproblem.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Eigenproblems</li>\n  <li>Symmetric/Hermitian matrices</li>\n  <li>Quadratic forms</li>\n  <li>Normal modes revisited</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"inner-product-spaces",title:"Inner-Product Spaces",subtitle:"Orthogonality, projections, and function spaces — the quantum-ready chapter",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The dot product generalizes into the inner product, bringing geometry — lengths, angles, orthogonality — to abstract vector spaces, including spaces whose "vectors" are functions. The stunning payoff: Fourier series is just projection onto an orthogonal basis of sines and cosines. This is the quantum-ready chapter — wavefunctions live in exactly such a space, and expansion in eigenstates is exactly this projection.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Orthogonality</li>\n  <li>Projections</li>\n  <li>Gram–Schmidt</li>\n  <li>Function spaces & Fourier as linear algebra — the quantum-ready chapter</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]}]},{id:"mathematical-methods",number:23,title:"Mathematical Methods for Physicists",description:"The Boas-level math-methods spine (with Riley/Hobson/Bence for depth) — complex analysis, variational calculus, PDEs, transforms, tensors, probability, and a first taste of group theory: every tool the theoretical core four will demand.",phase:5,chapters:[{id:"complex-analysis",title:"Complex Analysis",subtitle:"Analytic functions, contour integration, and residues — magic that computes real integrals",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Functions of a complex variable are astonishingly well-behaved: differentiable once means differentiable forever, and integrals around closed contours are determined entirely by a few special points inside. The residue theorem turns impossible-looking real integrals into short exercises, and complex methods run beneath the surface of scattering theory, Green\'s functions, and quantum field theory.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Analytic functions</li>\n  <li>Contour integration</li>\n  <li>Residues</li>\n  <li>Physical applications</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"calculus-of-variations",title:"Calculus of Variations",subtitle:"Functionals and the Euler–Lagrange equation — the door to Lagrangian mechanics",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Instead of asking "where is this function smallest?", the calculus of variations asks "which entire path makes this quantity smallest?" — and the Euler–Lagrange equation answers it. The brachistochrone (fastest descent curve) is the classic showcase, but the real reason this chapter sits here is timing: it is the door to Lagrangian mechanics, where all of classical physics is rewritten as a single optimization principle.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Functionals</li>\n  <li>The Euler–Lagrange equation</li>\n  <li>Brachistochrone</li>\n  <li>Constraints — the door to Lagrangian mechanics</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"partial-differential-equations",title:"Partial Differential Equations",subtitle:"Laplace, heat, and wave equations solved by separation of variables in every coordinate system",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The fundamental equations of physics — Laplace, heat, wave, Schr\xf6dinger — are partial differential equations, and separation of variables is the master technique for solving them. Practicing it in Cartesian, cylindrical, and spherical coordinates prepares you for the two flagship calculations ahead: boundary-value problems in electrodynamics and the hydrogen atom in quantum mechanics.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Laplace, heat, and wave equations</li>\n  <li>Separation of variables in Cartesian, cylindrical, spherical coordinates</li>\n  <li>Boundary-value problems</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"special-functions",title:"Special Functions",subtitle:"Legendre, Bessel, Hermite, spherical harmonics, and the unifying Sturm–Liouville theory",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Separate variables in a round or spherical problem and special functions appear automatically: Legendre polynomials, Bessel functions, spherical harmonics. Far from being a zoo of formulas, they are unified by Sturm–Liouville theory — each family is an orthogonal basis, exactly like sines and cosines. Spherical harmonics in particular will label the shapes of atomic orbitals; Hermite polynomials will build the quantum oscillator.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Legendre & Bessel functions</li>\n  <li>Hermite polynomials</li>\n  <li>Spherical harmonics</li>\n  <li>Sturm–Liouville theory & orthogonality</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"fourier-integral-transforms",title:"Fourier & Integral Transforms",subtitle:"Fourier transforms, convolution, the Dirac delta, and Green's functions",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>The Fourier transform extends Fourier series to non-periodic functions, translating between position and frequency descriptions of the same physics — the mathematical backbone of the quantum position–momentum relationship. Alongside it you meet the Dirac delta (the idealized point impulse), convolution, and Green's functions in full: solve for a point source once, superpose, and you have solved for every source.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Fourier transforms</li>\n  <li>Convolution</li>\n  <li>The Dirac delta</li>\n  <li>Green's functions</li>\n</ul>\n<div class=\"key-concept\">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>"}],quiz:[]},{id:"tensors-index-notation",title:"Tensors & Index Notation",subtitle:"Einstein summation, Kronecker delta, Levi-Civita, and the inertia tensor",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Index notation with the Einstein summation convention compresses pages of vector algebra into single lines — and the Kronecker delta and Levi-Civita symbols make identities like the double cross product almost mechanical. Tensors themselves, introduced here through the concrete inertia tensor of a rigid body, are the objects general relativity is written in; this chapter is where that language training begins.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Einstein summation</li>\n  <li>Kronecker delta & Levi-Civita</li>\n  <li>Cartesian tensors</li>\n  <li>The inertia tensor</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"probability-for-physics",title:"Probability for Physics",subtitle:"Distributions, the central limit theorem, random walks, and the stat-mech toolkit",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Statistical mechanics is applied probability, and this chapter assembles its toolkit: distributions, the central limit theorem (why the Gaussian appears everywhere), random walks, and the two workhorses of every partition-function calculation — Stirling's formula and Gaussian integrals. Entropy, temperature, and the arrow of time will all be built from the combinatorics you master here.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Distributions</li>\n  <li>Central limit theorem</li>\n  <li>Random walks</li>\n  <li>Stirling's formula & Gaussian integrals — the stat-mech toolkit</li>\n</ul>\n<div class=\"key-concept\">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>"}],quiz:[]},{id:"group-theory-primer",title:"Group Theory Primer",subtitle:"Symmetry groups, representations, and a first look at SO(3) and SU(2)",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Group theory is the mathematics of symmetry, and modern physics is organized around it: conservation laws, particle classifications, and selection rules all flow from symmetry groups and their representations. This primer introduces the key ideas gently, previewing the rotation groups SO(3) and SU(2) whose strange double-cover relationship is the mathematical origin of spin-\xbd — and whose bigger cousins classify the particles of the Standard Model.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Symmetry groups</li>\n  <li>The representation idea</li>\n  <li>Rotations, SO(3) and SU(2) preview</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]}]},{id:"classical-mechanics-2",number:24,title:"Classical Mechanics II — Lagrangian & Hamiltonian",description:"Mechanics reborn from a single principle — least action. Lagrangians, Noether's theorem, rigid bodies, Hamiltonian phase space, and chaos, at the Taylor/Landau level.",phase:5,chapters:[{id:"principle-of-least-action",title:"The Principle of Least Action",subtitle:"All of mechanics from one variational statement",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Nature extremizes action — and from that single statement all of Newtonian mechanics follows. Armed with the calculus of variations from Subject 23, you\'ll reformulate mechanics in generalized coordinates where constraints handle themselves.</p>\n<h3>Topics</h3>\n<ul>\n  <li>The variational formulation</li>\n  <li>Generalized coordinates</li>\n  <li>Constraints</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"lagrangian-mechanics",title:"Lagrangian Mechanics",subtitle:"Euler–Lagrange in practice — problems Newton's laws make painful",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Write L = T − V, turn the crank, and equations of motion fall out — no force diagrams, no constraint forces. Cyclic coordinates hand you conservation laws for free, and effective potentials tame two-dimensional problems.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Euler–Lagrange in practice</li>\n  <li>Cyclic coordinates</li>\n  <li>Effective-potential problems</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"symmetry-and-conservation",title:"Symmetry & Conservation",subtitle:"Noether's theorem — why conservation laws exist at all",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Emmy Noether proved the deepest theorem in classical physics: every continuous symmetry implies a conservation law. Time symmetry gives energy, space symmetry gives momentum, rotational symmetry gives angular momentum. This idea organizes all of modern physics, from particle physics to cosmology.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Noether\'s theorem</li>\n  <li>The deep meaning of conservation laws</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"central-forces-revisited",title:"Two-Body & Central Forces Revisited",subtitle:"Reduced mass, orbits, and the language of scattering",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The two-body problem collapses to one body with a reduced mass, and orbits follow elegantly. Then the setup inverts: instead of bound orbits, particles fly past and scatter — introducing the cross sections that nuclear and particle physics (Subject 31) measure daily.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Reduced mass</li>\n  <li>Scattering</li>\n  <li>Cross sections</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"rigid-body-motion",title:"Rigid-Body Motion",subtitle:"Euler angles, the inertia tensor, and why tops don't fall",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Real rotation is gloriously three-dimensional: the inertia tensor (your Subject 23 tensors at work), Euler's angles and equations, and the gyroscopic precession that keeps a spinning top upright and torque-free satellites tumbling predictably.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Euler angles</li>\n  <li>The inertia tensor</li>\n  <li>Euler's equations</li>\n  <li>Tops &amp; precession</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]},{id:"small-oscillations",title:"Small Oscillations",subtitle:"Normal modes as an eigenvalue problem — done right",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Every stable system oscillates harmonically near equilibrium. The normal-modes formalism diagonalizes the physics — literally: eigenvalues give frequencies, eigenvectors give mode shapes, and molecular vibration spectra follow.</p>\n<h3>Topics</h3>\n<ul>\n  <li>The normal-modes formalism</li>\n  <li>Molecular vibrations</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"hamiltonian-mechanics",title:"Hamiltonian Mechanics",subtitle:"Phase space, Poisson brackets, and the doorway to quantum mechanics",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>The Legendre transform trades velocities for momenta and reveals mechanics as flow in phase space. Poisson brackets, Liouville's theorem, and canonical transformations aren't just elegant — they are the exact classical skeleton onto which quantum mechanics grafts (Poisson brackets become commutators).</p>\n<h3>Topics</h3>\n<ul>\n  <li>Legendre transform</li>\n  <li>Phase space</li>\n  <li>Poisson brackets</li>\n  <li>Liouville's theorem</li>\n  <li>Canonical transformations</li>\n  <li>Hamilton–Jacobi glimpse</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]},{id:"nonlinear-dynamics-chaos",title:"Nonlinear Dynamics & Chaos",subtitle:"Deterministic yet unpredictable — sensitivity and strange attractors",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Determinism does not imply predictability: tiny differences in initial conditions grow exponentially. The driven pendulum from Phase 4 returns as a gateway to attractors, bifurcations, and the modern science of chaos.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Sensitivity to initial conditions</li>\n  <li>Attractors</li>\n  <li>The driven pendulum revisited</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"classical-to-quantum-continuum",title:"From Classical to Quantum & Continuum",subtitle:"Action-angle variables, adiabatic invariants, and continuous media",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Two bridges out of particle mechanics: action-angle variables and adiabatic invariants (the historical route to quantization), and a taste of continuum mechanics — fluids and elasticity — where the Lagrangian idea extends to fields.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Action-angle variables &amp; adiabatic invariants</li>\n  <li>Fluids &amp; elasticity taste</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]}]},{id:"electrodynamics",number:25,title:"Electrodynamics",description:"The full Griffiths-level theory of the electromagnetic field: boundary-value problems, fields in matter, complete Maxwell equations, radiation, and the relativistic formulation.",phase:5,chapters:[{id:"electrostatics-redone",title:"Electrostatics Redone",subtitle:"Boundary-value problems — images, separation of variables, multipoles",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Electrostatics at full mathematical strength: Laplace\'s equation with your Subject 23 PDE toolkit, the sly method of images, separation of variables in spherical coordinates (hello, Legendre polynomials), and the multipole expansion that organizes any charge distribution.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Vector calculus at full strength</li>\n  <li>Boundary-value problems</li>\n  <li>Method of images</li>\n  <li>Separation of variables</li>\n  <li>Multipole expansion</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"fields-in-matter",title:"Fields in Matter",subtitle:"Polarization, magnetization, and the auxiliary fields D and H",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Real materials respond to fields: dielectrics polarize, magnetic materials magnetize. The auxiliary fields D and H keep the bookkeeping honest and explain everything from capacitor dielectrics to why iron is special.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Polarization &amp; the D field</li>\n  <li>Dielectrics</li>\n  <li>Magnetization &amp; the H field</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"magnetostatics-deepened",title:"Magnetostatics Deepened",subtitle:"The vector potential and magnetic multipoles",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The vector potential A steps out of the shadows — a calculational device here, but destined to become physically real in quantum mechanics (the Aharonov–Bohm effect of Subject 27) and fundamental in QFT.</p>\n<h3>Topics</h3>\n<ul>\n  <li>The vector potential</li>\n  <li>Magnetic multipoles</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"maxwell-equations",title:"Electrodynamics & Maxwell's Equations",subtitle:"The complete field equations, their conservation laws, and gauge freedom",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Displacement current completes Maxwell's equations, and the theory's inner accounting emerges: field energy, field momentum, the Poynting vector, and the stress tensor. Gauge freedom — seemingly a technicality — foreshadows the organizing principle of the Standard Model.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Maxwell's equations complete</li>\n  <li>Gauge freedom</li>\n  <li>Field energy &amp; momentum</li>\n  <li>Poynting's theorem</li>\n  <li>The stress tensor</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]},{id:"em-waves",title:"EM Waves",subtitle:"Light in vacuum, matter, and conductors — dispersion to waveguides",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Maxwell\'s equations sing: waves in vacuum, refraction and dispersion in media, attenuation in conductors, the Fresnel coefficients governing reflection, and the guided waves inside waveguides and optical fibers.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Waves in vacuum, media, and conductors</li>\n  <li>Dispersion</li>\n  <li>Waveguides</li>\n  <li>Reflection &amp; transmission (Fresnel)</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"potentials-and-radiation",title:"Potentials & Radiation",subtitle:"Retarded potentials and how accelerating charges shed light",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Causality enters through retarded potentials — fields today reflect charges as they were. Accelerating charges radiate: dipole radiation explains antennas and the blue sky, Larmor\'s formula counts the power, and synchrotron light powers modern materials science.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Retarded potentials</li>\n  <li>Dipole radiation</li>\n  <li>Antennas</li>\n  <li>The Larmor formula</li>\n  <li>Synchrotron &amp; bremsstrahlung glimpse</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"relativistic-electrodynamics",title:"Relativistic Electrodynamics",subtitle:"E and B unified in the field tensor",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The punchline of classical physics: electricity and magnetism are one field seen from different frames. The field tensor F^μν makes Maxwell\'s equations manifestly covariant — two tensor equations containing everything — and the fields of fast-moving charges follow by transformation.</p>\n<h3>Topics</h3>\n<ul>\n  <li>The field tensor</li>\n  <li>Covariant Maxwell equations</li>\n  <li>Fields of moving charges</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]}]},{id:"quantum-mechanics-1",number:26,title:"Quantum Mechanics I",description:"The Griffiths-level first course: wavefunctions and the Schr\xf6dinger equation, the classic 1D problems, the Dirac formalism, the hydrogen atom, spin, and identical particles.",phase:5,chapters:[{id:"why-quantum",title:"Why Quantum",subtitle:"The experimental failures that forced a new physics",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Before the formalism, the evidence: blackbody radiation, the photoelectric effect, atomic spectra, and electron diffraction each broke classical physics in a specific way. Understanding exactly what failed makes the strange postulates ahead feel inevitable rather than arbitrary.</p>\n<h3>Topics</h3>\n<ul>\n  <li>The failures of classical physics</li>\n  <li>The experiments that forced the theory</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"wavefunction-schrodinger",title:"The Wavefunction & Schr\xf6dinger Equation",subtitle:"ψ, probability, and the equation that runs the microworld",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The state of a particle is a complex-valued wavefunction whose square is a probability density — Born\'s rule. The Schr\xf6dinger equation (a PDE your Subject 23 methods handle) evolves it deterministically. Operators, expectation values, and normalization set up the machinery.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Probability interpretation</li>\n  <li>Normalization</li>\n  <li>Expectation values</li>\n  <li>Operators intro</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"one-dimensional-problems",title:"One-Dimensional Problems",subtitle:"Wells, barriers, tunnelling, and the harmonic oscillator",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The exactly-solvable classics: infinite and finite wells (energy quantization appears!), tunnelling through barriers (how the sun fuses and flash memory writes), the harmonic oscillator solved twice — analytically and with the elegant ladder operators — and wave packets for free particles.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Infinite &amp; finite wells</li>\n  <li>Tunnelling</li>\n  <li>Scattering off steps &amp; barriers</li>\n  <li>The harmonic oscillator (analytic + ladder operators)</li>\n  <li>Free particles &amp; wave packets</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"the-formalism",title:"The Formalism",subtitle:"Hilbert space, Dirac notation, and measurement — quantum mechanics as linear algebra",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The conceptual core: states are vectors in Hilbert space, observables are Hermitian operators, measurement yields eigenvalues — your Subject 22 linear algebra was all preparation for this chapter. The uncertainty principle stops being folklore and becomes a theorem.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Hilbert space</li>\n  <li>Dirac notation</li>\n  <li>Hermitian operators &amp; observables</li>\n  <li>Eigenvalues &amp; eigenstates</li>\n  <li>The uncertainty principle derived</li>\n  <li>Time evolution</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"qm-in-three-dimensions",title:"QM in Three Dimensions",subtitle:"The hydrogen atom — quantum mechanics's greatest exact triumph",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Separation of variables in spherical coordinates (spherical harmonics from Subject 23 return) cracks the hydrogen atom exactly: the quantum numbers n, l, m emerge naturally and the spectrum Bohr guessed is derived. This is the calculation that convinced physics quantum mechanics was true.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Separation in spherical coordinates</li>\n  <li>The hydrogen atom</li>\n  <li>Quantum numbers</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"angular-momentum-and-spin",title:"Angular Momentum & Spin",subtitle:"Ladder algebra and the two-valued mystery of spin-\xbd",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Angular momentum in quantum mechanics comes quantized, and the ladder-operator algebra derives it all from commutators alone. Then spin: an intrinsic angular momentum with no classical analog, revealed by Stern–Gerlach, described by two-component spinors — the qubit of quantum computing.</p>\n<h3>Topics</h3>\n<ul>\n  <li>L operators &amp; ladder algebra</li>\n  <li>Spin-\xbd</li>\n  <li>Stern–Gerlach</li>\n  <li>Addition of angular momenta intro</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"identical-particles",title:"Identical Particles",subtitle:"Bosons, fermions, and why chemistry exists",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Identical quantum particles are radically identical — swapping them changes nothing observable, which splits the world into bosons and fermions. The Pauli exclusion principle follows, and with it the shell structure of atoms: the periodic table, and hence chemistry, explained from symmetry.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Bosons &amp; fermions</li>\n  <li>The Pauli principle</li>\n  <li>The periodic table explained</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]}]},{id:"quantum-mechanics-2",number:27,title:"Quantum Mechanics II",description:"The Shankar/Sakurai-level second pass: symmetries, perturbation theory, scattering, entanglement and Bell's theorem, and Feynman's path integrals.",phase:5,chapters:[{id:"formalism-deepened",title:"Formalism Deepened",subtitle:"Pictures, symmetries, and the generators of transformations",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The formalism matures: Schr\xf6dinger and Heisenberg pictures as two views of the same physics, and the profound identification of momentum as the generator of translations and angular momentum of rotations — Noether\'s theorem reborn in quantum form.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Schr\xf6dinger vs Heisenberg pictures</li>\n  <li>Symmetries &amp; unitary operators</li>\n  <li>Translation &amp; rotation generators</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"time-independent-perturbation",title:"Time-Independent Perturbation Theory",subtitle:"Systematic approximation — fine structure, Zeeman, and Stark",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Almost nothing is exactly solvable; perturbation theory is how quantum mechanics earns its living. Nondegenerate and degenerate machinery, then the payoff: hydrogen\'s fine structure and the Zeeman and Stark effects that split spectral lines in fields.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Nondegenerate &amp; degenerate cases</li>\n  <li>Fine structure</li>\n  <li>Zeeman &amp; Stark effects</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"variational-wkb",title:"Variational & WKB Methods",subtitle:"Bounding ground states and estimating tunnelling",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Two more tools for the intractable: the variational principle (guess a wavefunction, get a rigorous upper bound on the ground-state energy — the workhorse of quantum chemistry) and the WKB approximation for barrier penetration and tunnelling rates.</p>\n<h3>Topics</h3>\n<ul>\n  <li>The approximation toolkit</li>\n  <li>Tunnelling rates</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"time-dependent-perturbations",title:"Time-Dependent Perturbations",subtitle:"Fermi's golden rule — transitions, selection rules, and lasers",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Turn on a time-varying field and states transition: Fermi's golden rule gives the rates, selection rules say which jumps are allowed, and stimulated emission — Einstein's 1917 insight — becomes the working principle of every laser.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Fermi's golden rule</li>\n  <li>Radiative transitions</li>\n  <li>Selection rules</li>\n  <li>How lasers work</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]},{id:"scattering-theory",title:"Scattering Theory",subtitle:"Partial waves and the Born approximation — how we probe matter",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Nearly everything we know about the subatomic world comes from throwing particles at things. Partial-wave analysis and the Born approximation turn detector counts into structure — the theory behind Rutherford\'s nucleus and the LHC alike.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Partial waves</li>\n  <li>The Born approximation</li>\n  <li>Cross sections</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"entanglement-interpretation",title:"Entanglement & Interpretation",subtitle:"EPR, Bell's theorem, decoherence — and quantum information",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>The chapter Einstein started: entangled states, the EPR argument, and Bell's inequalities — which experiment has decisively settled against local realism. Decoherence explains the classical world's emergence, and qubits turn the weirdness into a technology.</p>\n<h3>Topics</h3>\n<ul>\n  <li>EPR</li>\n  <li>Bell inequalities</li>\n  <li>Decoherence</li>\n  <li>The measurement problem</li>\n  <li>Qubits &amp; quantum information taste</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]},{id:"path-integrals-glimpses",title:"Path Integrals & Advanced Glimpses",subtitle:"Feynman's sum over histories, Aharonov–Bohm, and Berry phase",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Feynman's third formulation: the particle takes every path, each weighted by its action — reconnecting quantum mechanics to Subject 24's least-action principle and opening the road to QFT. The Aharonov–Bohm effect and Berry phase reveal geometry hiding in quantum phases.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Feynman's sum over histories</li>\n  <li>Aharonov–Bohm</li>\n  <li>Berry phase glimpse</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]}]},{id:"statistical-mechanics",number:28,title:"Thermodynamics & Statistical Mechanics",description:"The Schroeder-level statistical theory of heat: entropy as counting, partition functions, quantum statistics from electron gases to Bose–Einstein condensates, and phase transitions.",phase:5,chapters:[{id:"first-law-revisited",title:"Energy & the First Law Revisited",subtitle:"Equilibrium, equipartition, and the microscopic ideal gas",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The thermal physics of Phase 3 returns with statistical foundations: what equilibrium really is, the ideal gas from molecular degrees of freedom, and the equipartition theorem that assigns \xbdkT to each — along with its famous failures that only quantum mechanics explains.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Equilibrium</li>\n  <li>The ideal gas microscopically</li>\n  <li>Equipartition</li>\n  <li>Heat &amp; work</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"entropy-second-law",title:"Entropy & the Second Law",subtitle:"S = k log W — entropy as counting, temperature as a definition",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The most profound idea in the subject: entropy simply counts microstates, and the second law is just probability at astronomical odds. Your combinatorics and Stirling\'s formula from Subject 23 derive it, and temperature itself gets defined statistically — 1/T = ∂S/∂E.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Multiplicity &amp; combinatorics</li>\n  <li>Boltzmann entropy</li>\n  <li>Temperature defined statistically</li>\n  <li>The third law</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"engines-free-energy",title:"Engines & Free Energy",subtitle:"Carnot's limit, thermodynamic potentials, and Maxwell relations",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Classical thermodynamics at full power: Carnot\'s absolute efficiency limit, the free energies that determine what happens at constant temperature and pressure, the Maxwell relations (partial-derivative identities doing real work), and the chemical potential that governs phase equilibria.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Carnot properly</li>\n  <li>Thermodynamic potentials</li>\n  <li>Maxwell relations</li>\n  <li>Phase equilibria</li>\n  <li>Chemical potential</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"boltzmann-statistics",title:"Boltzmann Statistics",subtitle:"The partition function — the machine that computes everything",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The canonical ensemble\'s Boltzmann factor e^(−E/kT) and its partition function Z form the central machine of statistical mechanics: differentiate Z correctly and any thermodynamic quantity drops out. Paramagnets, oscillators, and molecular gases put the machine to work.</p>\n<h3>Topics</h3>\n<ul>\n  <li>The canonical ensemble</li>\n  <li>Partition-function machinery</li>\n  <li>Applications (paramagnets, oscillators, molecules)</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"quantum-statistics",title:"Quantum Statistics",subtitle:"Fermi–Dirac, Bose–Einstein, and blackbody radiation derived",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>When particles are identical (Subject 26), statistics change: Fermi–Dirac for fermions explains metals and white-dwarf stability; Bose–Einstein for bosons yields the Planck blackbody law — the formula that started quantum theory — plus Debye\'s solids and Bose–Einstein condensation.</p>\n<h3>Topics</h3>\n<ul>\n  <li>The Gibbs factor</li>\n  <li>Fermi–Dirac &amp; Bose–Einstein</li>\n  <li>The electron gas</li>\n  <li>Blackbody radiation derived</li>\n  <li>Bose–Einstein condensation</li>\n  <li>Debye solids</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"phase-transitions",title:"Phase Transitions & Critical Phenomena",subtitle:"The Ising model, universality, and the renormalization idea",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>How does short-range order produce sudden global change — boiling, magnetization, superconductivity? The Ising model and mean-field theory give the classic answers; universality and the renormalization group reveal why wildly different systems share identical critical behavior.</p>\n<h3>Topics</h3>\n<ul>\n  <li>The Ising model</li>\n  <li>Mean-field theory</li>\n  <li>Universality</li>\n  <li>The renormalization idea</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"transport-fluctuations",title:"Transport & Fluctuations",subtitle:"Random walks, Brownian motion, and fluctuation–dissipation",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Statistical mechanics away from equilibrium: random walks becoming diffusion, Einstein\'s Brownian-motion analysis (which finally proved atoms exist), and the fluctuation–dissipation idea linking spontaneous jiggling to friction.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Random walks &amp; diffusion</li>\n  <li>Brownian motion</li>\n  <li>Fluctuation–dissipation glimpse</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]}]},{id:"computational-physics",number:29,title:"Computational Physics",description:"Physics's third pillar alongside theory and experiment: simulate motion, chaos, quantum wavefunctions, and the Ising model in Python — and analyze data like an experimentalist.",phase:5,chapters:[{id:"tools",title:"Tools",subtitle:"Python, NumPy, and plotting — the working physicist's stack",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The modern physicist\'s laboratory is often a laptop. Set up Python with NumPy for fast arrays, Matplotlib for publication-quality plots, and notebooks for reproducible explorations — the stack used from undergraduate labs to LIGO.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Python &amp; NumPy for physics</li>\n  <li>Plotting</li>\n  <li>Notebooks</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"solving-motion-numerically",title:"Solving Motion Numerically",subtitle:"From Euler to RK4 — drag, chaos, and N-body orbits",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Most differential equations have no closed-form solution; numerics doesn't care. Build up from Euler's method to RK4, then simulate what analytic methods can't touch: projectiles with realistic drag, the chaotic double pendulum, and gravitational N-body systems.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Euler → RK4</li>\n  <li>Projectile with drag</li>\n  <li>The double pendulum (chaos)</li>\n  <li>N-body orbits</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]},{id:"monte-carlo-methods",title:"Monte Carlo Methods",subtitle:"Random numbers as a computational superpower",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Randomness computes: Monte Carlo integration beats deterministic methods in high dimensions, and the Metropolis algorithm brings Subject 28\'s Ising model to life on screen — watching magnetization emerge and critical fluctuations diverge.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Random numbers</li>\n  <li>Monte Carlo integration</li>\n  <li>Simulating the Ising model</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"pdes-waves-numerically",title:"PDEs & Waves Numerically",subtitle:"Heat, waves, Laplace, and the Schr\xf6dinger equation on a grid",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Discretize space and time and the great PDEs of physics become loops: the heat and wave equations, relaxation methods for Laplace boundary-value problems, and the time-dependent Schr\xf6dinger equation — watch a wave packet actually tunnel.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Heat &amp; wave equations</li>\n  <li>Relaxation for Laplace</li>\n  <li>The time-dependent Schr\xf6dinger equation</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"data-and-fitting",title:"Data & Fitting",subtitle:"Least squares, uncertainty, and honest model comparison",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The experimentalist\'s essential skill set: least-squares fitting, propagating uncertainties, judging goodness of fit, and comparing models honestly — the difference between a measurement and a number.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Least squares</li>\n  <li>Uncertainty</li>\n  <li>Model comparison — real lab-analysis skills</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]}]},{id:"solid-state-physics",number:30,title:"Solid State Physics",description:"Why solids are the way they are, at the level of Simon's Oxford Solid State Basics: crystals, phonons, band theory, semiconductors, magnetism, and superconductivity.",phase:6,chapters:[{id:"bonding-crystal-structure",title:"Bonding & Crystal Structure",subtitle:"Lattices, the reciprocal lattice, and X-ray diffraction",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Crystals are nature\'s periodic tables in space. Learn the lattice language, then the reciprocal lattice — the Fourier transform of a crystal (Subject 23 pays off again) — and how X-ray diffraction reads atomic arrangements, the technique that later revealed DNA.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Lattices</li>\n  <li>The reciprocal lattice</li>\n  <li>X-ray diffraction</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"vibrations-phonons",title:"Vibrations & Phonons",subtitle:"Quantized lattice waves and the heat capacity of solids",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Atoms in a crystal vibrate collectively, and quantum mechanics quantizes those waves into phonons — particles of sound. Dispersion relations from 1D chains, then the Einstein and Debye models that finally explained solid heat capacities where classical physics failed.</p>\n<h3>Topics</h3>\n<ul>\n  <li>1D chains</li>\n  <li>Dispersion relations</li>\n  <li>Heat capacity (Einstein &amp; Debye models)</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"electrons-in-solids",title:"Electrons in Solids",subtitle:"Bloch's theorem and band structure — why metals conduct and glass doesn't",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Free electrons in a periodic potential organize into bands separated by gaps — Bloch's theorem is the key. Band filling then dictates everything: metals, insulators, and the semiconductors in between. This is Subject 26's quantum mechanics scaled to 10\xb2\xb3 particles.</p>\n<h3>Topics</h3>\n<ul>\n  <li>The free-electron gas</li>\n  <li>Bloch's theorem</li>\n  <li>Band structure</li>\n  <li>Nearly-free &amp; tight-binding models</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]},{id:"semiconductors",title:"Semiconductors",subtitle:"Doping, junctions, transistors — band theory becomes civilization",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The payoff chapter: doping engineers carriers, pn junctions rectify, transistors switch, LEDs glow, and solar cells harvest. If you\'ve taken the LearnSemi course, this is where its physics gets first-principles foundations.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Bands</li>\n  <li>Doping</li>\n  <li>pn junctions</li>\n  <li>Transistors</li>\n  <li>LEDs &amp; solar cells</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"magnetism-superconductivity",title:"Magnetism & Superconductivity",subtitle:"Collective quantum order — from ferromagnets to zero resistance",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Matter's collective quantum phases: dia-, para-, and ferromagnetism from electron spins, then superconductivity — zero resistance and expelled fields — via London theory and a glimpse of BCS pairing, ending at today's quantum materials frontier.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Dia-, para-, ferromagnetism</li>\n  <li>London theory</li>\n  <li>BCS glimpse</li>\n  <li>Quantum materials outlook</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]}]},{id:"nuclear-particle-physics",number:31,title:"Nuclear & Particle Physics",description:"From the nucleus to the Standard Model at the Griffiths/Krane level: binding energy, decay and fusion, detectors, quarks and leptons, broken symmetries, and the open questions beyond.",phase:6,chapters:[{id:"nuclear-structure",title:"Nuclear Structure",subtitle:"Binding energy, the shell model, and the valley of stability",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Inside the nucleus: the semi-empirical binding-energy curve that explains which nuclei exist, the shell model with its magic numbers (Subject 26\'s quantum mechanics in a new potential), and the systematics of nuclear stability.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Binding energy</li>\n  <li>The shell model</li>\n  <li>Stability</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"nuclear-processes",title:"Nuclear Processes",subtitle:"Decay theory, fission reactors, and fusion in stars and on Earth",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Nuclear transformation quantified: decay theory (Fermi\'s golden rule from Subject 27 in action), the controlled chain reactions inside power reactors, and fusion — the process powering every star and the goal of ITER.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Decay theory</li>\n  <li>Fission &amp; reactors</li>\n  <li>Fusion in stars and on Earth</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"particle-zoo-detectors",title:"The Particle Zoo & Detectors",subtitle:"Accelerators, detectors, and the discovery century",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>How particle physics actually happens: the accelerators that concentrate energy, the layered detectors that reconstruct collisions, and the discovery history from the positron through the muon puzzle to the quark hypothesis.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Accelerators</li>\n  <li>Detectors</li>\n  <li>The discovery history</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"standard-model",title:"The Standard Model",subtitle:"Quarks, leptons, force carriers — and how to read a Feynman diagram",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The most precisely tested theory in science: six quarks, six leptons, and the gauge bosons carrying three forces. You\'ll learn to read Feynman diagrams as physical processes and survey QED, QCD, and the weak interaction — the frontier Subject 34 formalizes.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Quarks &amp; leptons</li>\n  <li>Forces &amp; bosons</li>\n  <li>Reading Feynman diagrams</li>\n  <li>QED, QCD, weak-interaction overview</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"symmetries-conservation",title:"Symmetries & Conservation",subtitle:"Isospin, parity violation, CP, and oscillating neutrinos",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Symmetry organizes particle physics — and its violations write history: parity falls in weak decays, CP violation hints at why matter exists at all, and neutrino oscillations (a quantum interference effect light-years long) prove neutrinos have mass.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Isospin</li>\n  <li>Parity violation</li>\n  <li>CP</li>\n  <li>Neutrino oscillations</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"beyond-standard-model",title:"Beyond the Standard Model",subtitle:"The Higgs, dark matter, and the great open problems",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The 2012 Higgs discovery completed the Standard Model — and sharpened its mysteries: what is dark matter, why is the Higgs so light (the hierarchy problem), and why did matter beat antimatter? The honest state of the frontier.</p>\n<h3>Topics</h3>\n<ul>\n  <li>The Higgs discovery</li>\n  <li>Dark matter</li>\n  <li>The hierarchy problem</li>\n  <li>Baryogenesis — the open questions</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]}]},{id:"astrophysics-cosmology",number:32,title:"Astrophysics & Cosmology",description:"The universe as a physics laboratory, at the Carroll & Ostlie/Ryden level: telescopes and distances, stellar structure and death, galaxies and dark matter, and the Big Bang's evidence.",phase:6,chapters:[{id:"observing-the-universe",title:"Observing the Universe",subtitle:"Telescopes, the distance ladder, and magnitudes",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Astronomy\'s first problem is knowing how far away anything is. Climb the distance ladder from parallax to standard candles, learn the magnitude system, and survey how telescopes across the electromagnetic spectrum (and now gravitational waves) observe the cosmos.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Telescopes across the spectrum</li>\n  <li>The distance ladder</li>\n  <li>Magnitudes</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"stars",title:"Stars",subtitle:"Stellar structure, nuclear burning, and the HR diagram",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>A star is a self-gravitating fusion reactor in equilibrium — four coupled differential equations describe it entirely. Nuclear burning chains, the Hertzsprung–Russell diagram as a stellar family portrait, and the evolutionary tracks stars follow across it.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Stellar-structure equations</li>\n  <li>Nuclear burning</li>\n  <li>The HR diagram</li>\n  <li>Stellar evolution</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"stellar-endpoints",title:"Stellar Endpoints",subtitle:"White dwarfs, neutron stars, black holes, and supernovae",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>How stars die depends on mass: white dwarfs held up by electron degeneracy (Subject 28\'s Fermi gas in the sky), neutron stars spinning as pulsars, supernovae that forge the heavy elements — and black holes, where Subject 33 takes over.</p>\n<h3>Topics</h3>\n<ul>\n  <li>White dwarfs</li>\n  <li>Neutron stars &amp; pulsars</li>\n  <li>Astrophysical black holes</li>\n  <li>Supernovae</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"galaxies-large-scale-structure",title:"Galaxies & Large-Scale Structure",subtitle:"The Milky Way, galaxy types, and the case for dark matter",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Zoom out to galaxies: our Milky Way's anatomy, Hubble's classification, and the flat rotation curves plus cluster dynamics and lensing that make dark matter the most parsimonious explanation — evidence you can now weigh critically.</p>\n<h3>Topics</h3>\n<ul>\n  <li>The Milky Way</li>\n  <li>Galaxy types</li>\n  <li>The dark-matter evidence</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]},{id:"cosmology",title:"Cosmology",subtitle:"The expanding universe — Big Bang nucleosynthesis, the CMB, and dark energy",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The universe has a history: Hubble expansion, the primordial furnace that fixed the light-element abundances, the cosmic microwave background\'s baby picture, and the accelerating expansion attributed to dark energy — assembled into the remarkably precise ΛCDM timeline.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Hubble expansion</li>\n  <li>The FRW universe</li>\n  <li>Big Bang nucleosynthesis</li>\n  <li>The CMB</li>\n  <li>Dark energy</li>\n  <li>Inflation</li>\n  <li>The timeline of the universe</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]}]},{id:"general-relativity",number:33,title:"General Relativity",description:"Einstein's theory of gravity at the Hartle/Schutz 'physics-first' level: curved spacetime, the field equations, black holes, gravitational waves, and relativistic cosmology.",phase:6,chapters:[{id:"mathematics-of-curved-spacetime",title:"The Mathematics of Curved Spacetime",subtitle:"Metrics, tensors, geodesics, and curvature",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The language first: metrics measure spacetime, tensors (Subject 23\'s index gymnastics, now essential) keep equations frame-independent, geodesics are the straightest possible paths, and the covariant derivative quantifies curvature.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Manifolds &amp; metrics</li>\n  <li>Tensors properly</li>\n  <li>Geodesics</li>\n  <li>Covariant derivative &amp; curvature</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"equivalence-to-field-equations",title:"From Equivalence Principle to Field Equations",subtitle:"Einstein's 'happiest thought' becomes G = 8πT",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Free fall feels like no gravity at all — from that equivalence principle, Einstein reasoned his way to the field equations: matter tells spacetime how to curve, spacetime tells matter how to move. The weak-field limit recovers Newton, as it must.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Newton → Einstein</li>\n  <li>The Einstein equations</li>\n  <li>The weak-field limit</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"schwarzschild-solution",title:"The Schwarzschild Solution",subtitle:"The classic tests — precession, light bending, redshift, GPS",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The first exact solution describes spacetime outside any spherical mass. From it: Mercury\'s anomalous perihelion precession explained, starlight bending measured in 1919, gravitational redshift — and the GPS corrections without which navigation would drift kilometers per day.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Orbits</li>\n  <li>Perihelion precession</li>\n  <li>Light bending</li>\n  <li>Gravitational redshift</li>\n  <li>GPS revisited</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"black-holes",title:"Black Holes",subtitle:"Event horizons, rotating Kerr holes, and Hawking's thermodynamics",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Where Schwarzschild's solution turns extreme: event horizons as one-way membranes, the rotating Kerr geometry that real astrophysical black holes follow, and black-hole thermodynamics — Hawking radiation's still-unresolved challenge to quantum theory.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Event horizons</li>\n  <li>The Kerr glimpse</li>\n  <li>Black-hole thermodynamics (Hawking glimpse)</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]},{id:"gravitational-waves",title:"Gravitational Waves",subtitle:"Ripples in spacetime — the physics of LIGO",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Linearize Einstein\'s equations and spacetime waves: stretching space by parts in 10\xb2\xb9, detected at last in 2015. The interferometry of LIGO, the chirp of merging black holes, and the multimessenger astronomy the discovery unlocked.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Linearized theory</li>\n  <li>The physics of LIGO</li>\n  <li>Multimessenger astronomy</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"relativistic-cosmology",title:"Relativistic Cosmology",subtitle:"The Friedmann equations — the universe as a GR solution",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Apply Einstein's equations to the universe itself: the FRW metric from symmetry, the Friedmann equations governing expansion, and the cosmological constant Einstein regretted — now resurrected as dark energy. Subject 32's observational cosmology gets its theoretical engine.</p>\n<h3>Topics</h3>\n<ul>\n  <li>FRW derived</li>\n  <li>The Friedmann equations</li>\n  <li>The cosmological constant</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]}]},{id:"quantum-fields-frontier",number:34,title:"Quantum Fields & the Frontier",description:"The gateway course (Lancaster & Blundell level): why fields replace particles, quantization and Feynman diagrams, gauge symmetry and the Higgs, and an honest map of what physics doesn't know.",phase:6,chapters:[{id:"why-fields",title:"Why Fields",subtitle:"Relativity + quantum mechanics forces field theory",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Marry special relativity to quantum mechanics and single-particle theories break — particle number won't stay fixed. The resolution: fields are fundamental, particles are their excitations. Creation and annihilation operators (Subject 26's ladder algebra promoted) make it precise.</p>\n<h3>Topics</h3>\n<ul>\n  <li>The problems of relativistic QM</li>\n  <li>Creation &amp; annihilation</li>\n  <li>The second-quantization idea</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]},{id:"canonical-quantization-taste",title:"A Taste of Canonical Quantization",subtitle:"The Klein–Gordon field as infinitely many oscillators",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Quantize the simplest relativistic field: the Klein–Gordon field decomposes into harmonic oscillators (one per momentum), and quantizing each yields particles as quanta. The harmonic oscillator you\'ve now solved four ways turns out to be the foundation of reality.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Klein–Gordon</li>\n  <li>The quantum field as a set of oscillators</li>\n  <li>Particles as excitations</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"interactions-feynman-diagrams",title:"Interactions & Feynman Diagrams",subtitle:"What the diagrams really mean",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Add interactions and exact solutions vanish; perturbation theory returns with Feynman's diagrams as its bookkeeping — each line and vertex a factor in an amplitude, 'virtual particles' revealed as terms in an expansion rather than magic.</p>\n<h3>Topics</h3>\n<ul>\n  <li>What the perturbation expansion means</li>\n  <li>Virtual particles</li>\n  <li>Reading simple amplitudes</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]},{id:"gauge-symmetry-standard-model",title:"Gauge Symmetry & the Standard Model",subtitle:"Demanding local symmetry creates the forces",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>The Standard Model's deepest idea: demand that quantum phases can be chosen independently at every point in spacetime, and forces must exist — U(1) gauge symmetry generates electromagnetism. The Higgs mechanism then explains mass without breaking the symmetry's benefits.</p>\n<h3>Topics</h3>\n<ul>\n  <li>The U(1) gauge idea → QED</li>\n  <li>The Higgs mechanism conceptually</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]},{id:"open-frontier",title:"The Open Frontier",subtitle:"Renormalization, quantum gravity, and your graduate roadmap",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The course — and this curriculum — ends honestly: renormalization\'s modern meaning, why gravity resists quantization, the contenders (strings, loops), and what nobody knows. Plus the graduate roadmap: Jackson, Sakurai, Peskin, Carroll — you now have the foundations to attempt them all.</p>\n<h3>Topics</h3>\n<ul>\n  <li>The renormalization idea</li>\n  <li>The quantum-gravity problem</li>\n  <li>Strings &amp; loops glimpse</li>\n  <li>The graduate roadmap (Jackson, Sakurai, Peskin, Carroll)</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]}]}].map((e,t)=>({...e,...a[t]}));function o(e){let t=s.find(t=>t.id===e);return t?t.chapters.reduce((e,t)=>e+t.sections.length,0):0}function r(e){return s.find(t=>t.id===e)}function l(e,t){let i=r(e);return null==i?void 0:i.chapters.find(e=>e.id===t)}function h(e){return n[e.phase-1]}function c(e,t){let i=r(e);if(!i)return null;let n=i.chapters.findIndex(e=>e.id===t);if(n<i.chapters.length-1)return{subjectId:e,chapterId:i.chapters[n+1].id};let a=s.findIndex(t=>t.id===e);if(a<s.length-1){let e=s[a+1];return{subjectId:e.id,chapterId:e.chapters[0].id}}return null}function d(e,t){let i=r(e);if(!i)return null;let n=i.chapters.findIndex(e=>e.id===t);if(n>0)return{subjectId:e,chapterId:i.chapters[n-1].id};let a=s.findIndex(t=>t.id===e);if(a>0){let e=s[a-1];return{subjectId:e.id,chapterId:e.chapters[e.chapters.length-1].id}}return null}}}]);